import httpx;

import from .utils { sumObjectsByKey }

glob DISTRICT_VALUES: list[str] = [
    "alappuzha",
    "ernakulam",
    "idukki",
    "kannur",
    "kasaragod",
    "kollam",
    "kottayam",
    "kozhikode",
    "malappuram",
    "palakkad",
    "pathanamthitta",
    "thiruvananthapuram",
    "thrissur",
    "wayanad",
];

async def:pub getHistories() -> dict[str, object] {
    res = await httpx.get("https://keralastats.coronasafe.live/histories.json");
    return res.json() as dict[str, object];
}

async def:pub getHotspotsHistories() -> dict[str, object] {
    res = await httpx.get("https://keralastats.coronasafe.live/hotspots_histories.json");
    return res.json() as dict[str, object];
}

async def:pub getTestReports() -> list[dict[str, object]] {
    res = await httpx.get("https://keralastats.coronasafe.live/testreports.json");
    data = res.json() as dict[str, object];
    return data["reports"] as list[dict[str, object]];
}

async def:pub getMetaProps() -> dict[str, object] {
    histories_data = await getHistories();
    lastUpdated = histories_data["lastUpdated"] as str;
    districtHistories = histories_data["histories"] as list[dict[str, object]];
    hotspots_data = await getHotspotsHistories();
    hotspotsHistories = hotspots_data["histories"] as list[dict[str, object]];
    testReportHistories = await getTestReports();
    histories: list[dict[str, object]] = [];
    for i in districtHistories {
        delta_objs = [i["delta"][d] as dict[str, int] for d in DISTRICT_VALUES];
        delta = sumObjectsByKey(delta_objs);
        summary_objs = [i["summary"][d] as dict[str, int] for d in DISTRICT_VALUES];
        summary = sumObjectsByKey(summary_objs);
        histories = histories + [{"date": i["date"], "delta": delta, "summary": summary}];
    }
    return {
        "histories": histories,
        "districtHistories": districtHistories,
        "lastUpdated": lastUpdated,
        "hotspotsHistories": hotspotsHistories,
        "testReportHistories": testReportHistories,
    };
}

