    const updateCoinsOfPlayer = await prisma.user.update({
        where: {
            id: userId
        },
        data: {
            coins: {
                increment: amount // use variable amount sent via url params
            }
        }
    })

    // return updateCoinsOfPlayer as a json
    return NextResponse.json(updateCoinsOfPlayer);
}

