        }

        const regex = new RegExp(`${this.fieldName} ge ([0-9.]+) and ${this.fieldName} le ([0-9.]+)`, 'gi');
        const match = regex.exec(filterClause);
        return !match ? null : [Number(match[1]), Number(match[2])];
    }
