        }
        type="button"
        onClick={async () => {
          if (!isLoggedIn) navigate('/login');
          setDisabled(true);
          following ? await unfollow() : await follow();
          setDisabled(false);
        }}
      >
        <i className="ion-plus-round"></i>
        &nbsp;
        {following ? 'Unfollow' : 'Follow'} {username}
      </button>
    </>
  );
};

