import os;
import glob as glob_module;
import shutil;

type ErrResult[T] = tuple[Exception | None, T | None];

obj FileSystem {
    has readFile: Callable[[str], ErrResult[str]];
    has writeFile: Callable[[str, str], ErrResult[None]];
    has unlink: Callable[[str], ErrResult[None]];
    has copyFile: Callable[[str, str], ErrResult[None]];
    has glob: Callable[[str], ErrResult[list[str]]];
    has mkdir: Callable[[str], ErrResult[None]];
    has moveFile: Callable[[str, str], ErrResult[None]];
}

def _readFile(path: str) -> ErrResult[str] {
    try {
        with open(path, encoding="utf8") as f {
            return (None, f.read());
        }
    } except OSError as e {
        return (e, None);
    }
}

def _writeFile(path: str, content: str) -> ErrResult[None] {
    try {
        with open(path, "w", encoding="utf8") as f {
            f.write(content);
        }
        return (None, None);
    } except OSError as e {
        return (e, None);
    }
}

def _unlink(path: str) -> ErrResult[None] {
    try {
        os.unlink(path);
        return (None, None);
    } except OSError as e {
        return (e, None);
    }
}

def _copyFile(src: str, dst: str) -> ErrResult[None] {
    try {
        shutil.copyfile(src, dst);
        return (None, None);
    } except OSError as e {
        return (e, None);
    }
}

def _glob(pattern: str) -> ErrResult[list[str]] {
    try {
        return (None, glob_module.glob(pattern));
    } except OSError as e {
        return (e, None);
    }
}

def _mkdir(path: str) -> ErrResult[None] {
    try {
        os.makedirs(path, exist_ok=True);
        return (None, None);
    } except OSError as e {
        return (e, None);
    }
}

def _moveFile(src: str, dst: str) -> ErrResult[None] {
    try {
        os.rename(src, dst);
        return (None, None);
    } except OSError as e {
        return (e, None);
    }
}

glob fileSystem: FileSystem = FileSystem(
    readFile=_readFile,
    writeFile=_writeFile,
    unlink=_unlink,
    copyFile=_copyFile,
    glob=_glob,
    mkdir=_mkdir,
    moveFile=_moveFile
);

