import from "@/lib/utils" { cn }

glob MIN_POSSIBLE_SCORE: float = 40.0;
glob MIN_BAR_PERCENT: float = 6.0;

obj TrendWeek {
    has weeksAgo: int,
        score: int | None,
        analyzed: int,
        messages: int;
}

def barHeightPercent(score: int) -> float {
    ofRange = ((float(score) - MIN_POSSIBLE_SCORE) / (100.0 - MIN_POSSIBLE_SCORE)) * 100.0;
    return ofRange if ofRange > MIN_BAR_PERCENT else MIN_BAR_PERCENT;
}

def:pub TrendChart(weeks: list[TrendWeek]) -> JsxElement {
    scoredWeeks = [week for week in weeks if week.score is not None];
    if len(scoredWeeks) < 2 {
        return <></>;
    }
    <figure className="mt-5">
        <div className="flex h-24 items-end gap-1.5" aria-hidden="true">
            {for week in weeks {
                <div
                    key={week.weeksAgo}
                    className="flex flex-1 flex-col justify-end"
                    title={"No messages graded" if week.score is None else f"{week.score} / 100 across {week.analyzed} messages"}
                >
                    {if week.score is None {
                        <div className="h-1.5 rounded-full bg-foreground/5" />
                    } else {
                        <div
                            className={cn(
                                "rounded-lg transition-[height] duration-500",
                                "bg-foreground/70" if week.weeksAgo == 0 else "bg-foreground/20",
                            )}
                            style={{"height": f"{barHeightPercent(week.score)}%"}}
                        />
                    }}
                </div>
            }}
        </div>
        <figcaption className="mt-2 flex justify-between text-muted-foreground text-xs">
            <span>{len(weeks)}{" weeks ago"}</span>
            <span>This week</span>
        </figcaption>
    </figure>
}

