def review(reviewedText: str, tips: list[CoachTip]) -> dict[str, object] {
    return {"reviewedText": reviewedText, "tips": tips};
}

test "tipsForMessage shows nothing until the AI coach has analyzed the message" {
    assert tipsForMessage({"tips": None}) == [];
}

test "tipsForMessage returns exactly the stored analysis, including analyzed-and-clean" {
    assert tipsForMessage({"tips": [fix]}) == [fix];
    assert tipsForMessage({"tips": []}) == [];
}

test "rewriteForMessage only ever offers the AI's stored rewrite, for user messages" {
    assert rewriteForMessage({"author": "user", "rewrite": "Hello there."}) == "Hello there.";
    assert rewriteForMessage({"author": "user"}) == None;
    assert rewriteForMessage({"author": "persona", "rewrite": "x"}) == None;
}

test "summarizeSession score averages per-message quality with severity penalties" {
    oneFix = [{**fix}];
    result = summarizeSession(
        conversation([message("user", []), message("user", oneFix)])
    );
    assert result["score"] == int((100 + 85) / 2 + 0.5);
}

test "summarizeSession score floors a heavily marked message at 40" {
    pileOn = [{**fix} for _ in range(10)];
    result = summarizeSession(conversation([message("user", pileOn)]));
    assert result["score"] == 40;
}

test "summarizeSession score ignores unanalyzed messages' tips but still counts them as sent" {
    result = summarizeSession(
        conversation([message("user"), message("persona", [])])
    );
    assert result["sent"] == 1;
    assert result["score"] == 100;
}

test "draftMarks returns tips unchanged when the draft has no leading whitespace" {
    assert draftMarks("idk yet", review("idk yet", [fix])) == [fix];
}

test "draftMarks shifts spans past leading whitespace the coach never saw" {
    marks = draftMarks("\n  idk yet", review("idk yet", [fix]));
    assert marks == [{**fix, "start": 3, "end": 6}];
}

test "draftMarks keeps marks while only trailing whitespace is added" {
    assert draftMarks("idk yet  ", review("idk yet", [fix])) == [fix];
}

test "draftMarks drops every mark once the draft text itself changes" {
    assert draftMarks("idk yet more", review("idk yet", [fix])) == [];
}

test "draftMarks has nothing to place when the coach found nothing" {
    assert draftMarks("idk yet", review("idk yet", [])) == [];
}

