                </p>
            </div>
        );
    }

    user_submitted = user["submitted"] as list[int] if user.get("submitted") else [];
    total_submissions = len(user_submitted);
    has_more = loaded_count < total_submissions;
    user_id = user["id"] as str;
    user_created = user.get("created");
    user_karma = user.get("karma");
