import { useState, useEffect, Dispatch, SetStateAction } from 'react'
import { getStorageItem, setStorageItem } from 'utils/local-storage'

type Response<T> = [T, Dispatch<SetStateAction<T>>]

export function usePersistedState<T>(
  key: string,
  initialState: T
): Response<T> {
  const [state, setState] = useState(() => {
    const storageValue = getStorageItem(key)

    if (storageValue) {
      return storageValue
    } else {
      return initialState
    }
  })

  useEffect(() => {
    setStorageItem(key, state)
  }, [key, state])

  return [state, setState]
}

jac:
import from "utils/local-storage" { getStorageItem, setStorageItem }

def:pub usePersistedState[T](key: str, initialState: T) -> list[object] {
    statePair = useState(lambda () -> object {
        storageValue = getStorageItem(key);
        if storageValue {
            return storageValue;
        }
        return initialState;
    });
    state = statePair[0];
    setState = statePair[1];
    useEffect(lambda () -> None { setStorageItem(key, state); }, [key, state]);
    return [state, setState];
}

