import math;
import secrets;

def:pub pickRandomFromArray(array: str) -> str {
    return array[getRandomInt(0, len(array))];
}

def:pub getRandomInt(min: int, max: int) -> int {
    return secrets.randbelow(max - min) + min;
}

def:pub shuffleString(str: str) -> str {
    arr = list(str);
    i = len(arr) - 1;
    while i > 0 {
        j = getRandomInt(0, i + 1);
        tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
        i -= 1;
    }
    return "".join(arr);
}

def:pub getBooleanSequence(length: int) -> list[bool] {
    arr = secrets.token_bytes(int(math.ceil(length / 8)));
    result: list[bool] = [];
    for i in range(length) {
        byte = arr[i // 8];
        bit = byte & (1 << (i % 8));
        result.append(bit != 0);
    }
    return result;
}

