obj CalendarDate {
    has year: int;
    has month: int;
    has day: int;
}

glob calendarMonthNames: list[str] = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
];

def calendarDaysInMonth(month: int, year: int) -> int {
    return (new(Date, year, month + 1, 0).getDate()) as int;
}

def calendarBuildTotalDays(daysInMonth: int) -> list[int] {
    maxElementsInGrid = 35;
    lastDayFourthRow = 28;
    days = [d for d in range(1, daysInMonth + 1)];
    if len(days) > lastDayFourthRow {
        diff = maxElementsInGrid - daysInMonth;
        restOfDays = [d for d in range(1, diff + 1)];
        return days + restOfDays;
    }
    return days;
}

def:pub Calendar(
    closeCalendar: Callable[[], None],
    handleClickDate: Callable[[int, int, int], None],
    initialDate: CalendarDate
) -> JsxElement {
    has dateInCalendar: CalendarDate = CalendarDate(
        year=initialDate.year,
        month=initialDate.month,
        day=initialDate.day
    );
    has monthCounter: int = initialDate.month;
    has yearCounter: int = initialDate.year;

    can with (monthCounter, yearCounter) entry {
        dateInCalendar = CalendarDate(year=yearCounter, month=monthCounter, day=1);
    }

    def handlePrevMonth(_e: MouseEvent) {
        if monthCounter == 0 {
            monthCounter = 11;
            yearCounter = yearCounter - 1;
        } else {
            monthCounter = monthCounter - 1;
        }
    }

    def handleNextMonth(_e: MouseEvent) {
        if monthCounter == 11 {
            monthCounter = 0;
            yearCounter = yearCounter + 1;
        } else {
            monthCounter = monthCounter + 1;
        }
    }

    month = dateInCalendar.month;
    year = dateInCalendar.year;
    daysInMonth = calendarDaysInMonth(month, year);
    totalDaysToRender = calendarBuildTotalDays(daysInMonth);
    nameMonth = calendarMonthNames[month];

    def isDaySelected(day: int, selMonth: int, selYear: int) -> bool {
        return (
            initialDate.day == day
            and initialDate.month == selMonth
            and initialDate.year == selYear
        );
    }

    def isWithinTheMonth(index: int, dim: int) -> bool {
        return index < dim;
    }

    def getColorDay(index: int, day: int, colorMonth: int, colorYear: int) -> str {
        if isWithinTheMonth(index, daysInMonth) {
            if isDaySelected(day, colorMonth, colorYear) {
                return "text-brand-violet";
            }
            return "text-brand-text dark:text-brand-white";
        }
        return "text-brand-text-muted pointer-events-none";
    }

    def handleDayClick(day: int, clickMonth: int, clickYear: int) {
        handleClickDate(day, clickMonth, clickYear);
        closeCalendar();
    }

    <div className="w-full flex flex-col items-center gap-5 h-[243px] px-[18px] max-w-[240px] self-start brand-md:self-center rounded-lg mt-4 dark:bg-brand-gray-muted absolute bg-brand-white">
        <div className="flex justify-between tracking-tight w-[193px] h-[15px] text-fontSize-xs line-height-[15px] pt-[25px] pb-[32px]">
            <div className="cursor-pointer font-bold p-1" onClick={handlePrevMonth}>
                <img src="./assets/images/icon-arrow-left.svg" alt="Left arrow" />
            </div>
            <p>{nameMonth} {year}</p>
            <div className="cursor-pointer font-bold p-1" onClick={handleNextMonth}>
                <img src="./assets/images/icon-arrow-right.svg" alt="Right arrow" />
            </div>
        </div>
        <div className="text-lg grid grid-cols-7 w-[203px] h-[139px]" role="calendar">
            {for (i, day) in enumerate(totalDaysToRender) {
                <div
                    key={str(i)}
                    onClick={lambda (_e: MouseEvent) { handleDayClick(day, month, year); }}
                    className={"hover:cursor-pointer hover:text-brand-violet dark:hover:text-brand-violet text-center font-bold text-sm h-[15px] " + getColorDay(i, day, month, year)}
                    role="day"
                >
                    {day}
                </div>
            }}
        </div>
    </div>
}

