    validateOptions(options);
    password: str = getRequiredCharacters(options);
    availableCharacters: str = getAvailableCharacters(options);
    while len(password) < options.length {
        character: str = pickRandomFromArray(availableCharacters) as str;
        if options.excludeRepeating and (character in password) {
            continue;
        }
        password += character;
    }
    password = shuffleString(password) as str;
    if options.separator and options.separatorInterval {
        password = addSeparator(password, options.separator, options.separatorInterval);
    }
    return password;
}

