def defaultHandler(state: object | None) -> object {
    return state;
}

glob defaultConfig = {"defaultHandler": defaultHandler};

def formatKey(key: str) -> str {
    return str(key).upper();
}

class ActionHandlerFactory {
    has defaultHandler: Callable[[object | None], object];
    has handlers: dict[str, Callable[[object | None, dict], object]];

    def init(config: dict | None = None) {
        if config is None {
            config = defaultConfig;
        }
        cfgDefault = config.get("defaultHandler");
        self.defaultHandler = cfgDefault if cfgDefault else defaultHandler;
        self.handlers = {};
    }

    def register(key: str, handler: Callable[[object | None, dict], object]) {
        self.handlers[formatKey(key)] = handler;
    }

    def getHandler(key: str) -> Callable[[object | None, dict], object] {
        handler = self.handlers.get(formatKey(key));
        if handler {
            return handler;
        }
        return self.defaultHandler;
    }
}

glob:pub default = ActionHandlerFactory;

