          anchor={direction === "rtl" ? "right" : "left"}
          open={mobileOpen}
          onClose={handleDrawerToggle}
          slotProps={{
            paper: {
              sx: drawerPaperSx,
            },
          }}
          ModalProps={{
            keepMounted: true, // Better open performance on mobile.
          }}
