import from "@/shared/components/helpers" { FormikTextField, SubmitButton }

glob defaultInitialValues = {"title": ""};

def folderFormBody(formikBag: dict[str, object]) -> JsxElement {
    isSubmitting = formikBag["isSubmitting"] as bool;
    submitForm = formikBag["submitForm"] as Callable[[], None];
    return <Form><Field type="text" name="title" label="Title" margin="normal" fullWidth component={FormikTextField} /><SubmitButton disabled={isSubmitting} onClick={submitForm} /></Form>;
}

def:pub FolderForm(props: dict[str, object]) -> JsxElement {
    initialValues = defaultInitialValues;
    if "initialValues" in props {
        initialValues = props["initialValues"] as dict[str, str];
    }
    handleSubmit = props["handleSubmit"] as Callable[[dict[str, str]], None];
    return <Formik initialValues={initialValues} onSubmit={handleSubmit}>{folderFormBody}</Formik>;
}

