def:pub OtpForm(className: str = "") -> JsxElement {
    nav = useNavigate();
    has isLoading: bool = False;
    has disabledBtn: bool = True;
    has otp: str = "";

    def handle_complete() {
        disabledBtn = False;
    }

    def handle_incomplete() {
        disabledBtn = True;
    }

    def onSubmit(e: FormEvent) {
        e.preventDefault();
        isLoading = True;
        toast({
            "title": "You submitted the following values:",
            "description": <pre className="mt-2 w-[340px] rounded-md bg-slate-950 p-4">
                <code className="text-white">{JSON.stringify({"otp": otp})}</code>
