    <div className={cn("grid gap-6", className)}>
        <form onSubmit={onSubmit}>
            <div className="grid gap-2">
                <PinInput
                    value={otp}
                    className="flex h-10 justify-between"
                    onComplete={handle_complete}
                    onIncomplete={handle_incomplete}
