function sanitize(string: string) {
  const map: any = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;',
    '/': '&#x2F;',
    '.': '_', // https://github.com/react-hook-form/react-hook-form/issues/676
  }
  const reg = /[&<>"'/\.]/gi
  return string.replace(reg, (match: string) => map[match])
}

export { sanitize }

jac:
def:pub sanitize(string: str) -> str {
    escapes: dict[str, str] = {
        "&": "&amp;",
        "<": "&lt;",
        ">": "&gt;",
        "\"": "&quot;",
        "'": "&#x27;",
        "/": "&#x2F;",
        ".": "_",
    };
    result = "";
    for ch in string {
        if ch in escapes {
            result += escapes[ch];
        } else {
            result += ch;
        }
    }
    return result;
}

