obj CreateContextOptions {
    has session: object | None = None;
}

def createInnerTRPCContext(opts: CreateContextOptions) -> dict[str, object] {
    return {"session": opts.session, "prisma": prisma};
}

async def:pub createTRPCContext(opts: dict[str, object]) -> dict[str, object] {
    req = opts["req"];
    res = opts["res"];
    session = await getServerAuthSession({"req": req, "res": res});
