import React from "react";
import {BarTask} from "../../../types/bar-task";

type LinkProps ={
  taskFrom: any,
  taskTo: any
}

const drownPathAndTriangle = (
  taskFrom: BarTask,
  taskTo: BarTask,
  rowHeight: number,
  taskHeight: number,
  arrowIndent: number
) => {
  const indexCompare = taskFrom?.index > taskTo?.index ? -1 : 1;
  const taskToEndPosition = taskTo.y + 10 + taskHeight / 2;
  const taskFromEndPosition = taskFrom.x2 + arrowIndent * 2;
  const taskFromHorizontalOffsetValue =
    taskFromEndPosition < taskTo.x1 ? "" : `H ${taskTo.x1 - arrowIndent}`;
  const taskToHorizontalOffsetValue =
    taskFromEndPosition > taskTo.x1
      ? arrowIndent
      : taskTo.x1 - taskFrom.x2 - arrowIndent;

  const path = `M ${taskFrom.x2} ${taskFrom.y + 10 + taskHeight / 2}
  h ${arrowIndent}
  v ${(indexCompare * rowHeight) / 2}
  ${taskFromHorizontalOffsetValue}
  V ${taskToEndPosition}
  h ${taskToHorizontalOffsetValue}`;

  const trianglePoints = `${taskTo.x1},${taskToEndPosition}
  ${taskTo.x1 - 5},${taskToEndPosition - 5}
  ${taskTo.x1 - 5},${taskToEndPosition + 5}`;
  return [path, trianglePoints];
};

export const LinkLine : React.FC<LinkProps> = (
  {
    taskFrom,
    taskTo
  }
) => {

  let path: string;
  let trianglePoints: string;

  [path, trianglePoints] = drownPathAndTriangle(
    taskFrom,
    taskTo,
    56,
    46,
    20
  );

  return (
    <g className="arrow" fill="grey" stroke="grey">
      <path strokeWidth="1.5" d={path} fill="none" />
      <polygon points={trianglePoints} />
    </g>
  )
}

jac:
obj BarTask {
    has index: int = 0;
    has x1: float = 0.0;
    has x2: float = 0.0;
    has y: float = 0.0;
}

def drownPathAndTriangle(
    taskFrom: BarTask,
    taskTo: BarTask,
    rowHeight: float,
    taskHeight: float,
    arrowIndent: float
) -> list[str] {
    indexCompare = -1 if (taskFrom.index > taskTo.index) else 1;
    taskToEndPosition = taskTo.y + 10 + (taskHeight / 2);
    taskFromEndPosition = taskFrom.x2 + (arrowIndent * 2);
    taskFromHorizontalOffsetValue = "" if (taskFromEndPosition < taskTo.x1) else f"H {taskTo.x1 - arrowIndent}";
    taskToHorizontalOffsetValue = arrowIndent if (taskFromEndPosition > taskTo.x1) else (taskTo.x1 - taskFrom.x2 - arrowIndent);
    path = f"M {taskFrom.x2} {taskFrom.y + 10 + (taskHeight / 2)}\n  h {arrowIndent}\n  v {(indexCompare * rowHeight) / 2}\n  {taskFromHorizontalOffsetValue}\n  V {taskToEndPosition}\n  h {taskToHorizontalOffsetValue}";
    trianglePoints = f"{taskTo.x1},{taskToEndPosition}\n  {taskTo.x1 - 5},{taskToEndPosition - 5}\n  {taskTo.x1 - 5},{taskToEndPosition + 5}";
    return [path, trianglePoints];
}

def:pub LinkLine(taskFrom: BarTask, taskTo: BarTask) -> JsxElement {
    (path, trianglePoints) = drownPathAndTriangle(taskFrom, taskTo, 56, 46, 20);
    <g className="arrow" fill="grey" stroke="grey">
        <path strokeWidth="1.5" d={path} fill="none" />
        <polygon points={trianglePoints} />
    </g>
}

