    eY: int = model.eY if model.eY else 0;
    i: int = -33;
    if sY > eY {
        i = -7;
    }
    sY = sY - 21;
    eY = eY + i;
    path: str = "";

    if sY == eY {
        path = f"""
     M {sX} {sY}
     h {eX - sX}
    """;
    } else {
        path = f"""
     M {sX} {sY}
     h {eX - sX}
     v {eY - sY}
    """;
        if model.flag {
            path = f"""
       M {sX} {sY}
