import re;
import from main.files.parse_html { Section }

async def readFileUtf8(filePath: str) -> str {
    with open(filePath, "r", encoding="utf-8") as f {
        return f.read();
    }
}

async def parseTxt(filePath: str) -> list[Section] {
    data = await readFileUtf8(filePath);
    lines = data.split("\n");
    chunks: list[str] = [];
    sentenceEndings = r"(?<!\b(?:Mr|Mrs|Ms|Dr|Sr|Sra|Jr)\.)(?<!\b[A-Za-z]\.)(?<!\w\.\w.)(?<=\.|\?|!)(?=\s+[A-Z]|\s*$)";

    for line in lines {
        parts = re.split(sentenceEndings, line);
        chunks.extend(parts);
    }

    content = [chunk for chunk in chunks if chunk != ""];
    return [Section(section=content[0], content=content)];
}

