import re;
import unicodedata;
import from datetime { datetime }

glob:pub categoryLabelByKey: dict[str, str] = {
    "aiAgents": "AI Agents",
    "rag": "RAG",
    "webScraping": "Web Scraping",
    "travelPlanning": "Travel Planning",
    "llmIntegration": "LLM Integration",
    "dataAnalytics": "Data Analytics",
};

type ProjectFilters = dict[str, object];

def:pub normalizeText(value: str) -> str {
    normalized = unicodedata.normalize("NFKD", value.strip().lower());
    return re.sub(r"[\u0300-\u036f]", "", normalized);
}

def:pub deriveCategoryMap(topicClusters: dict[str, list[str]] | None) -> dict[str, str] {
    map: dict[str, str] = {};
    if topicClusters is None { return map; }
    for (clusterKey, projectIds) in topicClusters.items() {
        label = categoryLabelByKey[clusterKey] if clusterKey in categoryLabelByKey else clusterKey;
        for id in projectIds {
            if id not in map { map[id] = label; }
        }
    }
    return map;
}

def parseUpdatedAtMs(value: str) -> float {
    try {
        return datetime.strptime(value, "%Y-%m-%d").timestamp() * 1000.0;
    } except ValueError {
        return 0.0;
    }
}

def:pub filterProjects(projects: list[dict[str, object]], filters: ProjectFilters) -> list[dict[str, object]] {
    q = normalizeText(filters["q"] as str);
    hasQuery = len(q) > 0;
    langKey = (filters["lang"] as str).lower();
    result: list[dict[str, object]] = [];
    for project in projects {
        if filters["category"] as str != "all" and project["category"] as str != filters["category"] as str { continue; }
        language = project["language"];
        langValue = "" if language is None else language as str;
        if filters["lang"] as str != "all" and langValue.lower() != langKey { continue; }
        if project["stars"] as int < filters["minStars"] as int { continue; }
        if not hasQuery { result.append(project); continue; }
        haystack = normalizeText(" ".join([
            project["title"] as str,
            project["description"] as str,
            project["category"] as str,
            langValue,
            " ".join(project["topics"] as list[str]),
            " ".join(project["tags"] as list[str]),
        ]));
        if q in haystack { result.append(project); }
    }
    return result;
}

def:pub sortProjects(projects: list[dict[str, object]], sort: str) -> list[dict[str, object]] {
    sorted = [*projects];
    if sort == "stars" {
        sorted.sort(key=lambda (p: dict[str, object]) { return (-(p["stars"] as int), (p["title"] as str).lower()); });
    } elif sort == "updated" {
        sorted.sort(key=lambda (p: dict[str, object]) { return (-parseUpdatedAtMs(p["updatedAt"] as str), -(p["stars"] as int)); });
    } else {
        sorted.sort(key=lambda (p: dict[str, object]) { return (p["title"] as str).lower(); });
    }
    return sorted;
}

