import from "./types.jac" { createWarning, Warning }
import from "./context.jac" { isBlockLayoutDisplay, isDefaultSelfAlignmentValue, isMulticolContainer }

glob RULE_ID = "item-no-justify-self";

def warn(fields: dict[str, str]) -> Warning {
    return createWarning(RULE_ID, fields);
}

def isNonBlockLevelBox(display: str) -> bool {
    nonBlockDisplays = [
        "inline", "inline-block", "inline-flex", "inline-grid", "inline-table",
        "ruby", "table-row", "table-cell", "table-row-group",
        "table-header-group", "table-footer-group", "table-column",
