    action: ShowActions
) -> IShowState {
    switch action["type"] {
        case SHOW_MORE:
            return {**state, "list": {**action["payload"] as dict[str, bool]}};
            break;
        case SWITCH_KANBAN:
            return {**state, "kanban": action["payload"] as bool};
            break;
        default:
            return state;
            break;
    }
}

