import from "redux" { Dispatch }
import from "store/tasks/types" { FETCH_TASKS, DELETE_TASK, DRAG_AND_DROP, ITasksDragAndDropAction, ITasksDeleteTasksAction }

def:pub dragAndDrop(e: dict[str, object], type: str) -> ITasksDragAndDropAction {
    return {"type": DRAG_AND_DROP, "payload": {"e": e, "type": type}};
