        try {
            response = await instance.get("tasks.json");
            data = response["data"];
            dispatch({"type": FETCH_TASKS, "payload": data});
        } except Exception as err {
            print(f"[Action: fetchTasks] - {err}");
        }
    }
    return thunk;
