def:pub Tabs(isScrollable: bool | None = None, data: list[dict[str, object]] | None = None) -> JsxElement {
    has value: int = 0;
    tabs_data = data or [];

    can with entry {
        hash = window.location.hash.replace("#/", "");
        value = 0;
        if tabs_data {
            for (index, item) in enumerate(tabs_data) {
                if item.get("id") == hash {
                    value = index;
                }
            }
        }
    }

    def handle_change(_event: object, new_value: int) {
        item = tabs_data[new_value];
        hash_id = item.get("id") if item.get("id") else new_value;
        window.location.hash = "#/" + str(hash_id);
        value = new_value;
    }

    <div className="tabs-root">
        <AppBar position="static" color="default">
            <MaterialTabs
                value={value}
                onChange={handle_change}
                indicatorColor="primary"
                textColor="primary"
                variant={"scrollable" if isScrollable else "standard"}
            >
                {for item in tabs_data {
                    <Tab key={str(item.get("id", ""))} label={str(item.get("label", ""))} />
                }}
            </MaterialTabs>
        </AppBar>
        {for (index, item) in enumerate(tabs_data) {
            <TabContainer key={str(item.get("id", ""))}>
                {item.get("content") if value == index else None}
            </TabContainer>
        }}
    </div>
}

