import from "@material-ui/core" { ListItem, ListItemIcon, ListItemText }

def:pub MenuItem(
    redirectTo: Callable[[str], None],
    title: str,
    url: str | None = None,
    icon: JsxElement | None = None,
    isButton: bool = False,
    isDisabled: bool = False,
    className: str | None = None,
) -> JsxElement {
    def handle_click(e: MouseEvent) {
        if url {
            redirectTo(url);
        }
    }

    item_class = className if className else "";
    if url {
        item_class = f"{item_class} menu-item-button".strip();
    }
    if isDisabled {
        item_class = f"{item_class} menu-item-disabled".strip();
    }

    <ListItem onClick={handle_click if url else None} className={item_class}>
        {if icon {
            <ListItemIcon>{icon}</ListItemIcon>
        }}
        <ListItemText primary={title} />
    </ListItem>
}

