def:pub ErrorBoundary(children: object = None) -> JsxElement {
    has reset_key: int = 0;

    def handle_retry(e: MouseEvent) {
        reset_key = reset_key + 1;
    }

    panel_style: dict[str, object] = {"padding": 16, "textAlign": "center"};
    warning_style: dict[str, object] = {"color": "var(--warning-color)", "fontWeight": 600};
    muted_style: dict[str, object] = {"color": "var(--text-muted)", "fontSize": 11, "marginTop": 4};
    back_style: dict[str, object] = {"marginTop": 8};

    fallback = (
        <div className="panel" style={panel_style}>
            <p style={warning_style}>Something went wrong</p>
            <p style={muted_style}>An unexpected error occurred</p>
            <button
                type="button"
                className="scan-message__back"
                style={back_style}
                onClick={handle_retry}
            >
                Retry
            </button>
        </div>
    );

    <JacClientErrorBoundary key={str(reset_key)} fallback={fallback}>
        {children}
    </JacClientErrorBoundary>
}

