import { container, FactoryProvider, InjectionToken, registry } from 'tsyringe';
import { Merge, Sheet } from './lib/types';
import {
  ConfigService,
  SheetService,
  SheetServiceFactory,
  MergesService,
  MergesServiceFactory,
  CellRange,
  CellRangeFactory,
  Selector,
  SelectorFactory,
  ScrollingService,
  RenderProxyService,
} from './lib/services';

// @registry()
// // eslint-disable-next-line @typescript-eslint/no-unused-vars
// class __Registry__ {}

export * from './lib/crdt/yjs-workbook';
export * from './lib/constants';
export * from './lib/utils';
export * from './lib/types';
export * from './lib/services';
export * from './lib/controllers';

export function createCore() {
  const factoryProviders: Array<
    FactoryProvider<unknown> & { token: InjectionToken }
  > = [
    {
      token: SheetService,
      useFactory:
        (dependencyContainer): SheetServiceFactory =>
        (d: Sheet) =>
          new SheetService(
            d,
            dependencyContainer.resolve(ConfigService),
            dependencyContainer.resolve(ScrollingService),
            dependencyContainer.resolve(RenderProxyService),
            dependencyContainer.resolve(MergesService) as never,
            dependencyContainer.resolve(Selector) as never,
          ),
    },
    {
      token: CellRange,
      useFactory:
        (dependencyContainer): CellRangeFactory =>
        (sri: number, eri: number, sci: number, eci: number) =>
          new CellRange(
            sri,
            eri,
            sci,
            eci,
            dependencyContainer.resolve(ConfigService),
          ),
    },
    {
      token: Selector,
      useFactory:
        (dependencyContainer): SelectorFactory =>
        (sri: number, eri: number, sci: number, eci: number) =>
          new Selector(
            sri,
            eri,
            sci,
            eci,
            dependencyContainer.resolve(CellRange) as never,
          ),
    },
    {
      token: MergesService,
      useFactory:
        (dependencyContainer): MergesServiceFactory =>
        (merges: Merge[]) =>
          new MergesService(
            merges,
            dependencyContainer.resolve(CellRange) as never,
          ),
    },
  ];
  for (const p of factoryProviders) {
    container.register(p.token, p);
  }
}

const sortData = (headers: any, data: any, orderBy: any, order: any) => {
  const orderByHeader: any = headers.filter(
    (header: any) => header.id === orderBy,
  )[0];

  let { transformData } = orderByHeader;

  if (!data) {
    return data;
  }

  if (typeof transformData !== "function") {
    transformData = (values: any) => values;
  }

  const transformedData = data.map((element: any) => ({
    ...element,
    [orderBy]: transformData(element[orderBy]),
  }));

  const sortedData = transformedData.sort((a: any, b: any) =>
    a[orderBy] < b[orderBy] ? -1 : 1,
  );

  if (order === "asc") {
    return sortedData;
  }

  return sortedData.reverse();
};

export default sortData;

jac:
obj SortHeader {
    has id: str;
    has transformData: Callable[[object], object] | None = None;
}

def:pub sortData(
    headers: list[SortHeader],
    data: list[dict[str, object]] | None,
    orderBy: str,
    order: str
) -> list[dict[str, object]] | None {
    orderByHeader: SortHeader = [header for header in headers if header.id == orderBy][0];
    transformFn: Callable[[object], object] = (
        orderByHeader.transformData as Callable[[object], object]
        if callable(orderByHeader.transformData)
        else (lambda (values: object) -> object { return values; })
    );
    if not data {
        return data;
    }
    transformedData: list[dict[str, object]] = [
        {**element, **{orderBy: transformFn(element[orderBy])}}
        for element in data
    ];
    sortedData: list[dict[str, object]] = [row for row in transformedData];
    for i = 0 while i < len(sortedData) with i += 1 {
        for j = (i + 1) while j < len(sortedData) with j += 1 {
            if sortedData[i][orderBy] > sortedData[j][orderBy] {
                tmp = sortedData[i];
                sortedData[i] = sortedData[j];
                sortedData[j] = tmp;
            }
        }
    }
    if order == "asc" {
        return sortedData;
    }
    return list(reversed(sortedData));
}

