def:pub colLabelFromIndex(colIndex: int) -> str {
    letter = "";
    while colIndex >= 0 {
        temp = colIndex % 26;
        letter = chr(temp + 65) + letter;
        colIndex = int((colIndex - temp - 1) // 26);
    }
    return letter;
}

def:pub colIndexFromLabel(label: str) -> int {
    ret = 0;
    i = 0;
    while i < len(label) - 1 {
        cindex = ord(label[i]) - 65;
        exponet = len(label) - 1 - i;
        ret += int(len(alphabets) ** exponet + len(alphabets) * cindex);
        i += 1;
    }
    ret += ord(label[len(label) - 1]) - 65;
    return ret;
}

def:pub labelFromCell(ri: int, ci: int) -> str {
    colLabel = colLabelFromIndex(ci);
    return f"{colLabel}{ri + 1}";
}

def:pub xyFromLabel(label: str) -> tuple[int, int] {
    x = "";
    y = "";
    i = 0;
    while i < len(label) {
        ch = label[i];
        if ch >= "0" and ch <= "9" {
            y += ch;
        } else {
            x += ch;
        }
        i += 1;
    }
    return (colIndexFromLabel(x), int(y) - 1);
}

