export const mergeParams = <T>(params: Partial<T>, defaultParams: T): T => {
  const o: T = { ...defaultParams, ...params };
  Object.entries(defaultParams).forEach(([key, value]) => {
    if (value === undefined) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (o as any)[key] = (defaultParams as any)[key];
    }
  });
  return o;
};

jac:
def:pub mergeParams(params: dict[str, object], defaultParams: dict[str, object]) -> dict[str, object] {
    o: dict[str, object] = {**defaultParams, **params};
    for (key, value) in defaultParams.items() {
        if value is None {
            o[key] = defaultParams[key];
        }
    }
    return o;
}

