    for (i, row_raw) in enumerate(data) {
        if not isinstance(row_raw, dict) {
            raise Exception(f'last-data.json: fila {i} sin "countryId" de tipo string');
        }
        row = row_raw as dict[str, object];
        country_id = row.get("countryId");
        if not isinstance(country_id, str) {
            raise Exception(f'last-data.json: fila {i} sin "countryId" de tipo string');
        }
