def hexToRgb(hex: str) -> list[int] {
    n = int(hex.replace("#", ""), 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

def rgbToHex(rgb: list[float]) -> str {
    parts: list[str] = [f"{int(round(c)):02x}" for c in [rgb[0], rgb[1], rgb[2]]];
    return "#" + "".join(parts);
}

