import from "mongoose" { default as mongoose, Mongoose }
import from "./builder" { default as builder }
import from "./deleteAllData" { default as deleteAllData }

async def:pub connect() -> dict[str, object] {
    connection: Mongoose;
    try {
        DATABASE_URL = os.environ.get("DATABASE_URL");
        TEST_ENABLED = os.environ.get("TEST_ENABLED");
        if not DATABASE_URL {
            raise ValueError("DATABASE_URL param is empty");
        }
        databaseUrl = f"{DATABASE_URL}test" if TEST_ENABLED else DATABASE_URL;
        connection = await mongoose.connect(databaseUrl);
    } except Exception as err {
        print(err);
        raise ValueError("Cannot cannot to DB");
    }
    models = await builder() as dict[str, object];
    result: dict[str, object] = {"connection": connection};
    for (k, v) in models.items() {
        result[k] = v;
    }
    return result;
}

async def:pub disconnect() {
    TEST_ENABLED = os.environ.get("TEST_ENABLED");
    if TEST_ENABLED {
        await deleteAllData();
    }
    await mongoose.connection.close();
}

