import from "mongoose" { Document, ToObjectOptions }

def toJson(document: Document) -> object {
    options: ToObjectOptions = {
        "transform": lambda (_1: object, ret: dict[str, object], _2: object) -> dict[str, object] {
            newRet: dict[str, object] = {};
            for (k, v) in list(ret.items()) {
                if k != "_id" and k != "__v" {
                    newRet[k] = v;
                }
            }
            idVal = ret["_id"];
            newRet["_id"] = str(idVal);
            return newRet;
        },
        "flattenMaps": False
    };
    return document.toJSON(options) as object;
}

