import from "./Segment" { default as Segment }
import from "../utils/charToDigit" { default as defaultCharMap, CharToDigit }

glob letters: list[str] = ["A", "B", "C", "D", "E", "F", "G"];

glob DEFAULT_CHAR: str = "-";

def isValidSegmentArray(arr: list[int] | None) -> bool {
    if arr is None {
        return False;
    }
    return all(isinstance(item, (int, float)) for item in arr);
}

def:pub Digit(char: str, color: str = "red", height: int = 250, skew: bool = False, charMap: CharToDigit | None = None) -> JsxElement {
    style = {
        "height": f"{height}px",
        "width": f"{height * 0.6}px",
        "zIndex": "1",
        "padding": "8px 0px" if skew else "0",
        "boxSizing": "border-box",
    };
    currentMap = (charMap if charMap is not None else defaultCharMap) as dict[str, list[int]];
    charSegments: list[int] | None = currentMap[char] if isinstance(char, str) and char in currentMap else None;
    segmentsToRender: list[int];
    if isValidSegmentArray(charSegments) {
        segmentsToRender = charSegments as list[int];
    } else {
        fallbackSegments = currentMap[DEFAULT_CHAR];
        if isValidSegmentArray(fallbackSegments) {
            segmentsToRender = fallbackSegments as list[int];
        } else {
            console.error(f'react-7-segment-display: Invalid segment data for char "{char}" AND default char "{DEFAULT_CHAR}". Check charMap.');
            segmentsToRender = [];
        }
    }
    if len(segmentsToRender) > len(letters) {
        console.warn(f"react-7-segment-display: Segment count {len(segmentsToRender)} out of bounds for letters array.");
    }
    return <div className="digit" style={style}>{[Segment(active=active, color=color, height=height, id=letter, skew=skew) for (letter, active) in zip(letters, segmentsToRender)]}</div>;
}

def:pub ConditionalWrapper(when: bool, children: object, wrapper: Callable[[object], object]) -> object {
    return wrapper(children) if when else children;
}

