          altKey: true,
          shiftKey: true,
          ctrlKey: true,
          metaKey: true,
        })
      )
    ).toEqual("ctrl+shift+alt+meta+space");
  });
});

function newDecodedKey(key: Partial<DecodedKey>): DecodedKey {
  return {
    key: "",
    ctrlKey: false,
    shiftKey: false,
    altKey: false,
    metaKey: false,
    getModifierState(key: string): boolean {
      return ["Control", "Shift", "Alt", "Meta"].includes(key);
    },
    ...key,
  };
}

