glob defaultAbc = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";

import math;
import random;

def:pub newId(length: int = 8, abc: str = defaultAbc) -> str {
    id = "";
    for i = 0 while i < length with i += 1 {
        idx = int(math.floor(len(abc) * random.random()));
        id += abc[idx];
    }
    return id;
}

