    return lambda (state: AppRootState) -> FolderStatus | None {
        return state.directory.folderStatus.get(folder_metadata.id);
    };
}

def:pub selectAnsestors(folder_metadata: Directory.FolderMetadata) -> Callable[[AppRootState], list[Directory.FolderMetadata]] {
    return lambda (state: AppRootState) -> list[Directory.FolderMetadata] {
        current_node: Directory.FolderMetadata | None = state.directory.folderMetadata.get(folder_metadata.id);
        ansestors: list[Directory.FolderMetadata] = [];
        while (current_node is not None) and (current_node.id != Directory.RootNode.id) {
            ansestors.append(current_node);
            current_node = state.directory.folderMetadata.get(current_node.parentId);
        }
        ansestors.append(Directory.RootNode);
        ansestors.reverse();
        return ansestors;
    };
}

