import re;
import from urllib.parse { parse_qs }

enum RouteKind: str {
    HOME = "home",
    SEARCH = "search",
    MOVIE = "movie",
    TV = "tv",
    PERSON = "person",
    WATCHLISTS = "watchlists",
    SETTINGS = "settings",
    SETTINGS_PROFILE = "settings-profile",
    SETTINGS_PREFERENCES = "settings-preferences",
    AUTH_CALLBACK = "auth-callback",
    ONBOARDING = "onboarding",
    UNKNOWN = "unknown"
}

obj:pub ParsedRoute {
    has kind: RouteKind;
    has id: int | None = None;
    has query: str | None = None;
}

def _param(params: dict[str, list[str]], key: str) -> str | None {
    vals = params.get(key);
    if vals is None or len(vals) == 0 {
        return None;
    }
    return vals[0];
}

def:pub parseAppRoute(pathname: str, search: str) -> ParsedRoute {
    normalized_path = pathname if pathname else "/";
    query_string = search[1:] if search.startswith("?") else search;
    params = parse_qs(query_string if query_string else "");
    if normalized_path == "/" {
        q = _param(params, "q");
        type_val = _param(params, "type");
        id_val = _param(params, "id");
        if q is not None {
            if type_val == "show" or type_val == "tv" {
                return ParsedRoute(kind=RouteKind.SEARCH, query=q);
            }
            if type_val == "person" and id_val is not None {
                return ParsedRoute(kind=RouteKind.PERSON, id=int(id_val));
            }
            return ParsedRoute(kind=RouteKind.SEARCH, query=q);
        }
        return ParsedRoute(kind=RouteKind.HOME);
    }
    if normalized_path == "/search" {
        q = _param(params, "q");
        return ParsedRoute(kind=RouteKind.SEARCH, query=(q if q is not None else ""));
    }
    if normalized_path == "/watchlists" {
        return ParsedRoute(kind=RouteKind.WATCHLISTS);
    }
    if normalized_path == "/settings" {
        return ParsedRoute(kind=RouteKind.SETTINGS);
    }
    if normalized_path == "/settings/profile" {
        return ParsedRoute(kind=RouteKind.SETTINGS_PROFILE);
    }
    if normalized_path == "/settings/preferences" {
        return ParsedRoute(kind=RouteKind.SETTINGS_PREFERENCES);
    }
    if normalized_path == "/auth/callback" {
        return ParsedRoute(kind=RouteKind.AUTH_CALLBACK);
    }
    if normalized_path == "/onboarding" {
        return ParsedRoute(kind=RouteKind.ONBOARDING);
    }
    movie_match = re.match(r"^/movie/(\d+)$", normalized_path);
    if movie_match {
        return ParsedRoute(kind=RouteKind.MOVIE, id=int(movie_match.group(1)));
    }
    tv_match = re.match(r"^/tv/(\d+)$", normalized_path);
    if tv_match {
        return ParsedRoute(kind=RouteKind.TV, id=int(tv_match.group(1)));
    }
    person_match = re.match(r"^/person/(\d+)$", normalized_path);
    if person_match {
        return ParsedRoute(kind=RouteKind.PERSON, id=int(person_match.group(1)));
    }
    return ParsedRoute(kind=RouteKind.UNKNOWN);
}

