import re;

type PersonRoleMatch = str;

glob ROLE_RANK: dict[str, int] = {"match": 2, "neutral": 1, "mismatch": 0};

obj PersonCardInput {
    has name: str;
    has profile_url: str | None = None;
    has known_for_department: str | None = None;
    has known_for_titles: list[str] = [];
    has known_for: str | None = None;
}

obj PersonCardPresentation {
    has name: str;
    has roleChip: str;
    has snippet: str;
    has avatarUrl: str | None = None;
}

def sanitizeText(input: str | None = None) -> str {
    return re.sub(r"\s+", " ", str(input or "")).strip();
}

def truncateText(input: str, max: int = 70) -> str {
    if len(input) <= max {
        return input;
    }
    return input[0:max - 1].rstrip() + "…";
}

def:pub formatRoleChip(knownForDepartment: str | None = None) -> str {
    normalized = sanitizeText(knownForDepartment);
    if not normalized {
        return "Person";
    }
    return normalized;
}

def:pub formatKnownForSnippet(input: PersonCardInput) -> str {
    if len(input.known_for_titles) > 0 {
        snippet = " • ".join([part for part in [sanitizeText(title) for title in input.known_for_titles[0:3]] if part]);
        if snippet {
            return truncateText(snippet, 88);
        }
    }
    known_for = sanitizeText(input.known_for);
    return truncateText(known_for, 88) if known_for else "Known for notable film and TV work";
}

def:pub buildPersonCardPresentation(input: PersonCardInput) -> PersonCardPresentation {
    return PersonCardPresentation(
        name=sanitizeText(input.name),
        avatarUrl=input.profile_url,
        roleChip=formatRoleChip(input.known_for_department),
        snippet=formatKnownForSnippet(input)
    );
}

def _score_value(item: dict[str, object]) -> float {
    score = item.get("score");
    if isinstance(score, (int, float)) {
        return float(score);
    }
    confidence = item.get("confidence");
    if isinstance(confidence, (int, float)) {
        return float(confidence);
    }
    return 0.0;
}

def:pub sortPersonShortlist(candidates: list[dict[str, object]]) -> list[dict[str, object]] {
    return sorted(candidates, key=lambda (item: dict[str, object]) {
        role_key = str(item.get("role_match") or "neutral");
        role = ROLE_RANK.get(role_key, 1);
        popularity = item.get("popularity");
        pop = float(popularity) if isinstance(popularity, (int, float)) else 0.0;
        return (-_score_value(item), -role, -pop);
    });
}

