}

def:pub PricingCard(plan: BillingPlan, onSelect: Callable[[BillingPlan], None], currentPlan: str | None = None, isLoading: bool | None = None) -> JsxElement {
    isCurrent = currentPlan == plan.id;
    def handle_select(e: MouseEvent) {
        onSelect(plan);
    }
    <Card className={cn("relative flex flex-col", plan.popular and "border-primary shadow-md")}>
        {plan.popular and <Badge className="absolute -top-3 left-1/2 -translate-x-1/2">Most Popular</Badge>}
        <CardHeader>
            <CardTitle>{plan.name}</CardTitle>
            <CardDescription>{plan.description}</CardDescription>
            <div className="mt-4">
                <span className="text-4xl font-bold">{"Free" if plan.price == 0 else formatCurrency(plan.price)}</span>
                {plan.price > 0 and <span className="text-muted-foreground">/{plan.interval}</span>}
            </div>
        </CardHeader>
        <CardContent className="flex-1">
            <ul className="space-y-3">
                {for feature in plan.features {
                    <li key={feature} className="flex items-center gap-2 text-sm">
                        <svg className="h-4 w-4 text-primary" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                        </svg>
                        {feature}
                    </li>
                }}
            </ul>
        </CardContent>
        <CardFooter>
            <Button className="w-full" variant={"default" if plan.popular else "outline"} disabled={isCurrent or bool(isLoading)} isLoading={isLoading} onClick={handle_select}>
                {"Current Plan" if isCurrent else ("Get Started" if plan.price == 0 else "Upgrade")}
            </Button>
        </CardFooter>
    </Card>
}

