import from "vitest" { describe, it, expect }
import from "node:fs" { existsSync }
import from "node:path" { join, resolve, dirname }
import from "node:url" { fileURLToPath }

def swapWorkspaceDeps(pkg: dict[str, object]) -> dict[str, object] {
    depFields = ["dependencies", "devDependencies", "peerDependencies"];
    for field in depFields {
        deps = pkg.get(field) as dict[str, str] | None;
        if deps {
            for (dep, ver) in deps.items() {
                if ver == "workspace:*" {
                    deps[dep] = "latest";
                }
            }
        }
    }
    return pkg;
}

def swapPresetInCss(content: str, preset: str) -> str {
    return content.replace("@ninna-ui/core/theme/presets/default.css", f"@ninna-ui/core/theme/presets/{preset}.css");
}

