def pathFunc(link: dict[str, object]) -> str | None {
    source = link["source"] as dict[str, object];
    target = link["target"] as dict[str, object];
    if target["type"] == "plus" {
        return None;
    }
    return f"M{source['x']},{source['y']}L{target['x']},{target['y']}";
}

