/**
 * Compose multiple refs into a single ref callback
 * Useful when you need to pass a ref to multiple consumers
 */

export type ComposedRef<T> =
  | ((instance: T | null) => void)
  | { current: T | null }
  | null
  | undefined;

/**
 * Compose multiple refs into a single ref callback
 *
 * @example
 * const Component = forwardRef((props, forwardedRef) => {
 *   const internalRef = useRef(null);
 *   return <div ref={composeRefs(forwardedRef, internalRef)} />;
 * });
 */
export function composeRefs<T>(
  ...refs: ComposedRef<T>[]
): (instance: T | null) => void {
  return (instance: T | null) => {
    refs.forEach((ref) => {
      if (typeof ref === 'function') {
        ref(instance);
      } else if (ref != null) {
        ref.current = instance;
      }
    });
  };
}

jac:
type ComposedRef[T] = Callable[[T | None], None] | RefHolder[T] | None;

obj RefHolder[T] {
    has current: T | None = None;
}

def composeRefs[T](*refs: ComposedRef[T]) -> Callable[[T | None], None] {
    def composed(instance: T | None) {
        for ref in refs {
            if callable(ref) {
                (ref as Callable[[T | None], None])(instance);
            } elif ref is not None {
                (ref as RefHolder[T]).current = instance;
            }
        }
    }
    composed
}

