interface StatsCardProps {
  title: string;
  value: number;
  change?: number;
  format?: "number" | "currency";
  icon: React.ReactNode;
}

export function StatsCard({ title, value, change, format = "number", icon }: StatsCardProps) {
  const formattedValue = format === "currency"
