/**
 * FormLabel renders an accessible label for form fields
 * 
 * @example
 * ```tsx
 * <FormControl isRequired>
 *   <FormLabel>Email</FormLabel>
 *   <Input type="email" />
 * </FormControl>
 * ```
 */
