  (
    {
      variant = "solid",
      color = "primary",
      size = "md",
      radius = "md",
      loading = false,
      fullWidth = false,
      leftIcon,
      rightIcon,
      disabled,
      className,
      children,
      ...props
    },
    ref
  ) => {
    const isDisabled = disabled || loading;

    return (
      <button
        ref={ref}
        data-slot="button"
        className={cn(
          buttonVariants({ variant, color, size, radius, fullWidth }),
          className
        )}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        data-loading={loading}
        {...props}
      >
        {leftIcon && <span data-slot="icon">{leftIcon}</span>}
        {loading && (
          <span
            className={cn(
              'animate-spin rounded-full border-2 border-current border-t-transparent',
