    "withTextLine": "flex-1 h-px",
    "withTextContent": "text-sm font-medium shrink-0",
};

def dividerVariants(orientation: str | None = None, weight: str | None = None) -> str {
    o = orientation if orientation is not None else "horizontal";
    w = weight if weight is not None else "soft";
    if o == "vertical" {
        return cn("w-px self-stretch", f"divider-vertical-{w}");
    }
    return cn("w-full h-px", f"divider-horizontal-{w}");
}

def:pub Divider(
    variant: str | None = None,
    color: str | None = None,
    weight: str | None = None,
    text: str | None = None,
    className: str | None = None,
    ref: Ref[HTMLDivElement] = Ref(),
    props: dict[str, object] = {},
) -> JsxElement {
    v = variant if variant is not None else "horizontal";
    c = color if color is not None else "primary";
    w = weight if weight is not None else "soft";
    if v == "vertical" {
        return <div
            ref={ref}
            data-slot="divider"
            className={cn(dividerVariants(orientation="vertical", weight=w), className)}
            role="separator"
            aria-orientation="vertical"
            {**props}
        />;
    }
    if v == "with-text" {
        return <div
            ref={ref}
            data-slot="divider"
            className={cn(dividerStyles["withTextContainer"], className)}
            role="separator"
            aria-label={text}
            {**props}
        >
            <div className={cn(dividerStyles["withTextLine"], dividerVariants(orientation="horizontal", weight=w))} />
            {text and <span data-slot="label" className={cn(dividerStyles["withTextContent"], DIVIDER_TEXT_COLORS.get(c, ""))}>{text}</span>}
            <div className={cn(dividerStyles["withTextLine"], dividerVariants(orientation="horizontal", weight=w))} />
        </div>;
    }
    return <div
        ref={ref}
        data-slot="divider"
        className={cn(dividerVariants(orientation="horizontal", weight=w), className)}
        role="separator"
        aria-orientation="horizontal"
        {**props}
    />;
}

