        md:  "h-5 w-5",
        lg:  "h-6 w-6",
        xl:  "h-8 w-8",
      "2xl": "h-10 w-10",
      "3xl": "h-12 w-12",
    },
  },

  // Prevent size from affecting dots container
  compoundVariants: [
    { variant: "dots", size: "xs", className: "h-auto w-auto" },
