import from "@/components/ui/toast" {
    Toast,
    ToastClose,
    ToastDescription,
    ToastProvider,
    ToastTitle,
    ToastViewport,
}

def render_toast(item: dict[str, object]) -> JsxElement {
    toast_id = item["id"] as str;
    title = item.get("title");
    description = item.get("description");
    action = item.get("action");
    <Toast key={toast_id}>
        <div className="grid gap-1">
            {title and <ToastTitle>{title}</ToastTitle>}
            {description and <ToastDescription>{description}</ToastDescription>}
        </div>
        {action}
        <ToastClose />
    </Toast>
}

def:pub Toaster() -> JsxElement {
    hook = useToast();
    toasts = hook.toasts as list[dict[str, object]];
    <ToastProvider>
        {for item in toasts {
            render_toast(item);
        }}
        <ToastViewport />
    </ToastProvider>
}

