        users = [root -->][?:User];
        if not users {
            self.reports.append({"error": "Unauthorized"});
            disengage;
        }
        user = users[0];
        tenants = [user <-:Users:<-];
        if not tenants {
            self.reports.append({"error": "Tenant not found"});
            disengage;
        }
        tenant = tenants[0];
        if not self.price_id {
            self.reports.append({"error": "Price ID is required"});
            disengage;
        }
        url = await createCheckoutSession(
            jid(tenant),
            self.price_id,
            tenant.stripe_customer_id
        );
        self.reports.append({"url": url});
    }

    can respond with Root exit {
        report self.reports[0] if self.reports else {"error": "Internal server error"};
    }
}

