  /** Maximum number of avatars to show */
  max?: number;

  /** Size for all avatars in the group */
  size?: Size;

  /** Spacing between avatars (negative for overlap) */
  spacing?: 'tight' | 'normal' | 'loose';

  /** Avatar children */
  children: ReactNode;
}

