import os;

def:pub makeUrl(path: str, parameters: dict[str, object] | None = None) -> str {
    if not parameters {
        return path;
    }
    keys = list(parameters.keys());
    params = "&".join([f"{key}={parameters[key]}" for key in keys]);
    return f"{path}?{params}";
}

