import from "react-konva" { Stage, Layer, Rect, Text as KonvaText, Circle, Line, Arrow }
import from "lucide-react" { Plus }
import from "./PresentationCanvas" { SLIDE_WIDTH }

glob THUMB_WIDTH: int = 160;

glob THUMB_HEIGHT: int = 90;

glob THUMB_SCALE: float = float(THUMB_WIDTH) / (SLIDE_WIDTH as float);

obj SlideElement {
    has id: str;
    has type: str;
    has x: float;
    has y: float;
    has width: float;
    has height: float;
    has rotation: float = 0;
    has opacity: float = 1;
    has text: dict[str, str | int] | None = None;
    has shape: dict[str, str | int] | None = None;
}

obj Slide {
    has id: str;
    has elements: list[SlideElement] = [];
}

def SlideThumbnail(
    slide: Slide,
    index: int,
    isActive: bool,
    onClick: Callable[[], None],
) -> JsxElement {
    def renderElement(element: SlideElement) -> JsxElement {
        common = {
            "id": element.id,
            "x": element.x * THUMB_SCALE,
            "y": element.y * THUMB_SCALE,
            "rotation": element.rotation,
            "opacity": element.opacity,
            "listening": False,
        };
        match element.type {
            case "text":
                textData = element.text;
                content = str(textData.get("content", "Text")) if textData else "Text";
                fontSize = float(textData.get("fontSize", 32) if textData else 32) * THUMB_SCALE;
                fontFamily = str(textData.get("fontFamily", "Inter")) if textData else "Inter";
                fill = str(textData.get("color", "#1F2937")) if textData else "#1F2937";
                return <KonvaText
                    key={element.id}
                    {**common}
                    width={element.width * THUMB_SCALE}
                    height={element.height * THUMB_SCALE}
                    text={content}
                    fontSize={fontSize}
                    fontFamily={fontFamily}
                    fill={fill}
                />;
            case "shape":
                shapeData = element.shape;
                shapeType = str(shapeData.get("type", "rectangle")) if shapeData else "rectangle";
                if shapeType == "ellipse" {
                    return <Circle
                        key={element.id}
                        {**common}
                        x={(element.x + element.width / 2) * THUMB_SCALE}
                        y={(element.y + element.height / 2) * THUMB_SCALE}
                        radiusX={(element.width / 2) * THUMB_SCALE}
                        radiusY={(element.height / 2) * THUMB_SCALE}
                        fill={str(shapeData.get("fill", "#E5E7EB")) if shapeData else "#E5E7EB"}
                        stroke={str(shapeData.get("stroke", "#374151")) if shapeData else "#374151"}
                        strokeWidth={float(shapeData.get("strokeWidth", 2) if shapeData else 2) * THUMB_SCALE}
                    />;
                }
                if shapeType == "line" {
                    return <Line
                        key={element.id}
                        {**common}
                        points={[0.0, 0.0, element.width * THUMB_SCALE, element.height * THUMB_SCALE]}
                        stroke={str(shapeData.get("stroke", "#374151")) if shapeData else "#374151"}
                        strokeWidth={float(shapeData.get("strokeWidth", 3) if shapeData else 3) * THUMB_SCALE}
                    />;
                }
                if shapeType == "arrow" {
                    return <Arrow
                        key={element.id}
                        {**common}
                        points={[0.0, 0.0, element.width * THUMB_SCALE, element.height * THUMB_SCALE]}
                        fill={str(shapeData.get("fill", "#374151")) if shapeData else "#374151"}
                        stroke={str(shapeData.get("stroke", "#374151")) if shapeData else "#374151"}
                        strokeWidth={float(shapeData.get("strokeWidth", 3) if shapeData else 3) * THUMB_SCALE}
                        pointerLength={10.0 * THUMB_SCALE}
                        pointerWidth={10.0 * THUMB_SCALE}
                    />;
                }
                return <Rect
                    key={element.id}
                    {**common}
                    width={element.width * THUMB_SCALE}
                    height={element.height * THUMB_SCALE}
                    fill={str(shapeData.get("fill", "#E5E7EB")) if shapeData else "#E5E7EB"}
                    stroke={str(shapeData.get("stroke", "#374151")) if shapeData else "#374151"}
                    strokeWidth={float(shapeData.get("strokeWidth", 2) if shapeData else 2) * THUMB_SCALE}
                />;
            case _:
                return <Rect key={element.id} {**common} width={0.0} height={0.0} />;
        }
    }

    borderClass = "border-accent-primary" if isActive else "border-border-light dark:border-border-dark hover:border-accent-primary/50";

    <div onClick={onClick} className={"relative rounded border-2 overflow-hidden " + borderClass}>
        <Stage width={THUMB_WIDTH} height={THUMB_HEIGHT}>
            <Layer>
                {for element in slide.elements {
                    renderElement(element);
                }}
            </Layer>
        </Stage>
        <div className="absolute bottom-0 left-0 right-0 bg-black/50 text-white text-xs text-center py-0.5">
            {index + 1}
        </div>
    </div>
}

