import from "lucide-react" { MousePointer2, Type, Square, Circle, Minus, ArrowRight, Image, ImagePlus, Play, Download, Plus, Trash2, Copy, Palette, Sparkles }

type PresentationTool = str;

obj ToolEntry {
    has id: str;
    has icon: object;
    has label: str;
}

glob TOOLS: list[ToolEntry] = [
    ToolEntry(id="select", icon=MousePointer2, label="Select (V)"),
    ToolEntry(id="text", icon=Type, label="Text (T)"),
    ToolEntry(id="rectangle", icon=Square, label="Rectangle (R)"),
    ToolEntry(id="ellipse", icon=Circle, label="Ellipse (E)"),
    ToolEntry(id="line", icon=Minus, label="Line (L)"),
    ToolEntry(id="arrow", icon=ArrowRight, label="Arrow (A)"),
];

def button_class(active: bool = False) -> str {
    base = "p-1.5 rounded transition-colors ";
    if active {
        return base + "bg-accent-primary/10 text-accent-primary";
    }
    return base + "text-text-light-secondary dark:text-text-dark-secondary hover:bg-surface-light-alt dark:hover:bg-surface-dark-elevated";
}

def inactive_action_class() -> str {
    return "p-1.5 rounded transition-colors text-text-light-secondary dark:text-text-dark-secondary hover:bg-surface-light-alt dark:hover:bg-surface-dark-elevated hover:text-accent-primary";
}

def delete_action_class(enabled: bool) -> str {
    base = "p-1.5 rounded transition-colors ";
    if enabled {
        return base + "text-text-light-secondary dark:text-text-dark-secondary hover:bg-surface-light-alt dark:hover:bg-surface-dark-elevated hover:text-accent-primary";
    }
    return base + "text-text-light-tertiary dark:text-text-dark-tertiary opacity-50 cursor-not-allowed";
}

def:pub PresentationToolbar(
