        <div className="flex items-center gap-0.5 border-r border-border-light dark:border-border-dark pr-2 mr-1">
            <button onClick={onPresent} className={inactive_action_class()} title="Present">
                <Play className="w-4 h-4" />
            </button>
            <button onClick={onExport} className={inactive_action_class()} title="Export">
                <Download className="w-4 h-4" />
            </button>
        </div>
        {if onTheme or onAnimation {
