    has format: str = "pdf";
    has isExporting: bool = False;
    has progressCurrent: int = 0;
    has progressTotal: int = 0;

    async def handle_export() {
        isExporting = True;
        progressCurrent = 0;
        progressTotal = len(slides);
        progressCb = lambda (current: int, total: int) {
            progressCurrent = current;
            progressTotal = total;
        };
        try {
            if format == "pdf" {
