    content_urls = data["content_urls"] as dict[str, dict[str, str]];
    return WikiArticle(
        title=data["title"] as str,
        extract=data["extract"] as str,
        url=content_urls["desktop"]["page"],
        thumbnail=thumb,
    );
}

