        }
    }
    for tag in getRecentTags(allNotes, maxSuggestions * 2, existingTags) {
        if tag not in suggestions {
            suggestions[tag] = TagSuggestion(tag=tag, reason="recent", weight=0.4);
        }
    }
    ranked = sorted(
        suggestions.values(),
        key=lambda (s: TagSuggestion) -> float { return s.weight; },
        reverse=True,
    );
    return ranked[0:maxSuggestions];
}

