    setCopied = _copied_state[1];

    def copy() {
        navigator.clipboard.writeText(text);
        setCopied(True);
    }

    useEffect(lambda {
        if copied {
            timeout = setTimeout(lambda { setCopied(False); }, delay);
            return lambda { clearTimeout(timeout); };
        }
        return lambda { };
    }, [delay, copied]);

    return {"text": text, "copy": copy, "copied": copied};
}

