def format_wedding_date(date: str) -> str {
    if not date {
        return "";
    }
    d = new(Date, date);
    return d.toLocaleDateString("en-US", {"weekday": "long", "year": "numeric", "month": "long", "day": "numeric"});
}

def:pub GuestHeroSection(
    brideName: str | None = None,
    groomName: str | None = None,
    weddingDate: str | None = None,
    heroImageUrl: str | None = None,
    primaryColor: str = "#e4b6c6",
    headingFont: str = "Playfair Display",
    guestName: str | None = None,
) -> JsxElement {
    bg_image = (
        f"linear-gradient(rgba(0,0,0,0.3), rgba(0,0,0,0.3)), url({heroImageUrl})"
        if heroImageUrl
        else f"linear-gradient(135deg, {primaryColor} 0%, #ffffff 100%)"
    );
    text_shadow = "1px 1px 2px rgba(0,0,0,0.5)" if heroImageUrl else "none";
    body_text_color = "#ffffff" if heroImageUrl else "#666";
    heading_text_color = "#ffffff" if heroImageUrl else "#333";
  <section
        className="relative min-h-screen flex items-center justify-center text-white overflow-hidden"
        style={{
            "backgroundImage": bg_image,
            "backgroundSize": "cover",
            "backgroundPosition": "center",
        }}
    >
        <div className="relative z-10 text-center px-4 py-16">
            <div className="max-w-4xl mx-auto">
                {if guestName {
                    <p
                        className="text-lg sm:text-xl md:text-2xl font-light mb-4 tracking-wide"
                        style={{
                            "textShadow": text_shadow,
                            "color": body_text_color,
                            "fontFamily": headingFont,
                        }}
