import from "@radix-ui/react-slot" { Slot }
import from "@/lib/utils" { cn }

glob BUTTON_BASE: str = "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 shrink-0 [&_svg]:shrink-0 outline-none focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive cursor-pointer";

glob BUTTON_VARIANT_CLASSES: dict[str, str] = {
    "default": "bg-primary text-primary-foreground hover:bg-primary/90",
    "destructive": "bg-destructive text-white hover:bg-destructive/90 focus-visible:ring-destructive/20 dark:focus-visible:ring-destructive/40 dark:bg-destructive/60",
    "outline": "border bg-background shadow-xs hover:bg-accent hover:text-accent-foreground dark:bg-input/30 dark:border-input dark:hover:bg-input/50",
    "secondary": "bg-secondary text-secondary-foreground hover:bg-secondary/80",
    "ghost": "hover:bg-accent hover:text-accent-foreground dark:hover:bg-accent/50",
    "link": "text-primary underline-offset-4 hover:underline",
};

glob BUTTON_SIZE_CLASSES: dict[str, str] = {
    "default": "h-9 px-4 py-2 has-[>svg]:px-3",
    "sm": "h-8 rounded-md gap-1.5 px-3 has-[>svg]:px-2.5",
    "lg": "h-10 rounded-md px-6 has-[>svg]:px-4",
    "icon": "size-9",
    "icon-sm": "size-8",
    "icon-lg": "size-10",
};

def:pub buttonVariants(
    variant: str | None = None,
    size: str | None = None,
    className: str | None = None,
) -> str {
    v = variant if variant is not None else "default";
    s = size if size is not None else "default";
    return cn(BUTTON_BASE, BUTTON_VARIANT_CLASSES.get(v, ""), BUTTON_SIZE_CLASSES.get(s, ""), className);
}

def:pub Button(
    className: str | None = None,
    variant: str | None = None,
    size: str | None = None,
    asChild: bool = False,
    children: object | None = None,
    props: dict[str, object] = {},
) -> JsxElement {
    cls = buttonVariants(variant=variant, size=size, className=className);
    if asChild {
        return <Slot data-slot="button" className={cls} {**props}>{children}</Slot>;
    }
    return <button data-slot="button" className={cls} {**props}>{children}</button>;
}

