    has indicatorDirection: str | None = None;
    has afterChange: Callable[[dict[str, object]], None] | None = None;
}

def:pub Carousel(
    className: str | None = None,
    style: dict[str, object] | None = None,
    autoplay: bool = False,
    duration: int = 2000,
    activeIndex: int = 0,
    speed: int = 10,
    loop: bool = False,
    indicator: bool = True,
    axis: str = "x",
    indicatorColor: str = "#268AF0",
    indicatorDirection: str | None = None,
    afterChange: Callable[[dict[str, object]], None] | None = None,
    children: list[object] | None = None,
    props: dict[str, object] | None = None,
) -> JsxElement {
    has selectedIndex: int = 0;
    slides = children if children is not None else [];
    rest = props if props is not None else {};
    dir = indicatorDirection if indicatorDirection else ("left" if axis == "y" else "bottom");
    embla_result = useEmblaCarousel({"loop": loop, "axis": axis, "speed": speed});
    emblaRef = embla_result[0];
    emblaApi = embla_result[1];
    def handleOnSelect {
        if emblaApi {
            snap_fn = getattr(emblaApi, "selectedScrollSnap", None);
            if snap_fn {
                selectedIndex = snap_fn() as int;
                if afterChange {
                    afterChange({"index": selectedIndex});
                }
            }
        }
    }
    def handleScrollNext {
        if emblaApi {
            can_next = getattr(emblaApi, "canScrollNext", None);
            scroll_next = getattr(emblaApi, "scrollNext", None);
            scroll_to = getattr(emblaApi, "scrollTo", None);
            if can_next and can_next() {
                if scroll_next {
                    scroll_next();
                }
            } elif loop and scroll_to {
                scroll_to(0);
            }
        }
    }
    useEffect(lambda {
        timer: object = None;
        if emblaApi {
            scroll_to = getattr(emblaApi, "scrollTo", None);
            on_fn = getattr(emblaApi, "on", None);
            if scroll_to {
                scroll_to(activeIndex);
            }
            if on_fn {
                on_fn("select", handleOnSelect);
            }
        }
        if autoplay {
            timer = setInterval(lambda { handleScrollNext(); }, duration);
        }
        return lambda {
            if timer is not None {
                clearInterval(timer as float);
            }
        };
    }, [emblaApi, activeIndex, autoplay, duration]);
    wrapCls = classnames(prefixCls, className);
    <div className={wrapCls} style={style if style is not None else {}} {**rest}>
        <div className={f"{prefixCls}-viewport"} ref={emblaRef}>
            <div className={f"{prefixCls}-container"}>
                {for slide in slides {
                    <div className={f"{prefixCls}-slide"}>{slide}</div>
                }}
            </div>
        </div>
        {if indicator {
            <div className={classnames(f"{prefixCls}-indicator", f"{prefixCls}-indicator-{dir}")}>
                {for (i, _) in enumerate(slides) {
                    <span className={classnames(f"{prefixCls}-dot", {f"{prefixCls}-dot-active": i == selectedIndex})} style={{"backgroundColor": indicatorColor}} />
                }}
            </div>
        }}
    </div>
}

