import from "react-polymorphic-types" { PolymorphicPropsWithoutRef }
import from "styled-system" { ResponsiveValue }
import from "~lib" { SystemProps }
import from "~components/common/Box" { Box }
import from "~components/common/Flex" { Flex }
import from "~lib/css" { css }
import from "~lib/modifyResponsiveValue" { modifyResponsiveValue }

glob GridDefaultElement: str = "div";

def _gridNegate(val: float) -> float {
    return -val;
}

def _gridFlexSize(size: float) -> str {
    return f"0 1 {(1 / size) * 100}%";
}

def:pub Grid(
    rowSize: ResponsiveValue[float],
    rowGap: ResponsiveValue[float] = 0,
    columnGap: ResponsiveValue[float] = 0,
    children: object = None,
    props: dict[str, object] = {},
) -> JsxElement {
    <Box {**props}>
        <Flex
            flexWrap="wrap"
            ml={modifyResponsiveValue(columnGap, _gridNegate)}
            mt={modifyResponsiveValue(rowGap, _gridNegate)}
            css={css({
                "& > *": {
                    "flex": modifyResponsiveValue(rowSize, _gridFlexSize),
                    "pl": columnGap,
                    "pt": rowGap,
                },
            })}
        >
            {children}
        </Flex>
    </Box>
}

