def:pub SnackbarProvider(children: JsxElement | str | int | list[object] | None = None, maxSnack: int = 3) -> JsxElement {
    has snacks: list[dict[str, object]] = [];

    def removeSnack(id: int) {
        snacks = [snack for snack in snacks if (snack["id"] as int) != id];
    }

    def enqueueSnackbar(message: JsxElement | str | int | list[object] | None, options: dict[str, str] | None = None) {
        snack_id = Date.now() + Math.floor(Math.random() * 1000);
        variant = "default";
        if options and "variant" in options {
            variant = options["variant"];
        }
        item = {"id": snack_id, "message": message, "variant": variant};
        next_snacks = snacks + [item];
        if len(next_snacks) > maxSnack {
            next_snacks = next_snacks[-maxSnack:];
        }
        snacks = next_snacks;
    }

    value = {"enqueueSnackbar": enqueueSnackbar};

    <SnackbarContext.Provider value={value}>
        {children}
        <div className="fixed bottom-4 right-4 z-50 flex flex-col gap-2">
            {for snack in snacks {
                <div key={str(snack["id"])} className={f"rounded-lg border px-4 py-3 shadow-lg {variantClasses[snack['variant'] as str]}"} onClick={lambda -> None { removeSnack(snack["id"] as int); }}>{snack["message"]}</div>
            }}
        </div>
    </SnackbarContext.Provider>
}

def:pub useSnackbar -> dict[str, Callable[[JsxElement | str | int | list[object] | None, dict[str, str] | None], None]] {
    ctx: dict[str, Callable[[JsxElement | str | int | list[object] | None, dict[str, str] | None], None]] = useContext(SnackbarContext) as dict[str, Callable[[JsxElement | str | int | list[object] | None, dict[str, str] | None], None]];
    if not ctx {
        raise ValueError("useSnackbar must be used within SnackbarProvider");
    }
    return ctx;
}

