import from "./message" { addMessageHandler }
import from "./types" { MessageType }

obj KeyUpStatus {
    has alt: bool;
    has ctrl: bool;
    has meta: bool;
    has shift: bool;
    has key: str;
    has code: str;
}

glob shortCutSettings = {"disabledHandling": False};

def:pub toggleShortCutsDisabled(disabled: bool | None = None) -> None {
    shortCutSettings["disabledHandling"] = (
        not shortCutSettings["disabledHandling"] if disabled is None else disabled
    );
}

def:pub enableShortCuts() -> None {
    toggleShortCutsDisabled(False);
}

def:pub disableShortCuts() -> None {
    toggleShortCutsDisabled(True);
}

glob:pub bindings: dict[str, dict[str, str]] = {
    "keyboard": {
        "CtrlMeta + ArrowLeft": "flipChapterPrev",
        "CtrlMeta + ArrowRight": "flipChapterNext",
        "ArrowLeft": "flipPagePrev",
        "ArrowRight": "flipPageNext",
        "PageUp": "flipPagePrev",
        "PageDown": "flipPageNext",
        "Backquote": "toggleToc",
        "Home": "jumpPageFirst",
        "End": "jumpPageLast",
    },
    "mouse": {},
};

glob:pub actions: dict[str, Callable[[], None]] = {};

glob CONTROL_KEYS: set[str] = {"Control", "Meta", "Shift", "Alt"};

def keyHandler(keyStatus: KeyUpStatus) -> None {
    if shortCutSettings["disabledHandling"] {
        return;
    }
    if keyStatus.key in CONTROL_KEYS {
        return;
    }
    maps: list[list[str]] = [[keyStatus.code]];
    if keyStatus.alt {
        maps[0].append("Alt");
    }
    if keyStatus.shift {
        maps[0].append("Shift");
    }
    if keyStatus.ctrl or keyStatus.meta {
        maps.append(list(maps[0]));
        maps[0].append("CtrlMeta");
        maps[1].append("Ctrl" if keyStatus.ctrl else "Meta");
    }
    handled = False;
    for keys in maps {
        bind = " + ".join(reversed(keys));
        actionName = bindings["keyboard"].get(bind);
        if actionName {
            console.log(f"[shortcut] {bind} {actionName}");
            handler = actions.get(actionName);
            if handler {
                handler();
            }
            handled = True;
            break;
        }
    }
    if not handled {
        console.log(maps);
    }
}

with entry {
    window.addEventListener(
        "keyup",
        lambda (ev: KeyboardEvent) {
            keyHandler(
                KeyUpStatus(
                    alt=ev.altKey,
                    ctrl=ev.ctrlKey,
                    meta=ev.metaKey,
                    shift=ev.shiftKey,
                    key=ev.key,
                    code=ev.code
                )
            );
        },
        False
    );
    addMessageHandler("keyUp", keyHandler);
}

