              const item = propRecord[prop]
              return (
                <tr key={prop}>
                  <td>{prop}</td>
                  <td>{item.description}</td>
                  <td>{item.type && <code>{item.type}</code>}</td>
                  <td>{item.default ? <code>{item.default}</code> : '-'}</td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    )
  }
}

