import type from "../types" { Size }
import type from "@laser-ui/hooks/useRefExtra" { RefExtra }

obj LContextData {
    has namespace: str;
    has componentDisabled: bool;
    has componentSize: Size;
    has componentDefaultProps: dict[str, object];
    has layoutPageScrollEl: RefExtra | None;
    has layoutContentResizeEl: RefExtra | None;
}

obj LContextIn {
    has namespace: str | None = None;
    has componentDisabled: bool | None = None;
    has componentSize: Size | None = None;
    has componentDefaultProps: dict[str, object] | None = None;
    has layoutPageScrollEl: RefExtra | None = None;
    has layoutContentResizeEl: RefExtra | None = None;
}

obj LContextManager {
    has namespace: str;
    has componentDisabled: bool;
    has componentSize: Size;
    has componentDefaultProps: dict[str, object];
    has layoutPageScrollEl: RefExtra | None;
    has layoutContentResizeEl: RefExtra | None;
    has _parent: LContextManager | None = None,
        parent: LContextManager | None {
            getter -> LContextManager | None { return self._parent; }
        };

    def root() -> LContextManager {
        instance = self;
        while instance._parent is not None {
            instance = instance._parent as LContextManager;
        }
        return instance;
    }

    def setParent(parent: LContextManager) {
        self._parent = parent;
    }

    def derive(context: LContextIn) -> LContextData {
        contextCopied = LContextData(
            namespace=self.namespace,
            componentDisabled=self.componentDisabled,
            componentSize=self.componentSize,
            componentDefaultProps=dict(self.componentDefaultProps),
            layoutPageScrollEl=self.layoutPageScrollEl,
            layoutContentResizeEl=self.layoutContentResizeEl,
        );
        if context.namespace is not None {
            contextCopied.namespace = context.namespace;
        }
        if context.componentDisabled is not None {
            contextCopied.componentDisabled = context.componentDisabled;
        }
        if context.componentSize is not None {
            contextCopied.componentSize = context.componentSize;
        }
        if context.componentDefaultProps is not None {
            for (k, v) in context.componentDefaultProps.items() {
                contextCopied.componentDefaultProps[k] = v;
            }
        }
        if context.layoutPageScrollEl is not None {
            contextCopied.layoutPageScrollEl = context.layoutPageScrollEl;
        }
        if context.layoutContentResizeEl is not None {
            contextCopied.layoutContentResizeEl = context.layoutContentResizeEl;
        }
        return contextCopied;
    }
}

glob:pub LContext: LContextManager = LContextManager(
    namespace="l",
    componentDisabled=False,
    componentSize="medium",
    componentDefaultProps={},
    layoutPageScrollEl=":root",
    layoutContentResizeEl=None,
);

