enum:pub ConnectionAdvice: str {
    CHECK_NETWORK = "check-network",
    SIGN_IN_AGAIN = "sign-in-again",
    RETRYING = "retrying",
    UNKNOWN = "unknown",
}

obj:pub ConnectionDiagnostics {
