import from "@/unlockrepo/utils/strict_map" { StrictMap }
import from "@/unlockrepo/utils/encryptor" { Encryptor }
import from "@/config/merchant_config" { merchantConfig }

type ConnectionName = str;

obj ConnectionTokens {
    has accessToken: str;
}

obj ConnectionRecord {
    has id: str;
    has userId: str;
    has tokens: ConnectionTokens | str;
    has connectionId: str;
    has name: ConnectionName;
    has updatedAt: str;
    has createdAt: str;
}

def withDecryptedTokens(connection: ConnectionRecord) -> ConnectionRecord {
    if isinstance(connection.tokens, str) {
        decrypted = Encryptor.decryptJSON(connection.tokens);
        tokens = ConnectionTokens(accessToken=decrypted["accessToken"] as str);
        return ConnectionRecord(
            id=connection.id,
            userId=connection.userId,
            tokens=tokens,
            connectionId=connection.connectionId,
            name=connection.name,
            updatedAt=connection.updatedAt,
            createdAt=connection.createdAt
        );
    }
    raise Exception("Failed to decrypt connection tokens");
}

def:pub isMerchant(merchantIntegrations: list[str]) -> Callable[[ConnectionRecord], bool] {
    return lambda (connection: ConnectionRecord) -> bool { return connection.name in merchantIntegrations; };
}

def toMapById(connections: list[ConnectionRecord]) -> StrictMap[str, ConnectionRecord] {
    return StrictMap([(connection.id, connection) for connection in connections]);
}

def toMapByName(connections: list[ConnectionRecord]) -> StrictMap[ConnectionName, ConnectionRecord] {
    return StrictMap([(connection.name, connection) for connection in connections]);
}

glob:pub Connection = {
    "toMapById": toMapById,
    "toMapByName": toMapByName,
    "withDecryptedTokens": withDecryptedTokens,
    "isMerchant": isMerchant(list(merchantConfig.merchantIntegrations.keys())),
};

