def toInstruction(raw: object | None) -> dict[str, str | list[str]] {
    item = raw if isinstance(raw, dict) else {};
    instruction: dict[str, str | list[str]] = {
        "id": str(item.get("id", "")),
        "label": str(item.get("label", "")),
        "steps": [str(s) for s in item.get("steps", [])] if isinstance(item.get("steps"), list) else [],
    };
    command = item.get("command");
    if isinstance(command, str) {
        instruction["command"] = command;
    }
    return instruction;
}

def:pub toUpdateCheck(raw: dict[str, object]) -> dict[str, object] {
    latest_val = raw.get("latest");
    instructions_raw = raw.get("instructions");
    update: dict[str, object] = {
        "ok": raw.get("ok") is not False,
        "current": str(raw.get("current", "0.0.0")),
        "latest": latest_val if isinstance(latest_val, str) else None,
        "source": str(raw.get("source", "npm")),
        "updateAvailable": raw.get("update_available") is True,
        "canApply": raw.get("can_apply") is True,
        "manualRequired": raw.get("manual_required") is True,
        "installMethod": str(raw.get("install_method", "unknown")),
        "instructions": [toInstruction(i) for i in instructions_raw] if isinstance(instructions_raw, list) else [],
    };
    checked_at = raw.get("checked_at");
    if isinstance(checked_at, str) {
        update["checkedAt"] = checked_at;
    }
    error_val = raw.get("error");
    if isinstance(error_val, str) {
        update["error"] = error_val;
    }
    message_val = raw.get("message");
    if isinstance(message_val, str) {
        update["message"] = message_val;
    }
    return update;
}

