export const modifyResponsiveValue = (value, cb) => {
  if (typeof value === 'string' || typeof value === 'number') {
    return cb(value);
  } else if (Array.isArray(value)) {
    return value.map(cb);
  } else {
    const newObj = {};
    Object.keys(value).forEach((k) => (newObj[k] = cb(value[k])));
    return newObj;
  }
};

jac:
def:pub modifyResponsiveValue(
    value: str | int | list[object] | dict[str, object],
    cb: Callable[[object], object]
) -> object {
    if isinstance(value, str) or isinstance(value, int) {
        return cb(value);
    } elif isinstance(value, list) {
        return [cb(item) for item in value];
    } else {
        new_obj: dict[str, object] = {};
        for k in value {
            new_obj[k] = cb(value[k]);
        }
        return new_obj;
    }
}

