import from "./render-props.jac" { parseRenderProps }
import from "./start-props.jac" { parseStartProps }
import from "./next-props.jac" { parseNextProps }
import from "./test-props.jac" { parseTestProps }

def parseForProps(props: dict) -> dict[str, object] {
    return {
        **parseRenderProps(props),
        **parseStartProps(props),
        **parseTestProps(props),
        **parseNextProps(props)
    };
}

def:pub For(props: dict) -> JsxElement {
    parsed = parseForProps(props);
    render = parsed["render"] as Callable[[object], JsxElement];
    start = parsed["start"];
    test = parsed["test"] as Callable[[object], bool];
    next = parsed["next"] as Callable[[object], object];
    results: list[JsxElement] = [];
    i = start;
    while test(i) {
        results = results + [render(i)];
        i = next(i);
    }
    return <>{results}</>;
}

