import { WHITE_SPACE_CODE } from '.';

export const splitChildrenToFragments = (children: ReactText) =>
  children.toString().split(' ');

export const concatFragments = (children: ReactText) => {
  const splittedChildren = splitChildrenToFragments(children);

  return ([] as string[])
    .concat(
      ...splittedChildren.map((word, index) =>
        index !== 0 ? [WHITE_SPACE_CODE, word] : [word]
      )
    )
    .map((word) => (word === ' ' ? WHITE_SPACE_CODE : word));
};

jac:
import from "." { WHITE_SPACE_CODE }

def:pub splitChildrenToFragments(children: str | int) -> list[str] {
    return str(children).split(" ");
}

def:pub concatFragments(children: str | int) -> list[str] {
    splittedChildren = splitChildrenToFragments(children);
    parts: list[str] = [];
    for (index, word) in enumerate(splittedChildren) {
        if index != 0 {
            parts.append(WHITE_SPACE_CODE);
        }
        parts.append(word);
    }
    return [(WHITE_SPACE_CODE if word == " " else word) for word in parts];
}

