def:pub AvatarImage(src: str, name: str, className: str | None = None) -> JsxElement {
    has hasError: bool = False;
    ch = name[0] if len(name) > 0 else "";
    initial = ch.upper() if ch else "?";
    sizeClass = className if className else "h-10 w-10";
    textSize = "text-2xl" if "h-20" in sizeClass else ("text-lg" if "h-14" in sizeClass else "text-sm");
    if not src or hasError {
        return <div className={f"flex shrink-0 items-center justify-center rounded-full bg-surface font-bold text-muted {textSize} {sizeClass}"}>{initial}</div>;
    }
    def handle_error(_e: Event) {
        hasError = True;
    }
    <img src={src} alt={name} className={f"shrink-0 rounded-full object-cover {sizeClass}"} onError={handle_error} />
}

