import type Appsignal from "@appsignal/javascript"
import type { Breadcrumb } from "@appsignal/javascript"

const SUPPORTED_CONSOLE_METHODS = ["log", "debug", "info", "warn", "error"]

function consoleBreadcrumbsPlugin(options?: { [key: string]: any }) {
  const CONSOLE_LOG_METHODS = SUPPORTED_CONSOLE_METHODS.filter(
    (method: string) =>
      typeof console !== "undefined" &&
      typeof (console as any)[method] === "function"
  )

  return function (this: Appsignal) {
    const self = this

    CONSOLE_LOG_METHODS.forEach((method: string) => {
      const prevHandler = (console as any)[method]

      function _console(...args: any[]) {
        const breadcrumb: Omit<Breadcrumb, "timestamp"> = {
          action:
            args.length > 1
              ? "Console logged some values"
              : "Console logged a value",
          category: `console.${method}`,
          metadata: {}
        }

        args.forEach(
          (arg, i) =>
            // we're sure the `metadata` property exists
            (breadcrumb.metadata![`argument${i}`] =
              // attempt to get a useful value
              // the `metadata` object should be <string, string>, so nested
              // objects won't necessarily work here
              serializeValue(arg, method))
        )

        self.addBreadcrumb(breadcrumb)

        prevHandler.apply(console, args)
      }

      ;(console as any)[method] = _console
    })
  }
}

function serializeValue(value: any, method: string) {
  switch (typeof value) {
    case "string":
      return value
    case "undefined":
      return "undefined"
    default:
      try {
        return JSON.stringify(value, circularReplacer())
      } catch (e) {
        // Stringifying the value may cause a RangeError when the reason
        // is a very large object.
        if (e && typeof (e as any).message === "string") {
          return `[could not stringify value: ${(e as any).message}]`
        }
        return "[could not stringify value]"
      }
  }
}

function circularReplacer() {
  const seenValue: any[] = []
  const seenKey: string[] = []
  return (key: string, value: any) => {
    if (typeof value === "object" && value !== null) {
      const i = seenValue.indexOf(value)
      if (i !== -1) {
        return `[cyclic value: ${seenKey[i] || "root object"}]`
      } else {
        seenValue.push(value)
        seenKey.push(key)
      }
    }

    return value
  }
}

export const plugin = consoleBreadcrumbsPlugin

import type Appsignal from "@appsignal/javascript"

type PluginOptions = {
  // A boolean value representing whether the plugin should bind to `XMLHttpRequest`
  xhrEnabled: boolean
  // A boolean value representing whether the plugin should bind to `fetch`
  fetchEnabled: boolean
  // If any of the patterns match a request URL, then that request is ignored
  // Caution: don't add too many `RegExp`s to this array, otherwise network requests
  // will become very slow.
  ignoreUrls: RegExp[]
}

// Default options
const DEFAULTS = {
  xhrEnabled: true,
  fetchEnabled: true,
  ignoreUrls: []
}

/**
 * Automatically adds a breadcrumb on every network request.
 */
function networkBreadcrumbsPlugin(options?: Partial<PluginOptions>) {
  const opts = { ...DEFAULTS, ...options }
  const { xhrEnabled, fetchEnabled, ignoreUrls } = opts

  // feature detect browser features if they are enabled
  const isXhrEnabled = xhrEnabled ? "XMLHttpRequest" in window : false
  const isFetchEnabled = fetchEnabled ? "fetch" in window : false

  return function (this: Appsignal): void {
    const appsignal = this

    const xhrPatch = () => {
      const prevOpen = XMLHttpRequest.prototype.open

      // per the spec, this could be caled with more arguments,
      // but we just need `method` and `url` here. the rest are
      // passed to `prevOpen` later.
      function open(this: XMLHttpRequest, method: string, url: string): void {
        const metadata = { method, url }

        function onXhrLoad(this: XMLHttpRequest) {
          if (!ignoreUrls.some(el => el.test(url))) {
            appsignal.addBreadcrumb({
              action:
                this.status >= 400
                  ? `Request failed with code ${this.status}`
                  : `Received a response with code ${this.status}`,
              category: "XMLHttpRequest",
              metadata
            })
          }
        }

        function onXhrError(this: XMLHttpRequest) {
          if (!ignoreUrls.some(el => el.test(url))) {
            appsignal.addBreadcrumb({
              action: "Request failed",
              category: "XMLHttpRequest",
              metadata
            })
          }
        }

        // set handlers
        this.addEventListener("load", onXhrLoad)
        this.addEventListener("error", onXhrError)

        prevOpen.apply(this, arguments as any)
      }

      XMLHttpRequest.prototype.open = open
    }

    const fetchPatch = () => {
      const originalFetch = window.fetch

      function fetch(
        input: RequestInfo,
        init?: RequestInit
      ): Promise<Response> {
        const url = typeof input === "string" ? input : input.url

        // Assume a GET request if we can't infer the method
        const method =
          (typeof input !== "string" && input.method) ||
          (init && init.method) ||
          "GET"

        const metadata = {
          method,
          url
        }

        if (ignoreUrls.some(el => el.test(url))) {
          return originalFetch.apply(window, arguments as any)
        }

        return originalFetch
          .apply(window, arguments as any)
          .then((response: Response) => {
            // re-assign to fix some browsers not liking when you
            // access `response.status` directly
            const { status: statusCode } = response

            appsignal.addBreadcrumb({
              action: `Received a response with code ${statusCode}`,
              category: "Fetch",
              metadata
            })

            return response
          })
          .catch((error: Error) => {
            appsignal.addBreadcrumb({
              action: "Request failed",
              category: "Fetch",
              metadata
            })

            throw error
          })
      }

      window.fetch = fetch
    }

    if (isXhrEnabled) xhrPatch()
    if (isFetchEnabled) fetchPatch()
  }
}

export const plugin = networkBreadcrumbsPlugin

import type Appsignal from "@appsignal/javascript"
import type { Span } from "@appsignal/javascript"

export function installErrorHandler(appsignal: Appsignal, application: any) {
  const prevHandler = application.handleError

  application.handleError = function (
    error: Error,
    message: string,
    detail: { identifier?: string }
  ) {
    const span = appsignal.createSpan((span: Span) =>
      span
        .setAction(detail?.identifier || "[unknown Stimulus controller]")
        .setTags({ framework: "Stimulus", message })
        .setError(error)
    )

    appsignal.send(span)

    if (prevHandler && typeof prevHandler === "function") {
      prevHandler.apply(this, arguments as any)
    }
  }
}

