import math;
import from datetime { datetime }

type GenerationMode = str;

obj AccountHealth {
    has loginState: str | None = None;
    has cooldownUntil: str | None = None;
    has verificationRequired: bool = False;
    has consecutiveFailures: int = 0;
}

obj SeedanceQuota {
    has exhausted: bool = False;
    has estimatedTotalUnits: int = 0;
    has usedUnits: int = 0;
}

obj AccountScheduling {
    has enabled: bool = True;
    has manualCooldownUntil: str | None = None;
    has preferredModes: list[str] = [];
    has weight: float = 1.0;
}

obj Account {
    has status: str;
    has health: AccountHealth | None = None;
    has seedanceQuota: SeedanceQuota | None = None;
    has scheduling: AccountScheduling | None = None;
    has pinned: bool = False;
}

def _to_epoch_ms(value: str) -> int {
    normalized = value.replace("Z", "+00:00");
    return int(datetime.fromisoformat(normalized).timestamp() * 1000);
}

def getAccountSchedulingScore(
    account: Account,
    load: int,
    mode: GenerationMode,
    now: int = 0,
) -> float {
    ts = now if now else int(datetime.now().timestamp() * 1000);
    health = account.health;
    if account.status == "error" {
        return math.inf;
    }
    if health is not None and health.loginState == "expired" {
        return math.inf;
    }
    if health is not None and health.cooldownUntil {
        if _to_epoch_ms(health.cooldownUntil) > ts {
            return math.inf;
        }
    }
    if health is not None and health.verificationRequired {
        return math.inf;
    }
    if mode == "video" and account.seedanceQuota is not None and account.seedanceQuota.exhausted {
        return math.inf;
    }
    if account.scheduling is not None and account.scheduling.enabled is False {
        return math.inf;
    }
    if account.scheduling is not None and account.scheduling.manualCooldownUntil {
        if _to_epoch_ms(account.scheduling.manualCooldownUntil) > ts {
            return math.inf;
        }
    }

    quota_remaining = 0;
    if account.seedanceQuota {
        quota_remaining = max(
            0,
            account.seedanceQuota.estimatedTotalUnits - account.seedanceQuota.usedUnits,
        );
    }
    failure_penalty = (health.consecutiveFailures if health else 0) * 4;
    quota_bonus = min(quota_remaining, 10) * 0.25 if mode == "video" else 0.0;
    preference_bonus = 0.0;
    if account.scheduling and mode in account.scheduling.preferredModes {
        preference_bonus = 2.0;
    }
    weight = account.scheduling.weight if account.scheduling else 1.0;
    pinned_bonus = 0.5 if account.pinned else 0.0;
    return (load * 10 + failure_penalty - quota_bonus - preference_bonus - pinned_bonus) / weight;
}

