import from "lib/hooks" { useOffsetCalculator }
import from "lib/components/TimelineProvider" { useTimelineContext }

def:pub TimelineTimeIndicator(render: Callable[[dict[str, Callable[[object], dict[str, object]]]], JsxElement | None]) -> JsxElement | None {
    ctx = useTimelineContext();
    direction = ctx.direction;
    calcOffset = useOffsetCalculator();
    isHorizontalTimeline = (direction == "horizontal");

    def getIndicatorStyles(date: object) -> dict[str, object] {
        if isHorizontalTimeline {
            return {"position": "absolute", "left": calcOffset(date)};
        }
        return {"position": "absolute", "top": calcOffset(date)};
    }

    return render({"getIndicatorStyles": getIndicatorStyles});
}

