                  message.success('删除成功');
                  tableRef.current?.freshRequest();
                });
              }}
            />
          </Authorized>
        </Space>
      ),
    },
  ];

  return (
    <PageWrapper className={styles.UserManage} header={{ title: '基础列表页' }}>
      <SuperTable
        ref={tableRef}
        service={requestList}
        searchForm={searchFormConfig}
        enableIndex="fixedLeft"
        tableProps={{ rowKey: 'id', columns, scroll: { x: 1600 } }}
      />
    </PageWrapper>
  );
}

