def relative(ts: float) -> str {
    diff = Date.now() - ts;
    d = Math.round(diff / 86400000);
    if d == 0 {
        return "today";
    }
    if d == 1 {
        return "yesterday";
    }
    if d < 30 {
        return f"{d}d ago";
