    has imageModalOpen: bool = False;
    isOwn = False;
    seenUsers = data.seen or [];
    seenList = ", ".join([
        user.name or ""
        for user in seenUsers
        if user.email != data.sender.email
    ]);
    container = clsx("flex gap-3 p-4", isOwn and "justify-end");
    avatar = clsx(isOwn and "order-2");
    body = clsx("flex flex-col gap-2", isOwn and "item-end");
    message = clsx(
        "text-sm w-fit overflow-hidden",
        "bg-sky-500 text-white" if isOwn else "bg-gray-100",
        "rounded-md p-0" if data.image else "rounded-full py-2 px-3"
    );

    def close_image_modal() {
        imageModalOpen = False;
    }

    def open_image_modal() {
        imageModalOpen = True;
    }

    <div className={container}>
        <div className={avatar}>
            <Avatar user={data.sender} />
        </div>
        <div className={body}>
            <div className="flex items-center gap-1">
                <p className="text-sm text-gray-500">{data.sender.name}</p>
                <time
                    dateTime={format(new(Date, data.createdAt), "p")}
                    className="text-xs text-gray-400"
                >
                    {format(new(Date, data.createdAt), "p")}
                </time>
            </div>
            <div className={message}>
                {if data.image {
                    <>
                        <ImageModal
                            src={data.image}
                            isOpen={imageModalOpen}
                            onClose={close_image_modal}
                        />
                        <button
                            onClick={open_image_modal}
                            className="cursor-pointer focus:outline-sky-500"
                        >
                            <img
                                src={data.image}
                                alt="image"
                                height={288}
                                width={288}
                                className="object-cover hover:scale-110 transition translate"
                            />
                        </button>
                    </>
                } else {
                    <p>{data.body}</p>
                }}
            </div>
            {if isLast and isOwn and len(seenList) > 0 {
                <span className="text-xs font-light text-gray-500">
                    {f"Seen by {seenList}"}
                </span>
            }}
        </div>
    </div>
}

