import faker from 'faker';
import { set, add } from 'date-fns';
import {
  MAX_EMPLOYEES,
  BREAK_EVENT_MAX_DURATION,
  WORK_EVENT_MAX_DURATION,
  MAX_TASKS_PER_DAY_PER_EMPLOYEE,
  WORK_START_TIME,
} from 'config/constants';
import type { Employee, WorkLogRecord, WorkLogEvent, WorkLogEventType } from '../types';

faker.seed(123);

const employees: Employee[] = new Array(faker.datatype.number(MAX_EMPLOYEES)).fill(null).map(() => ({
  id: faker.datatype.uuid(),
  fullName: `${faker.name.firstName()} ${faker.name.lastName()}`,
}));

export default (activeDate: Date): WorkLogRecord[] =>
  employees.map((employee) => ({
    id: faker.datatype.uuid(),
    employee,
    events: generateEvents(activeDate),
  }));

function generateEvents(date: Date): WorkLogEvent[] {
  const workStartDate: Date = set(date, WORK_START_TIME);

  return new Array(faker.datatype.number(MAX_TASKS_PER_DAY_PER_EMPLOYEE))
    .fill(null)
    .reduce<WorkLogEvent[]>((events, _, index) => {
      const startDate: Date = index ? new Date(events[index - 1].endDate) : workStartDate;
      const type: WorkLogEventType = index % 2 ? 'break' : 'work';

      const isWorkEvent: boolean = type === 'work';
      const endDateMaxDuration = isWorkEvent ? WORK_EVENT_MAX_DURATION : BREAK_EVENT_MAX_DURATION;

      events.push({
        id: faker.datatype.uuid(),
        startDate,
        endDate: add(startDate, {
          hours: faker.datatype.number(endDateMaxDuration.hours),
          minutes: endDateMaxDuration.minutes,
        }),
        type,
      });

      return events;
    }, []);
}

jac:
import faker;
import from "date-fns" { set, add }

glob MAX_EMPLOYEES: int = 10;
glob MAX_TASKS_PER_DAY_PER_EMPLOYEE: int = 8;
glob WORK_START_TIME: dict[str, int] = {"hours": 9, "minutes": 0, "seconds": 0, "milliseconds": 0};
glob WORK_EVENT_MAX_DURATION: dict[str, int] = {"hours": 4, "minutes": 0};
glob BREAK_EVENT_MAX_DURATION: dict[str, int] = {"hours": 0, "minutes": 30};

obj Employee {
    has id: str,
        fullName: str;
}

obj WorkLogEvent {
    has id: str,
        startDate: object,
        endDate: object,
        type: str;
}

obj WorkLogRecord {
    has id: str,
        employee: Employee,
        events: list[WorkLogEvent];
}

def _buildEmployees() -> list[Employee] {
    faker.seed(123);
    return [
        Employee(
            id=faker.datatype.uuid(),
            fullName=f"{faker.name.firstName()} {faker.name.lastName()}"
        )
        for _ in range(faker.datatype.number(MAX_EMPLOYEES))
    ];
}

glob employees: list[Employee] = _buildEmployees();

def generateEvents(date: object) -> list[WorkLogEvent] {
    workStartDate = set(date, WORK_START_TIME);
    events: list[WorkLogEvent] = [];
    count = faker.datatype.number(MAX_TASKS_PER_DAY_PER_EMPLOYEE);
    for index in range(count) {
        startDate = new(Date, events[index - 1].endDate) if index else workStartDate;
        eventType = "break" if index % 2 else "work";
        isWorkEvent = eventType == "work";
        endDateMaxDuration = WORK_EVENT_MAX_DURATION if isWorkEvent else BREAK_EVENT_MAX_DURATION;
        events.append(WorkLogEvent(
            id=faker.datatype.uuid(),
            startDate=startDate,
            endDate=add(startDate, {
                "hours": faker.datatype.number(endDateMaxDuration["hours"]),
                "minutes": endDateMaxDuration["minutes"]
            }),
            type=eventType
        ));
    }
    return events;
}

def generateWorkLogRecords(activeDate: object) -> list[WorkLogRecord] {
    return [
        WorkLogRecord(
            id=faker.datatype.uuid(),
            employee=employee,
            events=generateEvents(activeDate)
        )
        for employee in employees
    ];
}

