def:pub SettingsSectionItemToggle(
    label: str,
    value: bool,
    onInput: Callable[[bool], None],
    description: str | None = None,
) -> JsxElement {
    track_cls = (
        "bg-green-500 border-green-500"
        if value
        else "bg-gray-200 border-gray-200 dark:bg-gray-700 dark:border-gray-700"
    );
    thumb_cls = "translate-x-[18px]" if value else "translate-x-0.5";

    return (
        <div className="flex-grow flex items-center justify-between">
            <label className="flex-grow pr-4 cursor-pointer select-none">
                <p className="font-semibold leading-normal text-gray-900 dark:text-white">{label}</p>
                {(
                    <p className="text-sm text-gray-500 dark:text-gray-400">{description}</p>
                    if description
                    else None
                )}
            </label>
            <button
                type="button"
                role="switch"
                aria-checked={value}
                onClick={lambda { onInput(not value); }}
                className={
                    track_cls
                    + " relative inline-flex flex-shrink-0 h-6 w-10 rounded-full cursor-pointer transition-colors ease-in-out duration-200 focus-visible-ring ring-offset-gray-100 dark:ring-offset-gray-800"
                }
            >
                <span
                    aria-hidden={True}
                    className={
                        thumb_cls
                        + " pointer-events-none inline-block h-5 w-5 rounded-full bg-white translate-y-0.5 shadow-lg transform ring-0 transition ease-in-out duration-200"
                    }
                />
            </button>
        </div>
    );
}

