'use client';

import { useEffect } from 'react';

const ContentComponentIncludes = ({ contextPath, serializedNode }: { contextPath: string; serializedNode: any }) => {
  const serializedNodeProps = Object.values(serializedNode.properties);
  // Use useEffect to prevent errors with rehydration to set Neos metadata
  useEffect(() => {
    (window as any)['@Neos.Neos.Ui:Nodes'] = {
      ...(window as any)['@Neos.Neos.Ui:Nodes'],
      [contextPath]: serializedNode,
    };
  }, [...serializedNodeProps]);

  return null;
};

export default ContentComponentIncludes;

jac:
def:pub ContentComponentIncludes(contextPath: str, serializedNode: dict[str, object]) -> None {
    props = serializedNode["properties"] as dict[str, object];
    serializedNodeProps = Object.values(props);
    useEffect(lambda () {
        prev = window["@Neos.Neos.Ui:Nodes"] as dict[str, object];
        merged = {**prev};
        merged[contextPath] = serializedNode;
        window["@Neos.Neos.Ui:Nodes"] = merged;
    }, [*serializedNodeProps]);
    return None;
}

