import type { AdjustType } from '@/types';
import styles from './Toolbar.module.css';

interface ToolbarProps {
  adjust: AdjustType;
  onAdjustChange: (adjust: AdjustType) => void;
  canUndo: boolean;
  canRedo: boolean;
  onUndo: () => void;
  onRedo: () => void;
  onZoomIn: () => void;
  onZoomOut: () => void;
  onPanLeft: () => void;
  onPanRight: () => void;
  onReset: () => void;
  onFullscreen?: () => void;
  /** 是否显示缩放/平移/撤销重做/重置按钮组（当前周期关闭 dataZoom 时应隐藏），默认 true */
  showZoomControls?: boolean;
}

