import from "@/lib/utils" { cn }

def alertVariants(variant: str = "default") -> str {
    base = "relative w-full rounded-lg border px-4 py-3 text-sm [&>svg+div]:translate-y-[-3px] [&>svg]:absolute [&>svg]:left-4 [&>svg]:top-4 [&>svg]:text-foreground [&>svg~*]:pl-7";
    if variant == "destructive" {
        return cn(
            base,
            "border-destructive/50 text-destructive dark:border-destructive [&>svg]:text-destructive"
        );
    }
    return cn(base, "bg-background text-foreground");
}

def:pub Alert(className: str = "", variant: str = "default", props: dict = {}, ref: object = None) -> JsxElement {
    <div ref={ref} role="alert" className={cn(alertVariants(variant), className)} {**props} />
}

def:pub AlertTitle(className: str = "", props: dict = {}, ref: object = None) -> JsxElement {
    <h5
        ref={ref}
        className={cn("mb-1 font-medium leading-none tracking-tight", className)}
        {**props}
    />
}

def:pub AlertDescription(className: str = "", props: dict = {}, ref: object = None) -> JsxElement {
    <div ref={ref} className={cn("text-sm [&_p]:leading-relaxed", className)} {**props} />
}

