import { z } from "zod";

/** Translation function type */
type TranslateFn = (key: string) => string;

/**
 * Create change password schema with translated messages
 * @param t - Translation function from useTranslation hook
 */
export function createChangePasswordSchema(t: TranslateFn) {
    return z
        .object({
            currentPassword: z.string().min(1, t("validation.password.required")),
            newPassword: z
                .string()
                .min(8, t("validation.password.min"))
                .max(128, t("validation.password.max")),
            confirmPassword: z.string(),
            revokeOtherSessions: z.boolean().optional(),
        })
        .refine((data) => data.newPassword === data.confirmPassword, {
            message: t("validation.confirmPassword.mismatch"),
            path: ["confirmPassword"],
        });
}

/**
 * Change password schema (for type inference)
 */
export const changePasswordSchema = createChangePasswordSchema((key) => key);

export type ChangePasswordInput = z.infer<typeof changePasswordSchema>;

