def:pub genObjectId() -> float {
    timestamp = int(new(Date).getTime() / 1000);
    return timestamp + Math.random() * 16;
}

def:pub zip[T, U](arr1: list[T], arr2: list[U]) -> list[list[T | U]] {
    if len(arr1) != len(arr2) {
        raise ValueError("arrays must be same length");
    }
    return [[arr1[i], arr2[i]] for i in range(len(arr1))];
}

def:pub omitText(text: str) -> Callable[[int], Callable[[str], str]] {
    return lambda (maxLen: int) -> Callable[[str], str] {
        return lambda (ellipsis: str) -> str {
            return (text[0:(maxLen - len(ellipsis))] + ellipsis) if len(text) >= maxLen else text;
        };
    };
}

def:pub isString(val: object) -> bool {
    return isinstance(val, str);
}

def:pub groupBy(objects: list[dict[str, object]], key: str) -> dict[str, list[dict[str, object]]] {
    map: dict[str, list[dict[str, object]]] = {};
    for obj in objects {
        bucket_key = str(obj[key]);
        if bucket_key not in map {
            map[bucket_key] = [];
        }
        map[bucket_key].append(obj);
    }
    return map;
}

def:pub nonNullable(value: object) -> bool {
    return value is not None;
}

def:pub match(val: object) -> dict[str, object] {
    return {
        "on": lambda (_pred: Callable[[object], bool], _fn: Callable[[], object]) -> dict[str, object] {
            return match(val);
        },
        "otherwise": lambda (_fn: Callable[[], object]) -> object {
            return val;
        },
    };
}

def:pub chain(val: object) -> dict[str, object] {
    return {
        "on": lambda (pred: Callable[[object], bool], fn: Callable[[], object]) -> dict[str, object] {
            return match(fn()) if pred(val) else chain(val);
        },
        "otherwise": lambda (fn: Callable[[], object]) -> object {
            return fn();
        },
    };
}

def:pub when(val: object) -> dict[str, object] {
    return {
        "on": lambda (pred: Callable[[object], bool], fn: Callable[[], object]) -> dict[str, object] {
            return match(fn()) if pred(val) else chain(val);
        },
    };
}

def:pub eq(val1: object) -> Callable[[object], bool] {
    return lambda (val2: object) -> bool { return val1 == val2; };
}

