def:pub planLoginRoute(result: MeResult) -> dict[str, object] {
    if result.ok {
        return {"action": "redirect", "to": "/"};
    }
    if result.status == 401 {
        return {"action": "render"};
    }
    return {"action": "rethrow", "error": result.error};
}

def:pub planLogoutRoute(result: MeResult) -> dict[str, object] {
    if result.ok {
        me = result.me as MeResponse;
        if me.mode == "session" {
            return {"action": "endSessionThenRedirect", "to": "/login"};
        }
        return {"action": "redirect", "to": "/"};
    }
    if result.status == 401 {
        return {"action": "redirect", "to": "/login"};
    }
    return {"action": "rethrow", "error": result.error};
}

