        classification = data["value_classification"] as str;
        fg_class = "".join(classification.split(" "));
        fg_class = fg_class[0].lower() + fg_class[1:];
        fearGreedClass = fg_class;
        fearGreedIndex = data["value"] as int;
    }

    can with entry {
        sync_from_data();
    }

    arc_color = get_color_for_index(fearGreedIndex);
    gauge_sx = {f"& .{gaugeClasses.valueArc}": {"fill": arc_color}};

    <>
        <Stack direction="column" spacing={0} sx={{"justifyContent": "center", "alignItems": "center"}}>
            <Gauge width={100} height={87} value={fearGreedIndex} startAngle={-100} endAngle={100} sx={gauge_sx} />
