}

def:pub applyFilterUpdate[TSearch, TFilters](
    prev: TSearch,
    updater: Callable[[TFilters], TFilters],
    codec: FilterCodec[TSearch, TFilters],
) -> TSearch {
    next = updater(codec.decode(prev));
    reset_on_change = codec.resetOnChange if codec.resetOnChange is not None else {};
    return {**prev, **codec.encode(next), **reset_on_change};
}

