import from "../constants" { ACCESS_KEY, REFRESH_KEY }
import from "../errors" { StorageError }
import from "../jwt/decode" { decodeJwt }
import time;

obj CookieConfig {
    has path: str | None = None;
    has domain: str | None = None;
    has secure: bool | None = None;
    has sameSite: str | None = None;
    has maxAge: int | str | None = None;
}

glob DEFAULT_PATH = "/";

glob DEFAULT_SAME_SITE = "strict";

def:pub parseCookieString(cookie_str: str) -> dict[str, str] {
    result: dict[str, str] = {};
    segments: list[str] = cookie_str.split(";");
    for pair_str in segments {
        trimmed = pair_str.strip();
        if not trimmed {
            continue;
        }
        eqIdx = trimmed.index("=");
        if eqIdx == -1 {
            continue;
        }
        name = trimmed[0:eqIdx].strip();
        value = trimmed[(eqIdx + 1):].strip();
        if name {
            try {
                result[name] = decodeURIComponent(value) as str;
            } except Exception {
                result[name] = value;
            }
        }
    }
    return result;
}

def capitalizeSameSite(sameSite: str) -> str {
    return sameSite[0].upper() + sameSite[1:];
}

def resolveSecure(config: CookieConfig, sameSite: str) -> bool {
    if sameSite == "none" {
        return True;
    }
    if config.secure is not None {
        return config.secure;
    }
    return (location is not None) and (location.protocol == "https:");
}

def resolveMaxAge(value: str, maxAge: int | str | None) -> int | None {
    if maxAge is None {
        return None;
    }
    if isinstance(maxAge, int) {
        return maxAge;
    }
    try {
        payload = decodeJwt[dict[str, int]](value);
        if "exp" in payload {
            return max(0, int(payload["exp"]) - int(time.time()));
        }
    } except Exception {
    }
    return None;
}

def buildCookieString(key: str, value: str, config: CookieConfig) -> str {
    sameSite = config.sameSite if config.sameSite is not None else DEFAULT_SAME_SITE;
    secure = resolveSecure(config, sameSite);
    maxAge = resolveMaxAge(value, config.maxAge);
    parts: list[str] = [
        f"{key}={encodeURIComponent(value) as str}",
        f"Path={config.path if config.path is not None else DEFAULT_PATH}",
        f"SameSite={capitalizeSameSite(sameSite)}",
    ];
    if config.domain {
        parts.append(f"Domain={config.domain}");
    }
    if secure {
        parts.append("Secure");
    }
    if maxAge is not None {
        parts.append(f"Max-Age={maxAge}");
    }
    return "; ".join(parts);
}

def buildRemoveCookieString(key: str, config: CookieConfig) -> str {
    sameSite = config.sameSite if config.sameSite is not None else DEFAULT_SAME_SITE;
    secure = resolveSecure(config, sameSite);
    parts: list[str] = [
        f"{key}=",
        f"Path={config.path if config.path is not None else DEFAULT_PATH}",
        f"SameSite={capitalizeSameSite(sameSite)}",
        "Max-Age=0",
    ];
    if config.domain {
        parts.append(f"Domain={config.domain}");
    }
    if secure {
        parts.append("Secure");
    }
    return "; ".join(parts);
}

def resolveDocument() -> object {
    if document is None {
        raise StorageError("Cookie storage is not available in this environment");
    }
    return document;
}

class CookieStorageAdapter {
    has config: CookieConfig = CookieConfig();

    def init(config: CookieConfig | None = None) {
        if config is not None {
            self.config = config;
        }
    }

    def get(key: str) -> str | None {
        doc = resolveDocument();
        cookies = parseCookieString((doc as dict)["cookie"] as str);
        return cookies.get(key);
    }

    def set(key: str, value: str) {
        doc = resolveDocument();
        (doc as dict)["cookie"] = buildCookieString(key, value, self.config);
    }

    def remove(key: str) {
        doc = resolveDocument();
        (doc as dict)["cookie"] = buildRemoveCookieString(key, self.config);
    }
}

