def:pub FollowingButton(isLoading: bool, followId: str, userId: str, onClick: Callable[[MouseEvent], Awaitable[None]]) -> JsxElement {
    has isFollowing: bool = False;

    def handle_click(e: MouseEvent) {
        onClick(e);
        isFollowing = not isFollowing;
    }

    <Box sx={{"display": "flex"}}>
        <Box sx={{"width": "100%", "alignItems": "center", "position": "relative", "marginRight": "10px"}}>
            <Button
                variant={("contained" if isFollowing else "outlined")}
                color="warning"
                size="small"
                sx={{"height": "30px", "width": "60px", "marginRight": "0.5rem", "padding": "0.5rem", "boxSizing": "border-box", "transition": "background-color .3s ease-out"}}
                data-followid={followId}
                data-userid={userId}
                disabled={isLoading}
                onClick={handle_click}
            >
                {("팔로우" if isFollowing else "언팔")}
            </Button>
        </Box>
    </Box>
}

