def:pub SignUpInput(
    placeholder: str,
    innerText: str | None,
    type: str,
    name: str,
    errorMsg: str | None,
    value: str,
    maxLength: str,
    isName: bool | None,
    duplicate: Callable[[], None] | None,
    onChange: Callable[[ChangeEvent], None] | None,
