            }
            isOverByScroll = False;
        }
        document.addEventListener("scroll", scroll_event);
        return lambda {
            document.removeEventListener("scroll", scroll_event);
        };
    }, []);

    return {"ref": ref, "isOverByScroll": isOverByScroll};
}

