import from "react" { useCallback, useEffect, useRef }

obj TimeoutFnProps {
    has fn: Callable[[], None];
    has ms: int;
}

def:pub useTimeoutFn(props: TimeoutFnProps) -> list[Callable[[], None]] {
    fn = props.fn;
    ms = props.ms;
    timeoutId = useRef(0);
    callback = useRef(fn);
    useEffect(lambda { callback.current = fn; }, [fn]);
    run = useCallback(lambda {
        if timeoutId.current {
            clearTimeout(timeoutId.current);
        }
        timeoutId.current = setTimeout(lambda { callback.current(); }, ms);
    }, [ms]);
    clear = useCallback(lambda {
        if timeoutId.current {
            clearTimeout(timeoutId.current);
        }
    }, [timeoutId]);
    useEffect(lambda { return clear; }, [clear]);
    return [run, clear];
}

