import from "react" { useContext, useEffect, useRef }
import from "./compute" { CallElement, Return }

def:pub One() -> JsxElement {
    <div data-type="nat" />
}

def _N_0() -> JsxElement {
    return <></>;
}

def _N_1() -> JsxElement {
    return <One />;
}

def _N_2() -> JsxElement {
    return <><One /><One /></>;
}

def _N_3() -> JsxElement {
    return <><One /><One /><One /></>;
}

def _N_4() -> JsxElement {
    return <><One /><One /><One /><One /></>;
}

def _N_5() -> JsxElement {
    return <><One /><One /><One /><One /><One /></>;
}

glob:pub N: dict[str, Callable[[], JsxElement]] = {
    "_0": _N_0,
    "_1": _N_1,
    "_2": _N_2,
    "_3": _N_3,
    "_4": _N_4,
    "_5": _N_5,
};

def:pub numberToNode(n: int) -> JsxElement {
    ones = [<One key={str(i)} /> for i in range(n)];
    return <>{ones}</>;
}

def:pub Add(children: object | None = None) -> JsxElement {
    onReturn = useContext(Return);
    ref = useRef(None);

    useEffect(lambda {
        nodes = ref.current.querySelectorAll('[data-type="nat"]') if ref.current else [];
        count = len(nodes);
        onReturn(count);
    }, [children, onReturn]);

    return <div ref={ref}>{children}</div>;
}

def:pub Multiply(a: object, b: object) -> JsxElement {
    def render_rows(aNum: int) -> JsxElement {
        return <Add>{[<>{b}</> for _ in range(aNum)]}</Add>;
    }
    return <CallElement fn={<Add>{a}</Add>}>{render_rows}</CallElement>;
}

def:pub Decrement(children: object | None = None) -> JsxElement {
    ref = useRef(None);

    useEffect(lambda {
        one = ref.current.querySelector('[data-type="nat"]') if ref.current else None;
        if one and one.dataset {
            one.dataset.type = '';
        }
    }, []);

    return <div ref={ref}>{children}</div>;
}

