import from "react" { useEffect }

def:pub Modal(open: bool, onClose: Callable[[], None], title: str, children: object = None) -> JsxElement | None {
    useEffect(lambda {
        if not open {
            return lambda { };
        }
        def on_key(e: KeyboardEvent) {
            if e.key == "Escape" {
                onClose();
            }
        }
        document.addEventListener("keydown", on_key);
        return lambda { document.removeEventListener("keydown", on_key); };
    }, [open, onClose]);

    useEffect(lambda {
        document.body.style.overflow = "hidden" if open else "";
        return lambda { document.body.style.overflow = ""; };
    }, [open]);

    if not open {
        return None;
    }

    def handle_overlay_click(e: MouseEvent) {
        onClose();
    }

    def handle_content_click(e: MouseEvent) {
        e.stopPropagation();
