  name: "Open Dashboard",
  description:
    "A full-stack back-office starter — copy a resource folder to ship your own.",
  logo: SquaresFourIcon,
  nav: {
    main: mainMenuItems,
    bottom: bottomMenuItems,
  },
  theme: {
    defaultTheme: "system",
    enableSystem: true,
  },
};

