// The canonical list request/response shapes live in the data layer (the
// Repository contract); re-exported here so table code has one import surface.
export type {
  ListParams,
  ListResult,
  SortDir,
} from "@/infra/data/repository";

export interface FilterOption {
  key: string;
  label: string;
}

export interface FilterConfig {
  key: string;
  label: string;
  placeholder?: string;
  options: FilterOption[];
}

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

export interface DescriptionItem {
  label: ReactNode;
  value: ReactNode;
  /** Span the full row (useful for long text like a description). */
  full?: boolean;
}

export interface DescriptionListProps {
  items: DescriptionItem[];
  /** Number of columns on `sm`+ screens. Default 2. */
  columns?: 1 | 2 | 3;
  className?: string;
}

const columnClass: Record<1 | 2 | 3, string> = {
  1: "sm:grid-cols-1",
  2: "sm:grid-cols-2",
  3: "sm:grid-cols-3",
};

/**
 * Label/value grid for record detail pages. Each item renders a muted label
 * above its value; `full` items span the whole row. The canonical building
 * block of the Detail/Show archetype.
 */
export function DescriptionList({
  items,
  columns = 2,
  className,
}: DescriptionListProps) {
  return (
    <dl
      className={cn(
        "grid grid-cols-1 gap-x-6 gap-y-4",
        columnClass[columns],
        className,
      )}
    >
      {items.map((item, index) => (
        <div
          key={typeof item.label === "string" ? item.label : index}
          className={cn("flex flex-col gap-1", item.full && "sm:col-span-full")}
        >
          <dt className="text-xs text-muted-foreground">{item.label}</dt>
          <dd className="text-sm">{item.value}</dd>
        </div>
      ))}
    </dl>
  );
}

"use client";

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";

export type ChipColor =
  | "success"
  | "warning"
  | "danger"
  | "primary"
  | "secondary"
  | "default";

const colorClasses: Record<ChipColor, string> = {
  success:
    "border-transparent bg-green-500/15 text-green-700 dark:text-green-400",
  warning:
    "border-transparent bg-amber-500/15 text-amber-700 dark:text-amber-400",
  danger: "border-transparent bg-destructive/15 text-destructive",
  primary: "border-transparent bg-primary/15 text-primary",
  secondary: "border-transparent bg-secondary text-secondary-foreground",
  default: "border-transparent bg-muted text-muted-foreground",
};

export interface StatusChipProps<T extends string> {
  status: T;
  colorMap: Record<T, ChipColor>;
  labelMap?: Record<T, string>;
  size?: "sm" | "md" | "lg";
  variant?:
    | "flat"
    | "bordered"
    | "solid"
    | "faded"
    | "shadow"
    | "light"
    | "dot";
  className?: string;
}

/**
 * Reusable status chip with configurable color mapping.
 *
 * @example
 * ```tsx
 * <StatusChip
 *   status="active"
 *   colorMap={{ active: "success", pending: "warning", inactive: "danger" }}
 *   labelMap={{ active: "Active", pending: "Pending", inactive: "Inactive" }}
 * />
 * ```
 */
export function StatusChip<T extends string>({
  status,
  colorMap,
  labelMap,
  className,
}: StatusChipProps<T>) {
  const color = colorMap[status] ?? "default";
  const label = labelMap?.[status] ?? formatStatus(status);

  return (
    <Badge variant="outline" className={cn(colorClasses[color], className)}>
      {label}
    </Badge>
  );
}

function formatStatus(status: string): string {
  return status
    .replace(/[-_]/g, " ")
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

