    target: "Product “Aero Mug”",
    time: "18m ago",
    dateTime: "2026-06-20T13:46:00Z",
    tone: "updated",
    changes: [
      { field: "price", from: "$24.00", to: "$19.00" },
      { field: "stock", from: "120", to: "96" },
