import from "@phosphor-icons/react" { GithubLogoIcon, GoogleLogoIcon }
import from "@/components/ui/button" { Button }
import from "@/lib/auth-client" { authClient }
import from "@/lib/toast" { toastError }

obj SocialProviderConfig {
    has id: str;
    has label: str;
    has icon: object;
}

glob PROVIDERS: list[SocialProviderConfig] = [
    SocialProviderConfig(id="github", label="Continue with GitHub", icon=GithubLogoIcon),
    SocialProviderConfig(id="google", label="Continue with Google", icon=GoogleLogoIcon),
];

def:pub SocialButtons(callbackURL: str = "/") -> JsxElement {
    has pending: str | None = None;

    async def signInWith(provider: str) {
        pending = provider;
        try {
            result = await authClient.signIn.social({
                "provider": provider,
                "callbackURL": callbackURL,
            });
            error = result.error;
            if error {
                message = error.message if error.message else f"{provider} sign-in isn't configured yet.";
                toastError(message);
            }
        } except Exception {
            toastError(
                f"{provider} sign-in isn't configured yet. Add its keys in src/lib/auth.ts."
            );
        } finally {
            pending = None;
        }
    }

    <div className="flex flex-col gap-2">
        {for provider in PROVIDERS {
            Icon = provider.icon;
            <Button
                key={provider.id}
                type="button"
                variant="outline"
                className="w-full"
                disabled={(pending is not None) and (pending != provider.id)}
                onClick={lambda { signInWith(provider.id); }}
            >
                <Icon weight="fill" />
                {"Redirecting…" if pending == provider.id else provider.label}
            </Button>
        }}
    </div>
}

