        "yarn": "npx @modern-core/ui add underline-tabs",
        "bun": "bunx --bun @modern-core/ui add underline-tabs",
    };
    <div>
        <TerminalBlock commands={commands} activeTab="npm" showTypingAnimation={True} />
    </div>
}

def ManualContent() -> JsxElement {
    comp = useComponentCode("underline-tabs");
    underlineTabsCode: str = comp.code;
    isLoading: bool = comp.isLoading;
    <div>
        {if isLoading {
            <div className="mt-2 text-sm text-muted-foreground">
                Loading component code...
            </div>
        } else {
            <CodeBlock code={underlineTabsCode} language="tsx" />
        }}
    </div>
}

