import from "@/lib/utils" { cn }
import from "react" { useEffect }

def format_number(num: float, decimalPlaces: int) -> str {
    if decimalPlaces > 0 {
        return f"{num:,.{decimalPlaces}f}";
    }
    return f"{int(round(num)):,}";
}

def:pub NumberCounter(
    value: float,
    startValue: float = 0,
    direction: str = "up",
    delay: int = 0,
    className: str = "",
    decimalPlaces: int = 0,
    props: dict[str, object] | None = None,
) -> JsxElement {
    has displayNum: float = value if direction == "down" else startValue;
    spreadProps = props if props is not None else {};
    target = startValue if direction == "down" else value;

    useEffect(lambda {
        timer = setTimeout(lambda {
            displayNum = target;
        }, delay * 1000);
        return lambda {
            clearTimeout(timer);
        };
    }, [target, delay]);

    <span
        className={cn(
            "inline-block tabular-nums tracking-wider text-black dark:text-white",
            className,
        )}
        {**spreadProps}
    >
        {format_number(displayNum, decimalPlaces)}
    </span>
}

