      } catch (error: any) {
        console.error(`Error fetching code for ${componentName}:`, error);
        setCode("// Error loading component code");
        setError(error?.message || "Failed to fetch component code");
      } finally {
        setIsLoading(false);
      }
    };

    fetchComponentCode();
  }, [componentName]);

  return { code, isLoading, error };
}

