import from "@/lib/utils" { cn }

glob BUTTON_BASE: str = "inline-flex items-center justify-center rounded-full text-sm font-medium whitespace-nowrap ring-offset-background transition-colors focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:outline-hidden disabled:pointer-events-none disabled:opacity-50";

glob VARIANT_CLASSES: dict[str, str] = {
    "default": "bg-primary text-primary-foreground hover:bg-primary/90",
    "secondary": "bg-muted text-secondary-foreground hover:bg-muted/80",
    "outline": "border border-input hover:bg-muted/80",
    "link": "text-primary underline-offset-4 hover:underline",
};

glob SIZE_CLASSES: dict[str, str] = {
    "default": "h-10 px-4 py-2",
    "sm": "h-9 px-3",
    "lg": "h-11 px-8",
    "icon": "size-11",
};

def:pub buttonVariants(variant: str = "default", size: str = "default", className: str = "") -> str {
    v = VARIANT_CLASSES.get(variant, VARIANT_CLASSES["default"]);
    s = SIZE_CLASSES.get(size, SIZE_CLASSES["default"]);
    return cn(BUTTON_BASE, v, s, className);
