import from "radix-ui" { Slot }
import from "@/lib/utils" { cn }

glob BUTTON_BASE: str = "group/button inline-flex shrink-0 items-center justify-center rounded-none border border-transparent bg-clip-padding text-xs font-semibold tracking-widest whitespace-nowrap uppercase transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/30 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-2 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-3.5";

glob BUTTON_VARIANTS: dict[str, str] = {
    "default": "bg-primary text-primary-foreground hover:bg-primary/80",
    "outline": "border-border bg-transparent hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-input/30",
    "secondary": "bg-secondary text-secondary-foreground hover:bg-secondary/80 aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
    "ghost": "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
    "destructive": "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
    "link": "text-primary underline underline-offset-4 hover:underline",
};

glob BUTTON_SIZES: dict[str, str] = {
    "default": "h-10 gap-1.5 px-6 has-data-[icon=inline-end]:pr-4 has-data-[icon=inline-start]:pl-4",
    "xs": "h-7 gap-1 px-3 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2 [&_svg:not([class*='size-'])]:size-3",
    "sm": "h-9 gap-1 px-4 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3",
    "lg": "h-11 gap-1.5 px-8 has-data-[icon=inline-end]:pr-5 has-data-[icon=inline-start]:pl-5",
    "icon": "size-10",
    "icon-xs": "size-7 [&_svg:not([class*='size-'])]:size-3",
    "icon-sm": "size-9",
    "icon-lg": "size-11",
};

def:pub buttonVariants(variant: str = "default", size: str = "default", className: str = "") -> str {
    variantClass = BUTTON_VARIANTS.get(variant, BUTTON_VARIANTS["default"]);
    sizeClass = BUTTON_SIZES.get(size, BUTTON_SIZES["default"]);
    return cn(BUTTON_BASE, variantClass, sizeClass, className);
}

def:pub Button(className: str = "", variant: str = "default", size: str = "default", asChild: bool = False, props: dict[str, object] = {}) -> JsxElement {
    classes = cn(buttonVariants(variant=variant, size=size, className=className));
    if asChild {
        return <Slot.Root data-slot="button" data-variant={variant} data-size={size} className={classes} {**props} />;
    }
    return <button data-slot="button" data-variant={variant} data-size={size} className={classes} {**props} />;
}

