import from "@/lib/utils" { cn }

glob:pub badgeVariants: dict[str, object] = {
    "base": "inline-flex items-center cursor-auto rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2",
    "variants": {
        "variant": {
            "default": "border-transparent bg-primary text-primary-foreground",
            "secondary": "border-transparent bg-secondary text-secondary-foreground",
            "destructive": "border-transparent bg-destructive text-destructive-foreground",
            "outline": "text-foreground",
        }
    },
    "defaultVariants": {"variant": "default"},
};

def resolve_badge_variant(variant: str | None = None) -> str {
    variants = (badgeVariants["variants"] as dict[str, dict[str, str]])["variant"];
    key = variant if variant else (badgeVariants["defaultVariants"] as dict[str, str])["variant"];
    if key in variants {
        return variants[key];
    }
    return variants["default"];
}

def:pub Badge(className: str = "", variant: str | None = None, props: dict[str, object] = {}) -> JsxElement {
    <div
        className={cn(
            badgeVariants["base"] as str,
            resolve_badge_variant(variant),
            className
        )}
        {**props}
    />
}

