import { useGetSubscription } from '@/features/subscriptions/api/use-get-subscription';
import { useSubscriptionModal } from '@/features/subscriptions/store/use-subscription-modal';

export const usePaywall = () => {
  const { data: subscription, isLoading: isLoadingSubscription } = useGetSubscription();
  const subscriptionModal = useSubscriptionModal();

  const shouldBlock = isLoadingSubscription || !subscription?.active;

  return {
    isLoading: isLoadingSubscription,
    shouldBlock,
    triggerPaywall: () => {
      subscriptionModal.onOpen();
    },
  };
};

jac:
import from ..api.use_get_subscription { useGetSubscription, Subscription }
import from ..store.use_subscription_modal { useSubscriptionModal }

def:pub usePaywall() -> dict[str, object] {
    query = useGetSubscription();
    subscriptionModal = useSubscriptionModal();
    isLoadingSubscription = query["isLoading"] as bool;
    subscription = query["data"] as Subscription | None;
    shouldBlock = isLoadingSubscription or subscription is None or not subscription.active;

    def triggerPaywall() {
        onOpen = subscriptionModal["onOpen"] as Callable[[], None];
        onOpen();
    }

    return {
        "isLoading": isLoadingSubscription,
        "shouldBlock": shouldBlock,
        "triggerPaywall": triggerPaywall,
    };
}

