        return "INTERVIEW_TIME_LIMIT_REACHED";
    }
    if ((reason == "ACCOUNT_SESSION_TIME_LIMIT_REACHED") or (reason == "TIME_LIMIT_EXCEEDED")) {
        return "ACCOUNT_SESSION_TIME_LIMIT_REACHED";
    }
    return "COMPLETED";
}

glob endReasonCopy: dict[str, dict[str, str | object]] = {"COMPLETED": {"icon": CheckCircle2, "iconClassName": "text-secondary-500", "title": "Thank you!", "description": "Your interview has been completed successfully. We appreciate your time and thoughtful responses."}, "INTERVIEW_TIME_LIMIT_REACHED": {"icon": Clock3, "iconClassName": "text-amber-600", "title": "Interview time limit reached", "description": "This interview reached its configured time limit and was submitted automatically. Thank you for your time and responses."}, "ACCOUNT_SESSION_TIME_LIMIT_REACHED": {"icon": AlertTriangle, "iconClassName": "text-amber-600", "title": "Session time limit reached", "description": "This interview ended because the organization's available session time was used up. Your responses were saved, but please contact the interviewer if you need to continue."}};

def:pub SessionEndedScreen(reason: str | None = None) -> JsxElement {
