import from "@/lib/supabase/server" { createClient }
import from "next/headers" { headers }

async def:pub createContext() -> dict[str, object | None] {
    serverClient = await createClient();
    user: object | None = None;
    try {
        authResult = await serverClient.auth.getUser();
        user = authResult.data.user;
    } except Exception {
        user = None;
    }
    if user is None {
        try {
            headerStore = await headers();
            authorization = headerStore.get("authorization");
            if authorization and authorization.startswith("Bearer ") {
                token = authorization[7:];
                bearerResult = await serverClient.auth.getUser(token);
                user = bearerResult.data.user;
            }
        } except Exception {
            user = None;
        }
    }
    return {"user": user, "supabase": supabaseAdmin};
}

