import os;
import from datetime { datetime }

type LogLevel = "debug" | "info" | "warn" | "error";

glob LEVELS: dict[str, int] = {"debug": 0, "info": 1, "warn": 2, "error": 3};

glob MIN_LEVEL: LogLevel = (os.environ.get("LOG_LEVEL", "") as LogLevel) if os.environ.get("LOG_LEVEL") else ("info" if os.environ.get("NODE_ENV") == "production" else "debug");

def ts() -> str {
    return datetime.now().isoformat().replace("T", " ")[0:-1];
}

def fmt(level: LogLevel, mod: str) -> str {
    return f"{ts()} {level.upper().ljust(5)} [{mod}]";
}

obj Logger {
    has mod: str;

    def debug(*args: object) {
        if LEVELS["debug"] >= LEVELS[MIN_LEVEL] {
            print(fmt("debug", self.mod), *args);
        }
    }

    def info(*args: object) {
        if LEVELS["info"] >= LEVELS[MIN_LEVEL] {
            print(fmt("info", self.mod), *args);
        }
    }

    def warn(*args: object) {
        if LEVELS["warn"] >= LEVELS[MIN_LEVEL] {
            print(fmt("warn", self.mod), *args);
        }
    }

    def error(*args: object) {
        print(fmt("error", self.mod), *args);
    }
}

def:pub createLogger(mod: str) -> Logger {
    return Logger(mod=mod);
}

glob:pub logger = createLogger("app");

