        "role": "assistant",
        "kind": "question",
        "content": question["text"],
        "questionIndex": index,
        "questionType": qtype,
        "questionOptions": normalizePrepQuestionOptions(options),
    };
}

def toPracticeMode(inputMode: str) -> PracticeMode {
