import from "@/components/data-table/utils/case-utils" { convertObjectKeys, convertObjectKeysWithMapper, CaseFormatConfig, DEFAULT_CASE_CONFIG }
import re;

glob API_BASE_URL: str = "/api";

async def:pub fetchUsers(options: dict[str, object] | None = None) -> dict[str, object] {
    opts = options if options is not None else {};
    search = opts.get("search", "") as str;
    from_date = opts.get("from_date", "") as str;
    to_date = opts.get("to_date", "") as str;
    sort_by = opts.get("sort_by", "created_at") as str;
    sort_order = opts.get("sort_order", "desc") as str;
    page = opts.get("page", 1) as int;
    limit = opts.get("limit", 10) as int;
    caseConfig = opts.get("caseConfig", DEFAULT_CASE_CONFIG) as CaseFormatConfig;
    processedSearch = re.sub(r"\s+", " ", search.strip()) if search else "";
    rawParams: dict[str, str | None] = {
        "search": processedSearch if processedSearch else None,
        "from_date": from_date if from_date else None,
        "to_date": to_date if to_date else None,
        "sort_by": sort_by,
        "sort_order": sort_order,
        "page": str(page),
        "limit": str(limit),
    };
    filteredParams: dict[str, str] = {k: v for (k, v) in rawParams.items() if v is not None};
    if caseConfig.keyMapper {
        convertedParams = convertObjectKeysWithMapper(filteredParams, caseConfig.keyMapper);
    } else {
        apiFormat = caseConfig.apiFormat if caseConfig.apiFormat else "snake_case";
        convertedParams = convertObjectKeys(filteredParams, apiFormat);
    }
    queryParts: list[str] = [f"{k}={v}" for (k, v) in convertedParams.items()];
    queryString = "&".join(queryParts);
    response = await fetch(f"{API_BASE_URL}/users?{queryString}");
    if not response.ok {
        raise Exception(f"Failed to fetch users: {response.statusText}");
    }
    data = await response.json();
    return data as dict[str, object];
}

