import type from "@tiptap/react" { Editor }
import from "react" { useEffect }
import from "@tiptap/react" { useEditor, EditorContent }
import from "@tiptap/starter-kit" { default as StarterKit }
import from "@tiptap/extension-link" { default as Link }
import from "@tiptap/extension-placeholder" { default as Placeholder }
import from "./RichTextToolbar" { RichTextToolbar }

glob parseOptions = {"preserveWhitespace": "full"};

def:pub RichTextEditor(value: str, onChange: Callable[[str], None], placeholder: str | None = None) -> JsxElement | None {
    def handle_update(payload: dict[str, object]) {
        e = payload["editor"] as Editor;
        html = e.getHTML();
        nextValue = "" if html == "<p></p>" else html;
        onChange(nextValue);
    }
    editor = useEditor({
        "extensions": [
            StarterKit.configure({"heading": False, "strike": False, "code": False, "codeBlock": False, "blockquote": False, "horizontalRule": False}),
            Link.configure({"openOnClick": False, "HTMLAttributes": {"target": "_blank", "rel": "noreferrer"}}),
            Placeholder.configure({"placeholder": placeholder if placeholder else ""}),
        ],
        "content": value,
        "parseOptions": parseOptions,
        "onUpdate": handle_update,
    });
    useEffect(lambda {
        if (not editor) {
            return;
        }
        current = editor.getHTML();
        normalized = "" if current == "<p></p>" else current;
        if (value != current) and (value != normalized) {
            editor.commands.setContent(value if value else "", False);
        }
    });
    if (not editor) {
        return None;
    }
    return <div className="rounded-md border"><RichTextToolbar editor={editor} /><EditorContent editor={editor} /></div>;
}

