import type from "@/types/json-resume" { JsonResume, JsonWork, JsonProject }

glob CUSTOM_MODULE_PREFIX = "custom-";

def aboutme_read(config: JsonResume) -> str | None {
    return config.get("x-op-aboutmeHtml") as str | None;
}

def aboutme_write(_config: JsonResume, _i: int, newHtml: str) -> dict[str, object] {
    return {"x-op-aboutmeHtml": newHtml};
}

def work_read(config: JsonResume, i: int) -> str | None {
    work = config.get("work") as list[JsonWork] | None;
    if work is None or i >= len(work) {
        return None;
    }
    return work[i].get("x-op-workDescHtml") as str | None;
}

def work_write(config: JsonResume, i: int, newHtml: str) -> dict[str, object] | None {
    work = list(config.get("work", []) as list[JsonWork]);
    if i >= len(work) {
        return None;
    }
    updated = dict(work[i]);
    updated["x-op-workDescHtml"] = newHtml;
    work[i] = updated as JsonWork;
    return {"work": work};
}

def project_read(config: JsonResume, i: int) -> str | None {
    projects = config.get("projects") as list[JsonProject] | None;
    if projects is None or i >= len(projects) {
        return None;
    }
