import from "@/lib/source" { source }
import from "@/lib/seo" { absoluteUrl }

def:pub sitemap() -> list[dict[str, object]] {
    pages = source.getPages() as list[dict[str, object]];
    now = new(Date, []);
    docEntries = [
        {
            "url": absoluteUrl(page["url"] as str),
            "lastModified": now,
            "changeFrequency": "weekly",
            "priority": 1 if (page["url"] as str) == "/docs" else 0.8,
        }
        for page in pages
    ];
    seen = set([entry["url"] for entry in docEntries]);
    docsUrl = absoluteUrl("/docs");
    if docsUrl not in seen {
        docEntries = [{"url": docsUrl, "lastModified": now, "changeFrequency": "weekly", "priority": 1}] + docEntries;
        seen.add(docsUrl);
    }
    staticEntries = [
        {"url": absoluteUrl("/"), "lastModified": now, "changeFrequency": "weekly", "priority": 1},
        {"url": absoluteUrl("/playground"), "lastModified": now, "changeFrequency": "weekly", "priority": 0.9},
    ];
    for entry in staticEntries {
        entryUrl = entry["url"] as str;
        if entryUrl not in seen {
            docEntries = [entry] + docEntries;
            seen.add(entryUrl);
        }
    }
    return docEntries;
}

