import from "@jac/runtime" { useLocation }
import from "react" { useMemo }

type IconComponent = Callable[[dict[str, str | int]], JsxElement];

obj SubMenuItemIn {
    has title: str;
    has url: str;
}

obj MenuItemIn {
    has title: str;
    has url: str;
    has icon: IconComponent;
    has items: list[SubMenuItemIn] | None = None;
}

obj ActiveSubMenuItem {
    has title: str;
    has url: str;
    has isActive: bool = False;
}

obj ActiveMenuItem {
    has title: str;
    has url: str;
    has icon: IconComponent;
    has isActive: bool = False;
    has items: list[ActiveSubMenuItem] | None = None;
}

def:pub useActiveMenu(items: list[MenuItemIn]) -> dict[str, list[ActiveMenuItem]] {
    location = useLocation();
    pathname = location.pathname or "";

    activeItems = useMemo(
        lambda -> list[ActiveMenuItem] {
            result: list[ActiveMenuItem] = [];
            for item in items {
                isMainActive = pathname == item.url;
                hasActiveChild = False;
                enrichedItems: list[ActiveSubMenuItem] | None = None;

                if item.items is not None {
                    enrichedItems = [];
                    for subItem in item.items {
                        subActive = pathname == subItem.url;
                        if subActive {
                            hasActiveChild = True;
                        }
                        enrichedItems.append(
                            ActiveSubMenuItem(
                                title=subItem.title,
                                url=subItem.url,
                                isActive=subActive
                            )
                        );
                    }
                }

                result.append(
                    ActiveMenuItem(
                        title=item.title,
                        url=item.url,
                        icon=item.icon,
                        isActive=isMainActive or hasActiveChild,
                        items=enrichedItems
                    )
                );
            }
            return result;
        },
        [pathname, items]
    );

    return {"activeItems": activeItems};
}

