import from "react" { useEffect }

def:pub useDebounce[T](value: T, delay: int = 500) -> T {
    has debouncedValue: T = value;

    useEffect(lambda {
        timer = setTimeout(lambda { debouncedValue = value; }, delay);
        return lambda { clearTimeout(timer); };
    }, [value, delay]);

    debouncedValue
}

