    variant: str | None = None,
    size: str | None = None,
    className: str | None = None,
) -> str {
    v = variant if variant is not None else "default";
    s = size if size is not None else "default";
    return cn(BUTTON_BASE, BUTTON_VARIANT_CLASSES.get(v, ""), BUTTON_SIZE_CLASSES.get(s, ""), className);
}

def:pub Button(
    className: str | None = None,
    variant: str | None = None,
    size: str | None = None,
    asChild: bool = False,
    children: object | None = None,
    props: dict[str, object] = {},
) -> JsxElement {
    cls = buttonVariants(variant=variant, size=size, className=className);
    if asChild {
        return <Slot data-slot="button" className={cls} {**props}>{children}</Slot>;
    }
    return <button data-slot="button" className={cls} {**props}>{children}</button>;
}

