import from "@/lib/auth" { getAuthUser }
import from "@/lib/url-fetch" { fetchUrlWithReaderFallback }
import from "cheerio" { * as cheerio }
import re;

glob MAX_TEXT_LENGTH: int = 15000;

def truncate(text: str) -> str {
    if (len(text) <= MAX_TEXT_LENGTH) {
        return text;
    }
    return text[0:MAX_TEXT_LENGTH] + "\n\n[...truncated]";
}

def htmlToText(html: str) -> str {
    text = re.sub(r"(?i)<script[^>]*>[\s\S]*?</script>", "", html);
    text = re.sub(r"(?i)<style[^>]*>[\s\S]*?</style>", "", text);
    text = re.sub(r"<[^>]+>", " ", text);
    collapsed = re.sub(r"[ \t]+", " ", text);
    normalized = re.sub(r"\n{3,}", "\n\n", collapsed);
    return normalized.strip();
}

async def:pub POST(url: str | None = None) -> dict[str, str] {
    user = await getAuthUser();
    if user is None {
        return {"error": "Unauthorized"};
    }
    if url is None or not url.strip() {
        return {"error": "Provide either a PDF file or a URL"};
    }
    targetUrl = url.strip();
    if re.search(r"(?i)^https?://", targetUrl) is None {
        return {"error": "Invalid URL — must start with http:// or https://"};
    }
    fetchResult = await fetchUrlWithReaderFallback(targetUrl) as dict[str, object];
    res = fetchResult["response"] as dict[str, object];
    if not (res["ok"] as bool) {
        status = res["status"] as int;
        return {"error": f"Failed to fetch URL (HTTP {status})"};
    }
    headers = res["headers"] as dict[str, str];
    contentType = headers.get("content-type") or "";
    textFn = res["text"] as Callable[[], Awaitable[str]];
    extractedText: str;
    if "text/plain" in contentType {
        extractedText = (await textFn()).strip();
    } else {
        pageHtml = await textFn() as str;
        extractedText = htmlToText(pageHtml);
    }
    if not extractedText {
        return {"error": "Could not extract meaningful text from the URL"};
    }
    return {"text": truncate(extractedText)};
}

