import { z } from "zod";

export const emailSchema = z.string().email();

export const checkPasswordSchema = z
  .string()
  .min(8, "Password must be at least 8 characters long")
  .max(100, "Password must not exceed 100 characters")
  .regex(/[A-Z]/, "Password must contain at least one uppercase letter")
  .regex(/[a-z]/, "Password must contain at least one lowercase letter")
  .regex(/[0-9]/, "Password must contain at least one number")
  .regex(
    /[^A-Za-z0-9]/,
    "Password must contain at least one special character",
  );

export const passwordSchema = z.string();

export const loginSchema = z.object({
  email: emailSchema,
  password: passwordSchema,
});

export const signUpSchema = z.object({
  name: z.string().min(1, "Name must be atleast 1 character"),
  email: emailSchema,
  password: passwordSchema,
});

export const updateProfileSchema = z.object({
  name: z.string().min(1, "Name must be atleast 1 character"),
  email: emailSchema,
});

jac:
import re;

def emailSchema(value: str) -> bool {
    return bool(re.match(r"^[^\s@]+@[^\s@]+\.[^\s@]+$", value));
}

def checkPasswordSchema(value: str) -> bool {
    if len(value) < 8 or len(value) > 100 {
        return False;
    }
    if re.search(r"[A-Z]", value) is None { return False; }
    if re.search(r"[a-z]", value) is None { return False; }
    if re.search(r"[0-9]", value) is None { return False; }
    if re.search(r"[^A-Za-z0-9]", value) is None { return False; }
    return True;
}

def passwordSchema(value: str) -> bool {
    return True;
}

obj LoginInput {
    has email: str;
    has password: str;
}

obj SignUpInput {
    has name: str;
    has email: str;
    has password: str;
}

obj UpdateProfileInput {
    has name: str;
    has email: str;
}

def loginSchema(input: LoginInput) -> bool {
    return emailSchema(input.email) and passwordSchema(input.password);
}

def signUpSchema(input: SignUpInput) -> bool {
    return len(input.name) >= 1 and emailSchema(input.email) and passwordSchema(input.password);
}

def updateProfileSchema(input: UpdateProfileInput) -> bool {
    return len(input.name) >= 1 and emailSchema(input.email);
}

