import math;

def:pub micLevelForDisplay(rms: float) -> float {
    if (not math.isfinite(rms) or rms <= 0) {
        return 0.0;
    }
    boosted = min(1.0, rms * 14.0);
    min(1.0, pow(boosted, 0.6) * 1.1)
}

