glob prefixes = {"pnpm": "pnpx shadcn@latest add", "npm": "npx shadcn@latest add", "yarn": "yarn shadcn@latest add", "bun": "bunx shadcn@latest add"};

def getTabIcon(command: str) -> JsxElement {
    if command == "pnpm" { return <SiPnpm className="size-3" />; }
    if command == "bun" { return <SiBun className="size-3" />; }
    if command == "npm" { return <SiNpm className="size-3" />; }
    if command == "yarn" { return <SiYarn className="size-3" />; }
    return <span />;
}

def getCommandValue(command: str, packages: str) -> str {
    return prefixes[command] + " " + packages;
}

def:pub PackagesManagerTabs(packages: str) -> JsxElement {
    has activeTab: str = "pnpm";
    commands = ["pnpm", "bun", "npm", "yarn"];
    def setActiveTabValue(v: str) {
        activeTab = v;
    }
    <Tabs defaultValue="pnpm" className="bg-accent/50 rounded-sm" value={activeTab} onValueChange={setActiveTabValue}>
        <TabsList className="w-full justify-between border-b rounded-none bg-accent h-10" variant="default">
            <div className="flex gap-2 justify-start">
                {for command in commands {
                    <TabsTrigger key={command} value={command} className="rounded-sm py-1"><span>{getTabIcon(command)}</span>{command}</TabsTrigger>
                }}
            </div>
            <CopyButton text={getCommandValue(activeTab, packages)} />
        </TabsList>
        {for command in commands {
            <TabsContent key={command} value={command} className="pt-3 pb-5 flex gap-2"><pre className="px-2 text-muted-foreground text-wrap">{getCommandValue(command, packages)}</pre></TabsContent>
        }}
    </Tabs>
}

