export const MARKDOWN_BODY_MARKER = "data-guide-markdown-body";

const PROSE_CLASSES = [
  "prose prose-lg dark:prose-invert max-w-none",
  "prose-headings:text-foreground prose-headings:font-bold",
  "prose-p:text-default-600 prose-p:leading-relaxed",
  // `[&_a:hover]:underline` puts :hover on the anchor itself.
  // `hover:prose-a:underline` puts it on the container, which underlines every
  // link whenever the cursor is anywhere in the article (prior regression).
  "prose-a:text-primary prose-a:no-underline [&_a:hover]:underline",
  "prose-strong:text-foreground",
  "prose-code:text-primary prose-code:bg-content2 prose-code:px-1.5 prose-code:py-0.5 prose-code:rounded",
  "prose-pre:bg-content2 prose-pre:border prose-pre:border-divider",
  "prose-li:text-default-600",
  "prose-table:border-collapse",
  "prose-th:border prose-th:border-divider prose-th:px-4 prose-th:py-2 prose-th:bg-content1",
  "prose-td:border prose-td:border-divider prose-td:px-4 prose-td:py-2",
].join(" ");

// The body is rendered as a placeholder <div> with a unique data-attribute.
// The build script (scripts/build-guides.tsx) replaces this placeholder with
// the markdown-to-HTML output at string level after React renders. This keeps
// React pure and confines raw HTML handling to one well-audited call site.
export function ProseArticle({ title }: { title: string }) {
  return (
    <article className={PROSE_CLASSES}>
      <h1>{title}</h1>
      <div {...{ [MARKDOWN_BODY_MARKER]: "" }} />
    </article>
  );
}

import { type Repository } from "@octokit/graphql-schema";
import { RequestError } from "@octokit/request-error";
import { useCallback, useMemo, useReducer, useRef } from "react";

import { useGitHubData } from "@/hooks/use-github-data";
import { analytics } from "@/utils/analytics";
import { debug } from "@/utils/debug";
import { createThrottledOctokit } from "@/github/client";
import { processRepo } from "@/github/mutations";

// --- Types ---

export type ModalMode = "confirmation" | "progress" | "result";

export type ModalAction =
  | { payload: { error: Error; repository?: Repository }; type: "ADD_ERROR" }
  | { payload: { increment: number; repo: string }; type: "UPDATE_PROGRESS" }
  | { payload: { login: string; username: string }; type: "SET_USERNAME" }
  | { type: "COMPLETE_PROCESSING" }
  | { type: "RESET" }
  | { payload: { totalCount: number }; type: "START_PROCESSING" };

export interface ModalState {
  confirming: boolean;
  currentRepo: string;
  errors: { error: Error; repository?: Repository }[];
  isCorrectUsername: boolean;
  mode: ModalMode;
  progress: number;
  totalCount: number;
  username: string;
}

export interface UseConfirmationModalProps {
  action: "archive" | "delete";
  login: string;
  onClose: () => void;
  onConfirm?: () => void;
  repos: Repository[];
}

export interface UseConfirmationModalReturn {
  handleConfirm: () => void;
  handleOnClose: () => void;
  handleSetUsername: (value: React.SetStateAction<string>) => void;
  handleStop: () => void;
  isDismissable: boolean;
  state: ModalState;
}

// --- Reducer ---

export const initialState: ModalState = {
  confirming: false,
  currentRepo: "",
  errors: [],
  isCorrectUsername: false,
  mode: "confirmation",
  progress: 0,
  totalCount: 0,
  username: "",
};

export function modalReducer(
  state: ModalState,
  action: ModalAction,
): ModalState {
  switch (action.type) {
    case "ADD_ERROR":
      return {
        ...state,
        errors: [...state.errors, action.payload],
      };
    case "COMPLETE_PROCESSING":
      return {
        ...state,
        confirming: false,
        mode: "result",
      };
    case "RESET":
      return initialState;
    case "SET_USERNAME":
      return {
        ...state,
        isCorrectUsername: action.payload.username === action.payload.login,
        username: action.payload.username,
      };
    case "START_PROCESSING":
      return {
        ...state,
        confirming: true,
        errors: [],
        mode: "progress",
        progress: 0,
        totalCount: action.payload.totalCount,
      };
    case "UPDATE_PROGRESS":
      return {
        ...state,
        currentRepo: action.payload.repo,
        progress: state.progress + action.payload.increment,
      };
    default:
      return state;
  }
}

// --- Hook ---

/**
 * Custom hook for managing the confirmation modal state machine.
 *
 * Handles:
 * - State transitions (confirmation -> progress -> result)
 * - Username validation
 * - Batch repo processing with abort support
 * - Analytics tracking
 * - Error collection
 */
export function useConfirmationModal({
  action,
  login,
  onClose,
  onConfirm,
  repos,
}: UseConfirmationModalProps): UseConfirmationModalReturn {
  const { mutate, pat } = useGitHubData();

  const octokit = useMemo(
    () => (pat ? createThrottledOctokit(pat) : null),
    [pat],
  );

  const [state, dispatch] = useReducer(modalReducer, initialState);
  const abortRef = useRef(false);

  const handleConfirmAsync = useCallback(async () => {
    debug.log("handleConfirm called");

    if (!octokit || state.confirming) return;

    abortRef.current = false;
    dispatch({
      payload: { totalCount: repos.length },
      type: "START_PROCESSING",
    });

    if (action === "archive") {
      analytics.trackArchiveSubmit(repos.length);
    } else {
      analytics.trackDeleteSubmit(repos.length);
    }

    let processed = 0;
    let errorCount = 0;

    for (const repo of repos) {
      if (abortRef.current) break;

      try {
        await processRepo(octokit, repo, action);

        // Optimistically remove this repo from table immediately
        void mutate(
          (current) => {
            if (!current?.repos) return current;
            return {
              ...current,
              repos: current.repos.filter((r) => r.id !== repo.id),
            };
          },
          { revalidate: false },
        );
      } catch (thrown) {
        const error =
          thrown instanceof Error ? thrown : new Error(String(thrown));
        debug.error(`Failed to ${action} the repo:`, error);
        dispatch({
          payload: { error, repository: repo },
          type: "ADD_ERROR",
        });
        errorCount++;

        if (thrown instanceof RequestError && thrown.status === 401) {
          debug.error(
            "Authentication failed — stopping batch early. Token may have expired.",
          );
          break;
        }
      } finally {
        processed++;
        dispatch({
          payload: { increment: 1, repo: repo.name },
          type: "UPDATE_PROGRESS",
        });
        if (!abortRef.current) {
          await new Promise((resolve) => setTimeout(resolve, 1000));
        }
      }
    }

    // Track batch outcome
    if (abortRef.current) {
      analytics.trackBatchStopped(processed);
    } else {
      analytics.trackBatchCompleted(processed - errorCount);
    }

    dispatch({ type: "COMPLETE_PROCESSING" });
    setTimeout(() => {
      onConfirm?.();
    }, 100);
  }, [action, mutate, octokit, onConfirm, repos, state.confirming]);

  const handleConfirm = useCallback(
    () => void handleConfirmAsync(),
    [handleConfirmAsync],
  );

  const handleStop = useCallback(() => {
    abortRef.current = true;
  }, []);

  const handleOnClose = useCallback(() => {
    // Trigger background revalidation to sync with server state
    // (optimistic update already removed successful repos from cache)
    if (state.mode === "result") {
      void mutate();
    }
    onClose();
    dispatch({ type: "RESET" });
  }, [mutate, onClose, state.mode]);

  const handleSetUsername = useCallback(
    (value: React.SetStateAction<string>) => {
      if (typeof value === "function") {
        const updater = value as (prevState: string) => string;
        const newValue = updater(state.username);
        dispatch({
          payload: { login, username: newValue },
          type: "SET_USERNAME",
        });
      } else {
        dispatch({ payload: { login, username: value }, type: "SET_USERNAME" });
      }
    },
    [login, state.username],
  );

  const isDismissable = state.mode === "confirmation";

  return {
    handleConfirm,
    handleOnClose,
    handleSetUsername,
    handleStop,
    isDismissable,
    state,
  };
}

