import from "@/lib/format" { formatBytes, formatDuration }

obj DownloadTask {
    has totalPages: int,
        status: str,
        speedBytesPerSecond: float,
        etaSeconds: int | None = None;
}

def formatProgressLabel(task: DownloadTask, progressPercent: int) -> str {
    return (f"{progressPercent}%" if (task.totalPages > 0) else "准备中");
}

def formatTaskMeta(task: DownloadTask) -> str {
    speed = f"{formatBytes(task.speedBytesPerSecond)}/S";
    if (task.status == "running") {
        return (f"{speed} · 剩余约 {formatDuration(task.etaSeconds)}" if (task.etaSeconds and (task.etaSeconds > 0)) else f"{speed} · 正在下载");
    }
    if (task.status == "queued") {
        return f"{speed} · 等待中";
    }
    if (task.status == "paused") {
        return "已暂停";
    }
    if (task.status == "completed") {
        return "已完成";
    }
    if (task.status == "cancelled") {
        return "已取消";
    }
    return "失败";
}

