                      endpoint={option.endpoint}
                      probe={option}
                      isDiscovering={isDiscovering}
                      isRefreshingEndpoints={isRefreshingEndpoints}
                    />
                  </SelectItem>
                ))}
              </SelectGroup>
            </SelectContent>
          </Select>
          <Button
            type="button"
            variant="outline"
            size="icon"
            disabled={isDiscovering || isRefreshingEndpoints}
