async def:pub DashboardPage() {
    user = await getCurrentUser();
    if not user {
        redirect("/login");
    }
    def where_workspace(workspace: object, ops: object) -> object {
        return getattr(ops, "eq")(getattr(workspace, "workspaceOwnerId"), getattr(user, "id"));
    }
    workspace = await db.query.workspaces.findFirst({"where": where_workspace});
    if not workspace {
        redirect("/dashboard/new-workspace");
    }
    redirect(f"/dashboard/{getattr(workspace, 'id')}");
}

