    profiles = result["profiles"] as list[dict[str, object]];
    return <div className="mx-auto max-w-6xl px-4 py-12">
        <div className="mb-10 max-w-xl">
            <h1 className="font-cal text-4xl md:text-5xl">Explore</h1>
            <p className="mt-3 text-lg text-muted-foreground">Discover creative profiles built with OpenBio. Get inspired, connect with creators, and build your own.</p>
            <Link href="/claim-link" className="mt-4 inline-flex items-center gap-1.5 rounded-full bg-primary px-4 py-2 font-medium text-primary-foreground text-sm transition-opacity hover:opacity-90">Create yours free</Link>
        </div>
        {if len(profiles) == 0 {
            <div className="flex flex-col items-center gap-3 py-20 text-center">
                <LayoutGrid className="h-10 w-10 text-muted-foreground/50" />
                <p className="font-medium text-lg">No public profiles yet</p>
                <p className="text-muted-foreground text-sm">Be the first to share your profile with the world.</p>
            </div>
        } else {
