                {for profile in profiles {
                    bio = stripHtml(profile["bio"] as str) if profile.get("bio") else None;
                    bento = profile.get("bento");
                    cardCount = len(bento) if isinstance(bento, list) else 0;
                    <Link
                        key={str(profile["id"])}
                        href={f"/{profile['link']}"}
                        className="group flex items-start gap-4 rounded-xl border border-border p-4 transition-all hover:border-primary hover:shadow-sm"
                    >
                        {if profile.get("image") {
                            <Image
                                src={profile["image"] as str}
                                alt={(profile.get("name") or "") as str}
                                width={48}
                                height={48}
                                className="h-12 w-12 shrink-0 rounded-full object-cover"
                            />
                        } else {
                            <div className="h-12 w-12 shrink-0 rounded-full bg-muted" />
                        }}
                        <div className="min-w-0 flex-1">
                            <p className="truncate font-cal text-base">{profile.get("name")}</p>
                            <p className="text-muted-foreground text-xs">@{profile["link"]}</p>
                            {if bio {
                                <p className="mt-1 line-clamp-2 text-muted-foreground text-xs leading-relaxed">{bio}</p>
                            }}
                            {if cardCount > 0 {
                                <p className="mt-1.5 text-muted-foreground/70 text-xs">{cardCount} {"card" if cardCount == 1 else "cards"}</p>
                            }}
                        </div>
                    </Link>
                }}
            </div>
        }}
    </div>;
}

