import * as z from 'zod';

export const SizeSchema = z
  .record(z.enum(['sm', 'md']), z.enum(['4x1', '2x2', '2x4', '4x2', '4x4']))
  .default({
    sm: '2x2',
    md: '2x2',
  });

export const PositionSchema = z
  .record(
    z.enum(['sm', 'md']),
    z
      .object({
        x: z.number().min(0).default(0),
        y: z.number().min(0).default(0),
      })
      .default({ x: 0, y: 0 })
  )
  .default({
    sm: { x: 0, y: 0 },
    md: { x: 0, y: 0 },
  });

export const LinkBentoSchema = z.object({
  id: z.string(),
  type: z.literal('link'),

  href: z.string().url(),
  clicks: z.number().int().min(0).default(0),

  size: SizeSchema,
  position: PositionSchema,
});

export const NoteBentoSchema = z.object({
  id: z.string(),
  type: z.literal('note'),

  text: z.string(),

  size: SizeSchema,
  position: PositionSchema,
});

export const AssetBentoSchema = z.object({
  id: z.string(),
  type: z.enum(['image', 'video']),

  url: z.string(),
  caption: z.string().optional(),
  href: z.string().optional(),

  size: SizeSchema,
  position: PositionSchema,
});

export const MapBentoSchema = z.object({
  id: z.string(),
  type: z.literal('map'),

  latitude: z.number(),
  longitude: z.number(),
  label: z.string().optional(),

  size: SizeSchema,
  position: PositionSchema,
});

export const GithubBentoSchema = z.object({
