type BentoSize = Literal["4x1", "2x2", "2x4", "4x2", "4x4"];

glob SIZE_TO_GRID: dict[str, dict[str, float]] = {"4x1": {"w": 2, "h": 0.5}, "2x2": {"w": 1, "h": 1}, "2x4": {"w": 1, "h": 2}, "4x2": {"w": 2, "h": 1}, "4x4": {"w": 2, "h": 2}};

glob SIZE_TO_GRID_SM: dict[str, dict[str, float]] = {"4x1": {"w": 2, "h": 0.5}, "2x2": {"w": 1, "h": 1}, "2x4": {"w": 1, "h": 2}, "4x2": {"w": 2, "h": 1}, "4x4": {"w": 2, "h": 2}};

def:pub sizeToGrid(size: str | None = None, breakpoint: Literal["sm", "md"] = "md") -> dict[str, float] {
    map = SIZE_TO_GRID_SM if breakpoint == "sm" else SIZE_TO_GRID;
    key = size if size else "2x2";
    if key in map {
        return map[key];
    }
    return SIZE_TO_GRID["2x2"];
}

