def:pub DroppableArea(
    date: object,
    hour: int | None = None,
    minute: int | None = None,
    children: object = None,
    className: str | None = None,
) -> JsxElement {
    dnd = useDragDrop();
    handleEventDrop = dnd.handleEventDrop;
    isDragging = dnd.isDragging;

    def handle_drag_over(e: Event) {
        e.preventDefault();
        e.currentTarget.classList.add("bg-primary/10");
    }

    def handle_drag_leave(e: Event) {
        e.currentTarget.classList.remove("bg-primary/10");
    }

    def handle_drop(e: Event) {
        e.preventDefault();
        e.currentTarget.classList.remove("bg-primary/10");
        handleEventDrop(date, hour, minute);
    }

    return (
        <div
            role="gridcell"
            aria-label="Droppable area"
            tabIndex={-1}
            className={f"{(className or '')} {'drop-target' if isDragging else ''}"}
            onDragOver={handle_drag_over}
            onDragLeave={handle_drag_leave}
            onDrop={handle_drop}
        >
            {children}
        </div>
    );
}

