import from "@tanstack/react-query" { useMutation, useQuery, useQueryClient }
import from "sonner" { toast }
import from "@/lib/api/download" { cancelDownloadTask, listDownloadTasks, openDownloadRootDir, openDownloadTaskDir, pauseDownloadTask, removeDownloadTask, resumeDownloadTask }
import from "@/lib/query-keys" { queryKeys }

type DownloadFilter = Literal["all", "active", "paused", "completed"];

glob:pub DOWNLOAD_FILTERS: list[dict[str, str]] = [
    {"value": "all", "label": "全部"},
    {"value": "active", "label": "下载中"},
    {"value": "paused", "label": "已暂停"},
    {"value": "completed", "label": "已完成"}
];

obj DownloadTask {
    has taskId: str;
    has status: str;
}

obj DownloadTaskListResult {
    has tasks: list[DownloadTask] = [];
}

glob EMPTY_DOWNLOAD_TASKS: list[DownloadTask] = [];

def getFilterCounts(tasks: list[DownloadTask]) -> dict[DownloadFilter, int] {
    return {
        "all": len(tasks),
        "active": len([
            task for task in tasks
            if task.status == "running" or task.status == "queued"
        ]),
        "paused": len([task for task in tasks if task.status == "paused"]),
        "completed": len([task for task in tasks if task.status == "completed"])
    };
}

def matchesFilter(task: DownloadTask, filter: DownloadFilter) -> bool {
    if filter == "active" {
        return task.status == "running" or task.status == "queued";
    }
    if filter == "paused" {
        return task.status == "paused";
    }
    if filter == "completed" {
        return task.status == "completed";
    }
    return True;
}

def showError(error: object) {
    toast.error(str(error));
}

def useTaskMutation(
    mutationFn: Callable[[str], object],
    message: str
) -> object {
    queryClient = useQueryClient();
    return useMutation({
        "mutationFn": mutationFn,
        "onSuccess": lambda (result: object) {
            queryClient.setQueryData(queryKeys.downloadTasks(), result);
            toast.success(message);
        },
        "onError": showError
    });
}

def:pub useDownloadTasks() -> dict[str, object] {
    has filter: DownloadFilter = "all";

    tasks = useQuery({
        "queryKey": queryKeys.downloadTasks(),
        "queryFn": listDownloadTasks,
        "refetchInterval": 1000,
        "refetchOnWindowFocus": False
    });
    cancelTask = useTaskMutation(cancelDownloadTask, "已取消下载任务");
    pauseTask = useTaskMutation(pauseDownloadTask, "已暂停下载任务");
    resumeTask = useTaskMutation(resumeDownloadTask, "已加入下载队列");
    removeTask = useTaskMutation(removeDownloadTask, "已删除下载任务和文件");
    openTaskDir = useMutation({
        "mutationFn": openDownloadTaskDir,
        "onError": showError
    });
    openRootDir = useMutation({
        "mutationFn": openDownloadRootDir,
        "onError": showError
    });

    taskList = tasks.data?["tasks"] or EMPTY_DOWNLOAD_TASKS;
    filterCounts = getFilterCounts(taskList);
    filteredTasks = [task for task in taskList if matchesFilter(task, filter)];

    def setFilterValue(value: DownloadFilter) {
        filter = value;
    }

    return {
        "filter": filter,
        "setFilter": setFilterValue,
        "tasks": tasks,
        "taskList": taskList,
        "filteredTasks": filteredTasks,
        "filterCounts": filterCounts,
        "cancelTask": cancelTask,
        "pauseTask": pauseTask,
        "resumeTask": resumeTask,
        "removeTask": removeTask,
        "openTaskDir": openTaskDir,
        "openRootDir": openRootDir
    };
}

