import from "@tanstack/react-router" { useNavigate }
import from "react-icons/cg" { CgFileDocument }
import from "react-icons/fa6" { FaPlus }
import from "react-icons/go" { GoGitCommit }
import from "sonner" { toast }
import from "@/components/ui/button" { Button }
import from "@/components/ui/dialog" { Dialog, DialogContent, DialogHeader, DialogOverlay, DialogTitle, DialogTrigger }
import from "@/components/ui/input" { Input }
import from "@/components/ui/toggle-group" { ToggleGroup, ToggleGroupItem }
import from "@/form-builder/hooks/use-form-builder-store" { default as useFormBuilderStore }
import from "@/form-builder/hooks/use-local-forms" { default as useLocalForms }

obj InitializedForm {
    has id: str;
    has name: str;
}

obj FormBuilderStorePick {
    has setFormElements: Callable[[list[object], dict[str, object]], None];
    has setIsMS: Callable[[bool], None];
}

obj LocalFormsStorePick {
    has initializeForm: Callable[[str, dict[str, bool]], InitializedForm | None];
}

def:pub NewForm() -> JsxElement {
    has formName: str = "";
    has formIsMS: bool = False;
    has open: bool = False;

    navigate = useNavigate();
    setFormElements = useFormBuilderStore(lambda (s: FormBuilderStorePick) -> Callable[[list[object], dict[str, object]], None] { return s.setFormElements; });
    setIsMs = useFormBuilderStore(lambda (s: FormBuilderStorePick) -> Callable[[bool], None] { return s.setIsMS; });
    initializeForm = useLocalForms(lambda (s: LocalFormsStorePick) -> Callable[[str, dict[str, bool]], InitializedForm | None] { return s.initializeForm; });

    def handleSave() -> None {
        if not formName {
            return;
        }
        newForm = initializeForm(formName, {"isMS": formIsMS});
        if newForm {
            navigate({"to": "/form-builder", "search": {"id": newForm.id}});
            setFormElements([], {"isMS": formIsMS, "id": newForm.id, "name": newForm.name});
            setIsMs(formIsMS);
        }
        open = False;
        toast("Form created successfully");
        formName = "";
        formIsMS = False;
    }

    def onKeyDown(e: KeyboardEvent) {
        if e.key == "Enter" {
            handleSave();
        }
    }

    def handleSubmit(e: FormEvent) {
        e.preventDefault();
        handleSave();
    }

    def toggleOpen() {
        open = not open;
    }

    <Dialog open={open} onOpenChange={toggleOpen}>
        <DialogTrigger asChild>
            <Button variant="outline" className="w-full"><FaPlus />New form</Button>
        </DialogTrigger>
        <DialogOverlay className="" />
        <DialogContent className="p-6 bg-glass">
            <DialogHeader>
                <DialogTitle>Create new form</DialogTitle>
            </DialogHeader>
            <div className="w-full pt-4">
                <form onSubmit={handleSubmit} className="flex items-start justify-center flex-col gap-3">
                    <Input
                        placeholder="Form Name"
                        value={formName}
                        onChange={lambda (e: ChangeEvent) { formName = e.target.value; }}
                        onKeyDown={onKeyDown}
                        required={True}
                    />
                    <ToggleGroup
                        type="single"
                        value={"multi" if formIsMS else "single"}
                        onValueChange={lambda (value: str) { formIsMS = value == "multi"; }}
                        className="flex gap-1 rounded-none"
                    >
                        <ToggleGroupItem className="rounded-md px-2" value="single">
                            <CgFileDocument className="size-4 text-secondary-foreground/50" />
                            Simple Form
                        </ToggleGroupItem>
                        <ToggleGroupItem className="rounded-md px-4" value="multi">
                            <GoGitCommit className="size-4 text-secondary-foreground/50" />
                            Multi-step Form
                        </ToggleGroupItem>
                    </ToggleGroup>
                    <div className="w-full flex justify-end pt-2">
                        <Button onClick={handleSave}>Create new form</Button>
