    isLastStep: bool,
    goToNext: Callable[[], bool],
    goToPrevious: Callable[[], None],
    goToFirstStep: Callable[[], None],
};

def:pub useMultiStepForm(
    initialSteps: list[FormStep],
    onStepValidation: Callable[[FormStep], bool] | None = None,
) -> UseMultiFormStepsReturn {
    has currentStep: int = 1;
    steps = initialSteps;

    async def goToNext() -> bool {
        currentStepData = initialSteps[currentStep - 1];
        if onStepValidation {
            isValid = await onStepValidation(currentStepData);
            if not isValid {
                return False;
            }
        }
        if currentStep < len(steps) {
            currentStep = currentStep + 1;
            return True;
        }
        return False;
    }

    def goToPrevious() {
        if currentStep > 1 {
            currentStep = currentStep - 1;
        }
    }

    def goToFirstStep() {
        currentStep = 1;
    }

    return {
        "steps": steps,
        "currentStep": currentStep,
        "currentStepData": steps[currentStep - 1],
        "progress": (currentStep / len(steps)) * 100.0,
        "isFirstStep": currentStep == 1,
        "isLastStep": currentStep == len(steps),
        "goToNext": goToNext,
        "goToPrevious": goToPrevious,
        "goToFirstStep": goToFirstStep,
    };
}

