import from "react" { useEffect }

def getThemePreset(name: str) -> dict[str, dict[str, dict[str, str]]] {
    return {
        "colors": {
            "dark": {},
            "light": {},
        },
    };
}

def:pub ThemeWrapper(
    children: JsxElement | str | None = None,
    theme: str | None = None,
    darkMode: bool | None = None,
    accentColor: str | None = None,
) -> JsxElement {
    themePreset = getThemePreset(theme if theme else "default");
    isDark = darkMode if darkMode is not None else False;
    colors = themePreset["colors"]["dark"] if isDark else themePreset["colors"]["light"];

    style: dict[str, str] = {};
    for (key, value) in colors.items() {
        style[key] = value;
    }
    if accentColor {
        style["--primary"] = accentColor;
        style["--accent"] = accentColor;
    }

    useEffect(lambda {
        el = document.body;
        vars = list(style.items());
        for (key, value) in vars {
            el.style.setProperty(key, value);
        }
        if isDark {
            el.classList.add("dark");
        }
        return lambda {
            for (key, _) in vars {
                el.style.removeProperty(key);
            }
            el.classList.remove("dark");
        };
    }, [style, isDark]);

    darkPrefix = "dark " if isDark else "";
    <div className={darkPrefix + "w-full bg-background text-foreground"} style={style}>
        <div className="fixed inset-0 z-0 bg-background" />
        <div className="relative z-10 w-full">{children}</div>
    </div>
}

