glob:pub FALLBACK_API_ENDPOINTS: list[str] = ["https://www.cdnhjk.net", "https://www.cdnhth.club"];

glob:pub READER_CACHE_LIMITS_MB: list[int] = [128, 256, 512, 1024, 2048];

glob:pub PROXY_MODES: list[str] = ["off", "http", "socks5"];

glob:pub READER_READ_MODES: list[str] = ["single", "strip"];

glob:pub READER_PAGE_DIRECTIONS: list[str] = ["ltr", "rtl"];

glob:pub READER_AUTO_READ_STRIP_DISTANCE_RANGE: list[int] = [10, 100];

glob:pub READER_AUTO_READ_STRIP_INTERVAL_RANGE: list[int] = [300, 5000];

glob:pub READER_AUTO_READ_PAGE_INTERVAL_RANGE: list[int] = [800, 10000];

glob DEFAULT_SETTINGS: dict[str, bool | int | str] = {
    "api": FALLBACK_API_ENDPOINTS[0],
    "readerCacheLimitMb": 512,
    "readerReadMode": READER_READ_MODES[0],
    "readerPageDirection": READER_PAGE_DIRECTIONS[0],
    "readerDoublePageMode": False,
    "readerAutoReadEnabled": False,
    "readerAutoReadStripIntervalMs": 1600,
    "readerAutoReadPageIntervalMs": 3000,
    "readerAutoReadStripDistancePercent": 72,
    "proxyMode": PROXY_MODES[0],
    "proxyHost": "127.0.0.1",
    "proxyPort": 7890,
    "hideCovers": True,
    "nsfwWarningDismissed": False
};

def isReaderCacheLimitMb(value: int) -> bool {
    return value in READER_CACHE_LIMITS_MB;
}

def isProxyMode(value: str) -> bool {
    return value in PROXY_MODES;
}

def isReaderReadMode(value: str) -> bool {
    return value in READER_READ_MODES;
}

def isReaderPageDirection(value: str) -> bool {
    return value in READER_PAGE_DIRECTIONS;
}

def isProxyPort(value: int) -> bool {
    return value > 0 and value <= 65535;
}

def clampNumber(value: float, min_val: float, max_val: float, fallback: float) -> int {
    if not math.isfinite(value) {
        return int(fallback);
    }
    rounded = round(value);
    clamped = max(min_val, min(max_val, rounded));
    return int(clamped);
}

def normalizeApiEndpoint(value: str) -> str | None {
    trimmed = value.strip();
    if not trimmed {
        return None;
    }
    with_scheme = trimmed if trimmed.startswith("http://") or trimmed.startswith("https://") else f"https://{trimmed}";
    parsed = urlparse(with_scheme);
    if not parsed.scheme or not parsed.netloc {
        return None;
    }
    origin = f"{parsed.scheme}://{parsed.netloc}";
    if origin.endswith("/") {
        return origin[:-1];
    }
    return origin;
}

