import from "@/components/prompt-kit/prompt-input" { PromptInput, PromptInputActions, PromptInputTextarea }
import from "@/components/prompt-kit/prompt-suggestion" { PromptSuggestion }
import from "@/components/ui/button" { Button }
import from "lucide-react" { ArrowUpIcon, BrainIcon }

glob suggestionGroups: list[dict[str, str | list[str]]] = [
    {"label": "Summary", "highlight": "Summarize", "items": ["Summarize a document", "Summarize a video", "Summarize a podcast", "Summarize a book"]},
    {"label": "Code", "highlight": "Help me", "items": ["Help me write React components", "Help me debug code", "Help me learn Python", "Help me learn SQL"]},
    {"label": "Design", "highlight": "Design", "items": ["Design a small logo", "Design a hero section", "Design a landing page", "Design a social media post"]},
    {"label": "Research", "highlight": "Research", "items": ["Research the best practices for SEO", "Research the best running shoes", "Research the best restaurants in Paris", "Research the best AI tools"]},
];

def:pub PromptSuggestionVariants() -> JsxElement {
    has inputValue: str = "";
    has activeCategory: str = "";

    def handleSend() {
        if inputValue.strip() {
            console.log("Sending:", inputValue);
            inputValue = "";
            activeCategory = "";
        }
    }

    def handleKeyDown(e: KeyboardEvent) {
        if e.key == "Enter" and not e.shiftKey {
            e.preventDefault();
            handleSend();
        }
    }

    def handlePromptInputValueChange(value: str) {
        inputValue = value;
        if value.strip() == "" {
            activeCategory = "";
        }
    }

    def selectCategory(label: str) {
        activeCategory = label;
    }

    def selectPrompt(prompt: str) {
        inputValue = prompt;
    }

    activeCategoryData: dict[str, str | list[str]] | None = None;
    for group in suggestionGroups {
        if (group["label"] as str) == activeCategory {
            activeCategoryData = group;
            break;
        }
    }
    showCategorySuggestions = activeCategory != "";

    <div className="flex w-full flex-col space-y-4">
        <PromptInput
            className="border-input bg-background border shadow-xs"
            value={inputValue}
            onValueChange={handlePromptInputValueChange}
            onKeyDown={handleKeyDown}
            onSubmit={handleSend}
        >
            <PromptInputTextarea placeholder="Type a message or click a suggestion..." />
            <PromptInputActions className="justify-end">
                <Button
                    size="sm"
                    className="size-9 cursor-pointer rounded-full"
                    onClick={handleSend}
                    disabled={not inputValue.strip()}
                    aria-label="Send"
                >
                    <ArrowUpIcon className="h-4 w-4" />
                </Button>
            </PromptInputActions>
        </PromptInput>
        <div className="flex flex-wrap gap-2">
            {for group in suggestionGroups {
                <PromptSuggestion key={group["label"] as str} onClick={lambda { selectCategory(group["label"] as str); }}>
                    <BrainIcon className="mr-1 h-4 w-4" />
                    {group["label"] as str}
                </PromptSuggestion>
            }}
        </div>
        {if showCategorySuggestions and activeCategoryData {
            <div className="flex flex-wrap gap-2">
                {for item in (activeCategoryData["items"] as list[str]) {
                    <PromptSuggestion
                        key={item}
                        highlight={activeCategoryData["highlight"] as str}
                        onClick={lambda { selectPrompt(item); }}
                    >
                        {item}
                    </PromptSuggestion>
                }}
            </div>
        }}
    </div>
}

