def TrackPage_(path: str) -> JsxElement {
    sendEvent = useAnalytics();
    searchParams = useSearchParams();
    ref = searchParams.get("ref");
    can with (path, ref, sendEvent) entry {
        pageUrl = path + (f"?ref={ref}" if ref else "");
        sendEvent({"event": "pageview", "props": {}}, pageUrl);
    }
    return <></>;
}

