                    <span className="ml-2">
                        Cntl + Z
                    </span>
                </TooltipContent>
            </Tooltip>

            <Tooltip>
                <TooltipTrigger asChild>
                    <span>
                        <Button
                            size={"icon"}
                            onClick={adjustPositions}
                            variant={"ghost"}
                        >
                            <LayoutGrid className="size-4" />
                        </Button>
                    </span>
                </TooltipTrigger>
                <TooltipContent>
                    {t("control_buttons.adjust_positions")}
                </TooltipContent>
            </Tooltip>

            <Separator orientation="vertical" />

            <Tooltip>
                <TooltipTrigger asChild>
                    <span>
                        <Button
                            size="icon"
                            onClick={onZoomOut}
                            variant={"ghost"}
                        >
                            <ZoomOut className="size-4" />
                        </Button>
                    </span>
                </TooltipTrigger>
                <TooltipContent>
                    {t("control_buttons.zoom_out")}
                </TooltipContent>
            </Tooltip>

            <Button
                size="icon"
                variant={"ghost"}
                onClick={resetZoom}
                className="w-[60px] p-2 "
            >
                {zoom}
            </Button>
            <Tooltip>
                <TooltipTrigger asChild>
                    <span>
                        <Button
                            size="icon"
                            onClick={onZoomIn}
                            variant={"ghost"}
                        >
