import from "@radix-ui/react-toggle" { * as TogglePrimitive }
import from "~/lib/utils" { cn }

def:pub toggleVariants(props: dict[str, str]) -> str {
    variant = props.get("variant", "default");
    size = props.get("size", "default");
    extra = props.get("className", "");
    base = "inline-flex items-center justify-center rounded-md text-sm font-medium transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground";
    variant_map: dict[str, str] = {
        "default": "bg-transparent",
        "outline": "border border-input bg-transparent shadow-sm hover:bg-accent hover:text-accent-foreground",
    };
    size_map: dict[str, str] = {
        "default": "h-9 px-3",
        "sm": "h-8 px-2",
        "lg": "h-10 px-3",
    };
    return cn(base, variant_map.get(variant, variant_map["default"]), size_map.get(size, size_map["default"]), extra);
}

def:pub Toggle(className: str = "", variant: str = "default", size: str = "default", ref: object = None) -> JsxElement {
    <TogglePrimitive.Root
        ref={ref}
        className={cn(toggleVariants({"variant": variant, "size": size, "className": className}))}
    />
}

