import os;
import from jaclang.byllm.lib { Model }
import from lib.api { getCategories }
import from lib.featureFlags { getRuntimeFeatureFlags }
import from lib.uploaded_image_url { isAllowedUploadUrl }
import from lib.utils { formatCategoryForAIPrompt }

glob llm: Model = Model(model_name=os.environ.get("OPENAI_MODEL_RECEIPT_EXTRACT", "gpt-4o"));

obj ReceiptExtractedInfo {
    has amount: float | None = None;
    has categoryId: str | None = None;
    has date: str | None = None;
    has title: str | None = None;
}

obj ReceiptLLMResult {
    has amount: float;
    has categoryId: str;
    has date: str;
    has title: str;
}

sem ReceiptLLMResult.amount = "Total amount as a non-formatted number without currency text.";
sem ReceiptLLMResult.categoryId = "ID of the best matching category from the provided list.";
sem ReceiptLLMResult.date = "Expense date in yyyy-mm-dd format.";
sem ReceiptLLMResult.title = "Short descriptive title for the expense.";

def extract_receipt_fields(imageUrl: str, categoryPrompt: str) -> ReceiptLLMResult by llm();
sem extract_receipt_fields = "Read the receipt image and extract expense details.";
sem extract_receipt_fields.imageUrl = "URL of the uploaded receipt image.";
sem extract_receipt_fields.categoryPrompt = "Formatted list of available categories with IDs.";

def finite_amount(raw: float | None) -> float | None {
    if raw is None {
        return None;
    }
    n = float(raw);
    if n != n {
        return None;
    }
    return n;
}

async def:pub extractExpenseInformationFromImage(imageUrl: str) -> ReceiptExtractedInfo {
    flags = await getRuntimeFeatureFlags();
    if not flags.enableReceiptExtract {
        raise ValueError("Receipt extraction is not enabled.");
    }
    if not isAllowedUploadUrl(imageUrl) {
        raise ValueError("Invalid image URL.");
    }
    categories = await getCategories();
    categoryPrompt = ", ".join([formatCategoryForAIPrompt(c) for c in categories]);
    try {
        parsed = extract_receipt_fields(imageUrl, categoryPrompt);
        return ReceiptExtractedInfo(
            amount=finite_amount(parsed.amount),
            categoryId=parsed.categoryId,
            date=parsed.date,
            title=parsed.title
        );
    } except Exception {
        return ReceiptExtractedInfo();
    }
}

