import from "@/lib/utils" { cn }

obj BrandItem {
    has name: str;
    has logo: str;
}

glob brandItems: list[BrandItem] = [
    BrandItem(name="Wrappixel", logo="/images/landingpage/wrappixel.svg"),
    BrandItem(name="Theme Designer", logo="/images/landingpage/theme_designer.svg"),
    BrandItem(name="Envanto", logo="/images/landingpage/envanto.svg"),
    BrandItem(name="Adminmart", logo="/images/landingpage/adminmart.svg"),
    BrandItem(name="Tailwind Admin", logo="/images/landingpage/tailwind_admin.svg"),
];

def:pub Brands(
    direction: str = "left",
    speed: str = "fast",
    pauseOnHover: bool = True,
    className: str = ""
) -> JsxElement {
    has containerRef: Ref[HTMLDivElement] = Ref();
    has scrollerRef: Ref[HTMLUListElement] = Ref();
    has start: bool = False;

    def getDirection() -> None {
        if containerRef.current {
            if direction == "left" {
                containerRef.current.style.setProperty("--animation-direction", "forwards");
            } else {
                containerRef.current.style.setProperty("--animation-direction", "reverse");
            }
        }
    }

    def getSpeed() -> None {
        if containerRef.current {
            if speed == "fast" {
                containerRef.current.style.setProperty("--animation-duration", "20s");
            } elif speed == "normal" {
                containerRef.current.style.setProperty("--animation-duration", "40s");
            } else {
                containerRef.current.style.setProperty("--animation-duration", "80s");
            }
        }
    }

    def addAnimation() -> None {
        if containerRef.current and scrollerRef.current {
            scrollerContent = list(scrollerRef.current.children);
            for item in scrollerContent {
                duplicatedItem = item.cloneNode(True);
                if scrollerRef.current {
                    scrollerRef.current.appendChild(duplicatedItem);
                }
            }
            getDirection();
            getSpeed();
            start = True;
        }
    }

    can with entry {
        addAnimation();
    }

    <div className="lg:pt-12 pt-8 border-t border-border">
        <div
            ref={containerRef}
            className={cn(
                "scroller relative z-20 container mx-auto overflow-hidden mask-[linear-gradient(to_right,transparent,white_20%,white_80%,transparent)]",
                className
            )}
        >
            <ul
                ref={scrollerRef}
                className={cn(
                    "flex w-max min-w-full shrink-0 flex-nowrap gap-30 py-4",
                    "animate-scroll" if start else "",
                    "hover:paused" if pauseOnHover else ""
                )}
            >
                {for item in brandItems {
                    <li key={item.name} className="relative shrink-0 flex items-center justify-center">
                        <img src={item.logo} alt={item.name} width={120} height={40} className="h-10 w-auto" />
                    </li>
                }}
            </ul>
        </div>
    </div>
}

