    has title: str;
    has desc: str;
    has time: str;
}

glob PROFILE_ITEMS: list[NotifItem] = [
    NotifItem(text_color="stroke-blue-500", bg_color="bg-blue-500/10", icon_idx=0, title="Event Today", desc="Just reminder that you have to", time="9:00 AM"),
    NotifItem(text_color="stroke-orange-400", bg_color="bg-orange-400/10", icon_idx=1, title="Team Meeting", desc="Discuss project updates and next steps", time="10:00 AM"),
    NotifItem(text_color="stroke-teal-400", bg_color="bg-teal-400/10", icon_idx=2, title="Lunch Break", desc="Take a break and recharge", time="12:30 PM"),
    NotifItem(text_color="stroke-red-500", bg_color="bg-red-500/10", icon_idx=3, title="Client Call", desc="Monthly check-in with the client", time="3:00 PM"),
    NotifItem(text_color="stroke-sky-400", bg_color="bg-sky-400/10", icon_idx=4, title="Project Review", desc="Review project deliverables with client", time="4:00 PM"),
];

def notif_icon(icon_idx: int, text_color: str) -> JsxElement {
    match icon_idx {
        case 0:
            return <Star size={20} className={cn("size-5", text_color)} />;
        case 1:
            return <Video size={20} className={cn("size-5", text_color)} />;
        case 2:
            return <Salad size={20} className={cn("size-5", text_color)} />;
        case 3:
            return <Headset size={20} className={cn("size-5", text_color)} />;
        case _:
            return <ScanText size={20} className={cn("size-5", text_color)} />;
    }
