import from "lucide-react" {
    BarChart3,
    ChartArea,
    Check,
    CirclePlay,
    Diamond,
    FormInput,
    LayoutGrid,
    Route,
}
import from "motion/react" { motion, AnimatePresence }
import from "react" { useEffect }

obj ReminderItem {
    has id: str;
    has title: str;
    has iconId: str;
}

glob DATA: list[ReminderItem] = [
    ReminderItem(id="1", title="Breadcrumb component", iconId="route"),
    ReminderItem(id="2", title="Animated component", iconId="circle-play"),
    ReminderItem(id="3", title="UI components", iconId="diamond"),
    ReminderItem(id="4", title="Form components", iconId="form-input"),
    ReminderItem(id="5", title="Chart components", iconId="bar-chart"),
    ReminderItem(id="6", title="Layout components", iconId="layout-grid"),
    ReminderItem(id="7", title="Area Chart", iconId="chart-area"),
];

def render_reminder_icon(iconId: str) -> JsxElement {
    if iconId == "route" { return <Route size={20} />; }
    if iconId == "circle-play" { return <CirclePlay size={20} />; }
    if iconId == "diamond" { return <Diamond size={20} />; }
    if iconId == "form-input" { return <FormInput size={20} />; }
    if iconId == "bar-chart" { return <BarChart3 size={20} />; }
    if iconId == "layout-grid" { return <LayoutGrid size={20} />; }
    return <ChartArea size={20} />;
}

def:pub ReminderCarousel() -> JsxElement {
    has visible: list[ReminderItem] = DATA[0:3];
    has pointer: int = 2;

    useEffect(lambda {
        interval = setInterval(lambda {
            nextIndex = (pointer + 1) % len(DATA);
            pointer = nextIndex;
            visible = visible[1:] + [DATA[nextIndex]];
        }, 2000);
        return lambda { clearInterval(interval); };
    }, [pointer]);

    <div className="relative flex flex-col items-center rounded-2xl h-52 w-full overflow-hidden">
        <AnimatePresence initial={False}>
            {for (i, item) in enumerate(visible) {
                <motion.div
                    key={item.id}
                    initial={{"y": 215, "opacity": 0, "scale": 0.9}}
                    animate={{
                        "y": i * 70,
                        "scale": 1.0 if i == 1 else 0.9,
                        "opacity": 1.0 if i == 1 else 0.5,
                    }}
                    exit={{"y": -100, "opacity": 0, "scale": 0.8}}
                    transition={{"duration": 0.6, "ease": "easeInOut"}}
                    className="absolute flex items-center justify-between w-full px-5 py-4 rounded-xl bg-background border border-border text-card-foreground"
                >
                    <div className="flex items-center justify-between w-full">
                        <div className="flex items-center gap-2">
                            {render_reminder_icon(item.iconId)}
                            <span className="text-sm font-medium">{item.title}</span>
                        </div>
                        <Check size={20} />
                    </div>
                </motion.div>
            }}
        </AnimatePresence>
    </div>
}

