                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -5 }}
                transition={{ duration: 0.15 }}
                className="inline-flex items-center gap-2"
              >
                <UserCheckIcon className="size-4 shrink-0 text-green-500" />
                <span>Following</span>
              </motion.span>
            )
