                        placeholder="Search or create label..."
                        value={query}
                        onValueChange={handle_query_change}
                    />
                    <CommandList>
                        <CommandEmpty>No label found.</CommandEmpty>
                        <CommandGroup>
                            {for label in labels {
                                <CommandItem
                                    key={label.value}
