import from "@base-ui/react/checkbox" { Root as CheckboxPrimitiveRoot, Indicator as CheckboxPrimitiveIndicator }
import from "lucide-react" { CheckIcon, MinusIcon }
import from "@/components/ui/label" { Label }

glob items: list[str] = ["Nike", "Adidas", "Puma"];

def Checkbox(
    checked: bool | str | None = None,
    defaultChecked: bool | str | None = None,
    onCheckedChange: Callable[[bool], None] | None = None,
    id: str = "",
    className: str = "",
) -> JsxElement {
    checked_val = None if checked == "indeterminate" else checked;
    indeterminate = checked == "indeterminate";
    default_val = False if defaultChecked == "indeterminate" else defaultChecked;
    def handle_change(c: bool) {
        if onCheckedChange {
            onCheckedChange(c);
        }
    }
    <CheckboxPrimitiveRoot
        data-slot="checkbox"
        checked={checked_val}
        indeterminate={indeterminate}
        defaultChecked={default_val}
        onCheckedChange={handle_change}
        id={id}
        className={className if className else "peer border-input dark:bg-input/30 data-[checked]:bg-primary data-[checked]:text-primary-foreground data-[indeterminate]:text-foreground dark:data-[checked]:bg-primary data-[checked]:border-primary focus-visible:border-ring focus-visible:ring-ring/50 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive group size-4 shrink-0 rounded-[4px] border shadow-xs transition-shadow outline-none focus-visible:ring-[3px] disabled:cursor-not-allowed disabled:opacity-50"}
    >
        <CheckboxPrimitiveIndicator
            data-slot="checkbox-indicator"
            className="flex items-center justify-center text-current transition-none"
        >
            <MinusIcon className="hidden size-2.5 group-data-[indeterminate]:block" />
            <CheckIcon className="hidden size-3.5 group-data-[checked]:block" />
        </CheckboxPrimitiveIndicator>
    </CheckboxPrimitiveRoot>
}

def:pub CheckboxTreeDemo() -> JsxElement {
    has checked: bool | str = "indeterminate";
    has selected: list[str] = ["Child 1", "Child 2"];

    can with [selected] entry {
        if len(selected) == len(items) {
            checked = True;
        } elif len(selected) > 0 {
            checked = "indeterminate";
        } else {
            checked = False;
        }
    }

    def handle_checked_change(value: bool | str) {
        checked = value;
        if value == True {
            selected = [item for item in items];
        } elif value == False {
            selected = [];
        }
    }

    def handle_item_change(label: str, value: bool) {
        if value {
            selected = selected + [label];
        } else {
            selected = [item for item in selected if item != label];
        }
    }

    <div className="flex flex-col gap-4">
        <div className="flex items-center gap-2">
            <Checkbox id="Brands" checked={checked} onCheckedChange={handle_checked_change} />
            <Label htmlFor="Brands">Brands</Label>
        </div>
        <div className="flex flex-col gap-2 pl-6">
            {for label in items {
                <div key={label} className="flex items-center gap-2">
                    <Checkbox
                        id={label}
                        checked={label in selected}
                        onCheckedChange={lambda (value: bool) { handle_item_change(label, value); }}
                    />
                    <Label htmlFor={label} className="text-muted-foreground">
                        label;
                    </Label>
                </div>
            }}
        </div>
    </div>
}

