"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Collapsible, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Separator } from "@/components/ui/separator";
import {
  ArrowRight,
  ChevronRightIcon,
  ClockIcon,
  LucideIcon,
  MapPinIcon,
  MessageSquareIcon,
} from "lucide-react";

export type StatRow = {
  icon: LucideIcon;
  label: string;
  value: string;
};

export type Collapsible04Props = {
  name?: string;
  username?: string;
  avatar?: string;
  status?: string;
  stats?: StatRow[];
  profileHref?: string;
};

const containerVariants = {
  hidden: { height: 0, opacity: 0 },
  visible: {
    height: "auto",
    opacity: 1,
    transition: {
      duration: 0.3,
      ease: [0.04, 0.62, 0.23, 0.98],
      staggerChildren: 0.07,
      delayChildren: 0.1,
    },
  },
  exit: {
    height: 0,
    opacity: 0,
    transition: { duration: 0.25, ease: "easeInOut" },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: -6 },
  visible: {
    opacity: 1,
    y: 0,
    transition: { duration: 0.22, ease: "easeOut" },
  },
  exit: { opacity: 0, y: -4, transition: { duration: 0.15 } },
};

const defaultStats: StatRow[] = [
  { icon: MessageSquareIcon, label: "Last activity", value: "2 hours ago" },
  { icon: ClockIcon, label: "Member since", value: "Mar 2022" },
  { icon: MapPinIcon, label: "Location", value: "New York, US" },
];

