import from "@/lib/utils" { cn }
import from "lucide-react" { Upload }

obj FileMeta {
    has name: str;
    has size: int;
    has lastModified: int;
}

def format_file_size(size: int) -> str {
    return f"{(size / (1024 * 1024)):.2f}";
}

def format_date(timestamp: int) -> str {
    return new(Date, timestamp).toLocaleDateString();
}

def FileItem(file: FileMeta) -> JsxElement {
    <div className={cn("relative overflow-hidden z-40 bg-card border flex flex-col items-start justify-start md:h-24 p-4 mt-4 w-full mx-auto rounded-md shadow-sm")}>
        <div className="flex justify-between w-full items-center gap-4">
            <p className="text-sm font-medium text-foreground truncate max-w-xs">{file.name}</p>
            <p className="rounded-full bg-primary/10 px-2 py-0.5 text-xs text-muted-foreground">{format_file_size(file.size)} MB</p>
        </div>
        <p className="text-xs text-muted-foreground mt-2">{format_date(file.lastModified)}</p>
    </div>
}

def EmptyState() -> JsxElement {
    <div className="flex flex-col items-center justify-center py-8">
        <Upload className="size-10 text-muted-foreground" />
        <p className="text-sm text-muted-foreground mt-2">No files uploaded yet</p>
    </div>
}

def:pub FileUploadStruc(onChange: Callable[[list[FileMeta]], None] | None = None) -> JsxElement {
    has files: list[FileMeta] = [];
    has fileInputRef: Ref[HTMLInputElement] = Ref();

    def handle_input_change(e: ChangeEvent) {
        target = e.target as HTMLInputElement;
        if target.files {
            collected: list[FileMeta] = [];
            for raw in list(target.files) {
                entry = raw as dict[str, object];
                collected = collected + [FileMeta(name=entry["name"] as str, size=entry["size"] as int, lastModified=entry["lastModified"] as int)];
            }
            files = files + collected;
            if onChange { onChange(collected); }
        }
    }

    def handle_click(_e: MouseEvent) {
        if fileInputRef.current { fileInputRef.current.click(); }
    }

    <div className="w-full">
        <div onClick={handle_click} className="p-6 group/file block rounded-lg cursor-pointer w-full relative overflow-hidden">
            <input ref={fileInputRef} id="file-upload-handle" type="file" onChange={handle_input_change} className="hidden" />
            <div className="flex flex-col items-center justify-center">
                <p className="relative z-20 font-bold text-foreground text-xl">Upload file</p>
                <p className="relative z-20 font-normal text-muted-foreground text-base mt-2">Drag or drop your files here or click to upload</p>
                <div className="relative w-full mt-10 max-w-xl mx-auto">
                    {if len(files) > 0 {
                        for (idx, file) in enumerate(files) {
                            <FileItem key={file.name + str(idx)} file={file} />
                        }
                    } else {
                        <EmptyState />
                    }}
                </div>
            </div>
        </div>
    </div>
}

