            CommandCheckboxItem(id="badges", label="Badges", count=25),
        ],
    ),
];

def build_filters(groups: list[CommandFilterGroup]) -> dict[str, str] {
    result: dict[str, str] = {};
    for g in groups {
        result[g.id] = g.defaultValue;
    }
    return result;
}

def:pub CommandFilterSearchDemo(
    buttonLabel: str = "Search & Filter",
    placeholder: str = "Search...",
    emptyMessage: str = "No results found.",
    filterGroups: list[CommandFilterGroup] = defaultFilterGroups,
    checkboxGroups: list[CommandCheckboxGroup] = defaultCheckboxGroups,
) -> JsxElement {
    has open: bool = False;
    has filters: dict[str, str] = {};
    has selectedItems: list[str] = [];

    can with entry {
        filters = build_filters(filterGroups);
    }

    def toggle_item(id: str) {
        if id in selectedItems {
            selectedItems = [x for x in selectedItems if x != id];
        } else {
            selectedItems = selectedItems + [id];
        }
    }

  <div className="flex flex-col gap-4">
    <Button onClick={lambda (e: MouseEvent) { open = True; }} variant="outline" className="w-fit cursor-pointer">
      <SlidersHorizontalIcon />
      {buttonLabel}
    </Button>
    <CommandDialog open={open} onOpenChange={lambda (value: bool) { open = value; }}>
      <Command>
        <CommandInput placeholder={placeholder} />
        <CommandList>
          <CommandEmpty>{emptyMessage}</CommandEmpty>
          {for group in filterGroups {
            <CommandGroup heading={group.heading} key={group.id}>
              <RadioGroup
                value={filters[group.id]}
                onValueChange={lambda (value: str) { filters = {**filters, **{group.id: value}}; }}
              >
                {for option in group.options {
                  <CommandItem key={option.value} className="cursor-pointer">
                    <RadioGroupItem value={option.value} />
                    <Label>{option.label}</Label>
                  </CommandItem>
                }}
              </RadioGroup>
            </CommandGroup>
          }}
          <CommandSeparator />
          {for group in checkboxGroups {
            <CommandGroup heading={group.heading} key={group.heading}>
              {for item in group.items {
                <CommandItem key={item.id} className="cursor-pointer">
                  <Checkbox
                    checked={item.id in selectedItems}
                    onCheckedChange={lambda { toggle_item(item.id); }}
                  />
                  <Label>{item.label}</Label>
                  <span className="ml-auto text-xs text-muted-foreground">{str(item.count)}</span>
                </CommandItem>
              }}
            </CommandGroup>
          }}
        </CommandList>
      </Command>
    </CommandDialog>
  </div>
}

