def:pub InteractiveJump() -> JsxElement {
    has active_page: int = 12;
    has is_editing: bool = False;
    has input_value: str = "12";
    total_pages = 48;

    def handle_page_change(page: int) {
        new_page = max(1, min(total_pages, page));
        active_page = new_page;
        input_value = str(new_page);
        is_editing = False;
    }

    def handle_input_submit(e: FormEvent) {
        e.preventDefault();
        try {
            page = int(input_value);
            handle_page_change(page);
        } except ValueError {
            input_value = str(active_page);
            is_editing = False;
        }
    }

    def handle_prev(e: MouseEvent) {
        e.preventDefault();
        handle_page_change(active_page - 1);
    }

    def handle_next(e: MouseEvent) {
        e.preventDefault();
        handle_page_change(active_page + 1);
    }

    def start_editing(e: MouseEvent) {
        is_editing = True;
    }

    def handle_input_change(e: ChangeEvent) {
        input_value = e.target.value;
    }

    def handle_input_blur(e: FocusEvent) {
        is_editing = False;
    }

    <Pagination className="justify-center">
        <PaginationContent className="bg-background border p-1.5 rounded-xl gap-2">
            <PaginationItem>
                <PaginationPrevious
                    href="#"
