import from "lucide-react" { SlidersHorizontalIcon, StarIcon }
import from "@/components/ui/sheet" { Sheet, SheetTrigger, SheetContent, SheetHeader, SheetTitle, SheetDescription, SheetFooter, SheetClose }
import from "@/components/ui/button" { Button }
import from "@/components/ui/checkbox" { Checkbox }
import from "@/components/ui/slider" { Slider }
import from "@/components/ui/label" { Label }
import from "@/components/ui/badge" { Badge }
import from "@/components/ui/separator" { Separator }

glob CATEGORIES: list[str] = ["Watches", "Clothing", "Beauty", "Electronics", "Home & Living"];
glob RATINGS: list[int] = [4, 3, 2, 1];
glob AVAILABILITY: list[str] = ["In Stock", "On Sale"];

def:pub AdvancedFiltersDemo() -> JsxElement {
    has selectedCategories: list[str] = [];
    has priceMin: int = 0;
    has priceMax: int = 1000;
    has selectedRating: int | None = None;
    has selectedAvailability: list[str] = [];

    def toggleCategory(cat: str) {
        if cat in selectedCategories {
            selectedCategories = [c for c in selectedCategories if c != cat];
        } else {
            selectedCategories = selectedCategories + [cat];
        }
    }

    def toggleAvailability(val: str) {
        if val in selectedAvailability {
            selectedAvailability = [v for v in selectedAvailability if v != val];
        } else {
            selectedAvailability = selectedAvailability + [val];
        }
    }

    def clearAll() {
        selectedCategories = [];
        priceMin = 0;
        priceMax = 1000;
        selectedRating = None;
        selectedAvailability = [];
    }

    def onPriceChange(vals: list[int]) {
        if len(vals) >= 2 {
            priceMin = vals[0];
            priceMax = vals[1];
        }
    }

    activeCount = len(selectedCategories) + (1 if priceMin != 0 or priceMax != 1000 else 0) + (1 if selectedRating is not None else 0) + len(selectedAvailability);

    <Sheet>
        <SheetTrigger render={<Button variant="outline" className="relative cursor-pointer gap-2" />}>
            <SlidersHorizontalIcon size={16} />
            Filters
            {if activeCount > 0 {
                <Badge className="size-5 justify-center rounded-full p-0 text-[10px]">
                    {activeCount}
                </Badge>
            }}
        </SheetTrigger>
        <SheetContent side="left" className="flex flex-col p-0 gap-0">
            <SheetHeader className="px-4 pt-5 pb-4 border-b">
                <div className="flex items-center justify-between">
                    <SheetTitle>Filters</SheetTitle>
                </div>
                <SheetDescription>Narrow down products by your preferences.</SheetDescription>
            </SheetHeader>
            <div className="flex-1 overflow-y-auto px-4 py-4 flex flex-col gap-5">
                <div className="flex flex-col gap-3">
                    <p className="text-sm font-medium">Category</p>
                    {for cat in CATEGORIES {
                        <div key={cat} className="flex items-center gap-2.5">
                            <Checkbox
                                id={f"cat-{cat}"}
                                checked={cat in selectedCategories}
                                onCheckedChange={lambda (checked: bool) { toggleCategory(cat); }}
                            />
                            <Label htmlFor={f"cat-{cat}"} className="text-sm font-normal cursor-pointer">
                                {cat}
                            </Label>
                        </div>
                    }}
                </div>
                <Separator />
                <div className="flex flex-col gap-4">
                    <div className="flex items-center justify-between">
                        <p className="text-sm font-medium">Price Range</p>
                        <span className="text-xs text-muted-foreground">
                            ${priceMin} - ${priceMax}
                        </span>
                    </div>
                    <Slider value={[priceMin, priceMax]} onValueChange={onPriceChange} min={0} max={1000} step={10} />
                </div>
                <Separator />
                <div className="flex flex-col gap-3">
                    <p className="text-sm font-medium">Minimum Rating</p>
                    {for rating in RATINGS {
                        <div key={str(rating)} className="flex items-center gap-2.5">
                            <Checkbox
                                id={f"rating-{rating}"}
                                checked={selectedRating == rating}
                                onCheckedChange={lambda (checked: bool) {
                                    selectedRating = None if selectedRating == rating else rating;
                                }}
                            />
                            <Label htmlFor={f"rating-{rating}"} className="flex items-center gap-1 text-sm font-normal cursor-pointer">
                                {for i in range(rating) {
                                    <StarIcon key={str(i)} className="size-3.5 fill-amber-400 text-amber-400" />
                                }}
                                <span className="text-muted-foreground">& up</span>
                            </Label>
                        </div>
                    }}
                </div>
                <Separator />
                <div className="flex flex-col gap-3">
                    <p className="text-sm font-medium">Availability</p>
                    {for val in AVAILABILITY {
                        <div key={val} className="flex items-center gap-2.5">
                            <Checkbox
                                id={f"avail-{val}"}
                                checked={val in selectedAvailability}
                                onCheckedChange={lambda (checked: bool) { toggleAvailability(val); }}
                            />
                            <Label htmlFor={f"avail-{val}"} className="text-sm font-normal cursor-pointer">
                                {val}
                            </Label>
                        </div>
                    }}
                </div>
            </div>
            <SheetFooter className="px-4 py-4 border-t gap-2">
                <Button variant="outline" onClick={clearAll} className="flex-1 cursor-pointer">Clear All</Button>
                <SheetClose render={<Button className="flex-1 cursor-pointer">Apply Filters</Button>} />
            </SheetFooter>
        </SheetContent>
    </Sheet>
}

