import from "motion/react" { motion }
import from "@/lib/utils" { cn }

def ripple_container_class(size: str) -> str {
    if size == "sm" {
        return "size-6";
    }
    if size == "lg" {
        return "size-24";
    }
    return "size-12";
}

def ripple_border_width(size: str) -> str {
    if size == "sm" {
        return "border";
    }
    if size == "lg" {
        return "border-[3px]";
    }
    return "border-2";
}

def:pub RippleSpinner(size: str = "md", className: str = "") -> JsxElement {
    container_cls = ripple_container_class(size);
    border_w = ripple_border_width(size);

    <motion.div
        className={cn("relative flex items-center justify-center text-foreground", container_cls, className)}
    >
        {for index in [0, 1, 2] {
            <motion.div
                key={str(index)}
                className={cn("absolute inset-0 rounded-full border-current bg-current/[0.03] opacity-0", border_w)}
                initial={{"scale": 0.1, "opacity": 0}}
                animate={{"scale": 1, "opacity": [0, 0.8, 0]}}
                transition={{"duration": 1.8, "repeat": float("inf"), "delay": index * 0.6, "ease": "easeOut"}}
            />
        }}
