import math;
import from "motion/react" { motion, AnimatePresence }

obj Spark {
    has angle: int;
    has distance: int;
    has delay: float;
}

glob sparks: list[Spark] = [
    Spark(angle=0, distance=28, delay=0),
    Spark(angle=60, distance=24, delay=0.04),
    Spark(angle=120, distance=30, delay=0.02),
    Spark(angle=180, distance=26, delay=0.06),
    Spark(angle=240, distance=28, delay=0.01),
    Spark(angle=300, distance=25, delay=0.05),
];

def spark_offset(spark: Spark) -> dict[str, float] {
    rad = (float(spark.angle) * math.pi) / 180.0;
    return {"x": math.cos(rad) * float(spark.distance), "y": math.sin(rad) * float(spark.distance)};
}

