import from "motion/react" { motion }
import from "lucide-react" { Star }
import from "@/lib/utils" { cn }

def SpinningText(
    text: str,
    radius: int = 50,
    fontSize: int = 12,
    speed: int = 10,
    direction: str = "normal",
    className: str = "",
    children: JsxElement | None = None,
) -> JsxElement {
    has isHovered: bool = False;

    characters = text.split("");
    totalChars = len(characters);
    angleStep = 360 / totalChars if totalChars > 0 else 360;

    def handle_mouse_enter(e: MouseEvent) {
        isHovered = True;
    }

    def handle_mouse_leave(e: MouseEvent) {
        isHovered = False;
    }

    <div
        className={cn("relative flex items-center justify-center", className)}
        onMouseEnter={handle_mouse_enter}
        onMouseLeave={handle_mouse_leave}
    >
        <motion.div
            animate={{"rotate": 360 if direction == "normal" else -360}}
            transition={{"duration": speed / 2 if isHovered else speed, "repeat": Infinity, "ease": "linear"}}
            className="relative flex items-center justify-center"
            style={{"width": radius * 2, "height": radius * 2}}
        >
            {for (i, char) in enumerate(characters) {
                <span
                    key={f"{i}-{char}"}
                    className="absolute left-1/2 top-0 font-medium uppercase tracking-tighter"
                    style={{
                        "height": radius,
                        "transform": f"translateX(-50%) rotate({i * angleStep}deg)",
                        "fontSize": fontSize,
                        "transformOrigin": f"center {radius}px",
                    }}
                >
                    {char}
                </span>
            }}
        </motion.div>
        <div className="absolute flex items-center justify-center">
            {children if children else <Star className="text-primary fill-primary" size={radius // 2} />}
        </div>
    </div>
}

