import from "@/config/registry/components/index" { components }
import from "@/components/blocks/utils" { categorizedBlocks }
import from "@/components/blocks/category/block/TopBlockInfo" { isNew }
import from "@/lib/utils" { cn }
import from "next/link" { default as Link }
import from "@/components/ui/badge" { Badge }
import from "@/components/ui/sidebar" { SidebarMenuSubItem }
import from "@/components/custom-components/ss-sidebar/sidebar-menu-button" { default as AppSidebarMenuButton }

obj SidebarItem {
    has url: str;
    has title: str;
    has icon: str | None = None;
    has blockName: str | None = None;
    has isNew: bool | None = None;
}

obj RegistryCategory {
    has name: str;
}

obj RegistryComponent {
    has category: RegistryCategory;
    has isNew: bool;
}

obj CategorizedBlock {
    has created_at: str | None = None;
}

def:pub AppSidebarMenuItem(item: SidebarItem, showFileCount: bool = False, props: dict[str, object] = {}) -> JsxElement {
    registryComponents = components as list[RegistryComponent];
    blocksMap = categorizedBlocks as dict[str, list[CategorizedBlock]];
    componentCount = 0;
    if item.blockName {
        componentCount = len([comp for comp in registryComponents if comp.category.name == item.blockName]);
    }
    blockCount = 0;
    if item.blockName and item.blockName in blocksMap {
        blockCount = len(blocksMap[item.blockName]);
    }
    isBlock = item.url.startswith("/blocks");
    fileCount = blockCount if isBlock else componentCount;
    categoryComponents: list[RegistryComponent] = [];
    if item.blockName {
        categoryComponents = [comp for comp in registryComponents if comp.category.name == item.blockName];
    }
    newComponentsCount = len([comp for comp in categoryComponents if comp.isNew]);
    categoryBlocks: list[CategorizedBlock] = [];
    if item.blockName and item.blockName in blocksMap {
        categoryBlocks = blocksMap[item.blockName];
    }
    newBlocksCount = len([block for block in categoryBlocks if block.created_at and isNew(block.created_at)]);
    totalNewCount = newBlocksCount if isBlock else newComponentsCount;
    <SidebarMenuSubItem {**props}>
        <AppSidebarMenuButton url={item.url} className={cn("group/menu-button gap-x-3")} tooltip={item.title}>
            <Link href={item.url} prefetch={False} className="flex items-center justify-between w-full py-2 duration-150 transform group-hover/menu-button:translate-x-1">
                <div className="flex items-center gap-2">
                    <span className="font-medium capitalize">{item.title}</span>
                    {if totalNewCount > 0 {
                        <Badge variant="default" className="text-xs rounded-sm font-medium px-1.5">+ {totalNewCount} New</Badge>
                    }}
                </div>
                {if showFileCount and fileCount {
                    <Badge className="py-0 px-1 min-w-[18px] inline-flex justify-center rounded-full bg-foreground/5" variant="outline">{fileCount}</Badge>
                }}
            </Link>
        </AppSidebarMenuButton>
    </SidebarMenuSubItem>
}

