import from "react" { useId }
import from "@/components/ui/label" { Label }
import from "@/components/ui/radio-group" { RadioGroup, RadioGroupItem }
import from "lucide-react" { SwatchBook, WandSparkles }

obj Plan {
    has value: str;
    has title: str;
    has description: str;
    has backgroundColor: str;
    has color: str;
}

glob plans: list[Plan] = [
    Plan(value="1", title="Brand Strategy", description="Perfect for individual creators.", backgroundColor="bg-blue-500/10", color="text-blue-500"),
    Plan(value="2", title="UX/UI Design", description="Built for collaboration and growing teams.", backgroundColor="bg-orange-400/10", color="text-orange-400"),
];

def planIcon(value: str, className: str) -> JsxElement {
    if value == "1" {
        return <SwatchBook className={className} />;
    }
    return <WandSparkles className={className} />;
}

def:pub RadioGroupCardVerticalDemo() -> JsxElement {
    id = useId();
    <RadioGroup
        defaultValue="1"
        className="w-full max-w-72 justify-items-center sm:grid-cols-2"
    >
        {for plan in plans {
            radioId = f"{id}-{plan.value}";
            <Label
                key={plan.value}
                htmlFor={radioId}
                className={"border-input cursor-pointer relative flex w-full max-w-44 flex-col items-center gap-3 rounded-md border p-5 shadow-xs transition " + plan.backgroundColor}
            >
                <div className="w-full flex flex-col justify-items-start gap-9 text-start">
                    <div className="w-full flex items-center justify-between gap-2">
                        {planIcon(plan.value, plan.color)}
                        <div className="bg-background p-px rounded-full">
                            <RadioGroupItem
                                id={radioId}
                                value={plan.value}
                                aria-describedby={f"{radioId}-description"}
                            />
                        </div>
                    </div>
                    <span className="text-base font-medium">{plan.title}</span>
                </div>
            </Label>
        }}
    </RadioGroup>
}

