            <div className="px-2 py-1">
                {for (index, file) in enumerate(files) {
                    iconClass = iconClassNames[file.type];
                    <div key={file.id}>
                        <div className="hover:bg-muted group grid cursor-pointer grid-cols-[1fr_auto_auto] items-center gap-2 rounded-lg px-2 py-2 transition-colors">
                            <div className="flex min-w-0 items-center gap-2.5">
                                {fileTypeIcon(file.type, "size-4 shrink-0 " + iconClass)}
                                <span className="min-w-0 truncate text-sm font-medium">{file.name}</span>
                                {if file.author == "you" {
                                    <Badge variant="outline" className="text-primary border-primary/30 hidden shrink-0 text-[10px] group-hover:inline-flex">you</Badge>
                                }}
                            </div>
                            <div className="w-16 text-center">
                                {if file.size {
                                    <Badge variant={badgeVariants[file.type]} className="text-[10px]">{file.size}</Badge>
                                } else {
                                    <span className="text-muted-foreground text-xs">—</span>
                                }}
                            </div>
                            <span className="text-muted-foreground w-24 shrink-0 text-right text-xs">{file.modified}</span>
                        </div>
                        {if index < len(files) - 1 {
                            <div className="bg-border/50 mx-2 h-px" />
                        }}
                    </div>
                }}
            </div>
        </ScrollArea>
        <div className="bg-muted/40 text-muted-foreground flex items-center justify-between border-t px-4 py-2 text-xs">
            <span>Last synced just now</span>
            <span>↑ 3 pending uploads</span>
        </div>
    </div>
}

