import from "@radix-ui/react-toggle" { * as TogglePrimitive }
import from "@/lib/utils" { cn }

def:pub toggleVariants(options: dict[str, str] = {}) -> str {
    variant = options["variant"] if "variant" in options else "default";
    size = options["size"] if "size" in options else "default";
    className = options["className"] if "className" in options else "";
    base = "inline-flex items-center justify-center gap-2 rounded-md text-sm font-medium hover:bg-muted hover:text-muted-foreground disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground [&_svg]:pointer-events-none [&_svg:not([class*='size-'])]:size-4 [&_svg]:shrink-0 focus-visible:border-ring focus-visible:ring-ring/50 focus-visible:ring-[3px] outline-none transition-[color,box-shadow] aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive whitespace-nowrap";
    variant_map: dict[str, str] = {
        "default": "bg-transparent",
        "outline": "border border-input bg-transparent shadow-xs hover:bg-accent hover:text-muted-foreground",
    };
    size_map: dict[str, str] = {
        "default": "h-9 px-2 min-w-9",
        "sm": "h-8 px-1.5 min-w-8",
        "lg": "h-10 px-2.5 min-w-10",
    };
    return cn(base, variant_map.get(variant, variant_map["default"]), size_map.get(size, size_map["default"]), className);
}

def:pub Toggle(
    className: str = "",
    variant: str = "default",
    size: str = "default",
    props: dict[str, object] = {}
) -> JsxElement {
    <TogglePrimitive.Root
        data-slot="toggle"
        className={cn(toggleVariants({"variant": variant, "size": size, "className": className}))}
        {**props}
    />
}

