import json;
import from pathlib { Path }
import from store.subscriptionStore { defaultSubscriptions }

glob CONFIG_FILE: str = str(Path.cwd() / "data" / "config.json");

async def readConfig() -> dict[str, object] {
    try {
        data = Path(CONFIG_FILE).read_text(encoding="utf-8");
        return json.loads(data) as dict[str, object];
    } except FileNotFoundError {
        return {};
    } except Exception as e {
        print(f"Error reading config file: {str(e)}");
        return {};
    }
}

async def writeConfig(config: dict[str, object]) {
    try {
        Path(CONFIG_FILE).write_text(json.dumps(config, indent=2), encoding="utf-8");
    } except Exception as e {
        print(f"Error writing config file: {str(e)}");
    }
}

async def:pub loader(params: dict[str, str]) -> dict[str, object] {
    try {
        config = await readConfig();
        key = params.get("key");
        if key is None {
            return {"error": "Key is undefined", "status": 400};
        }
        if key not in config and key == "subscription-storage" {
            return {"value": {"state": {"subscriptions": defaultSubscriptions}}};
        }
        value = config.get(key);
        return {"value": value if value is not None else None};
    } except Exception as e {
        print(f"Loader error: {str(e)}");
        return {"value": None};
    }
}

async def:pub action(method: str, params: dict[str, str], body: dict[str, object] | None) -> dict[str, object] {
    try {
        key = params.get("key");
        config = await readConfig();

        if key is None {
            return {"error": "Key is undefined", "status": 400};
        }

        if method == "PUT" {
            if body is None or "value" not in body {
                return {"error": "Missing value", "status": 400};
            }
            config[key] = body["value"];
            await writeConfig(config);
            return {"success": True};
        }

        if method == "DELETE" {
            config.pop(key, None);
            await writeConfig(config);
            return {"success": True};
        }

        return {"error": "Method not allowed", "status": 405};
    } except Exception as e {
        print(f"Action error: {str(e)}");
        return {"error": "Internal Server Error", "status": 500};
    }
}

