obj Metadata {
    has title: str | None = None;
    has description: str | None = None;
    has openGraph: OpenGraph | None = None;
    has authors: list[Author] = [];
    has manifest: str | None = None;
}

def _defaultOpenGraph(metadata: Metadata) -> OpenGraph {
    title: str = metadata.title or "";
    description: str = metadata.description or "";
    siteName: str = "Shadcn Space";
    ogType: str = "website";
    images: list[OpenGraphImage] = [
        OpenGraphImage(
            url="/images/og-image.png",
            height=630,
            width=1200,
            alt="Customized Shadcn Space & Components"
        )
    ];
    locale: str = "en_US";
    if metadata.openGraph is not None {
        if metadata.openGraph.title is not None {
            title = metadata.openGraph.title;
        }
        if metadata.openGraph.description is not None {
            description = metadata.openGraph.description;
        }
        if metadata.openGraph.siteName is not None {
            siteName = metadata.openGraph.siteName;
        }
        if metadata.openGraph.type is not None {
            ogType = metadata.openGraph.type;
        }
        if metadata.openGraph.images {
            images = metadata.openGraph.images;
        }
        if metadata.openGraph.locale is not None {
            locale = metadata.openGraph.locale;
        }
    }
    return OpenGraph(
        title=title,
        description=description,
        siteName=siteName,
        type=ogType,
        images=images,
        locale=locale
    );
}

def constructMetadata(metadata: Metadata) -> Metadata {
    result = Metadata(
        title=metadata.title,
        description=metadata.description,
        openGraph=_defaultOpenGraph(metadata),
        authors=[Author(name="Shadcn Space", url="https://twitter.com/")],
        manifest="/site.webmanifest"
    );
    if metadata.title is not None {
        result.title = metadata.title;
    }
    if metadata.description is not None {
        result.description = metadata.description;
    }
    if metadata.openGraph is not None {
        result.openGraph = metadata.openGraph;
    }
    if metadata.authors {
        result.authors = metadata.authors;
    }
    if metadata.manifest is not None {
        result.manifest = metadata.manifest;
    }
    return result;
}

